INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (6, 5, 4, 'Junior Backend Developer', false, 'Design and implement robust microservices patterns, maintain API gateways, write comprehensive unit tests, and collaborate with open-source project documentation streams. BSc in Computer Science or equivalent engineering field required.', 'Colombo 03, Sri Lanka', '2026-06-19 06:35:11.682514+00', '2026-06-19 06:35:11.682514+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (7, 6, 4, 'Staff Nurse', false, 'Provide direct patient care in the general ward, administer medications as prescribed, maintain accurate patient records, and coordinate with the medical team for treatment plans. Minimum 2 years of clinical experience required.', 'Kandy, Sri Lanka', '2026-06-19 06:35:11.789309+00', '2026-06-19 06:35:11.789309+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (8, 7, 4, 'Production Supervisor', false, 'Oversee daily production line operations, ensure quality control standards are met, manage a team of 20+ floor workers, and report production metrics to the plant manager. Experience in garment manufacturing is essential.', 'Gampaha, Sri Lanka', '2026-06-19 06:35:11.814341+00', '2026-06-19 06:35:11.814341+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (9, 8, 4, 'Operations Coordinator', false, 'We are looking for a detail-oriented Operations Coordinator to manage supply chain documentation and warehouse schedules. Responsibilities include tracking shipments, communicating with logistics partners, and maintaining inventory records. Candidates must possess strong organizational skills and familiarity with warehouse management software.', 'Gampaha, Sri Lanka', '2026-06-22 09:32:15.552712+00', '2026-06-22 09:32:15.552712+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (10, 9, 4, 'Admin Assistant - Female', false, 'Admin Assistant role at Trans Interior & Signage (Pvt) Ltd. Please go through the attached image. Please share your CV via WhatsApp, as it is mandatory.', 'Wellampitiya, Colombo, Sri Lanka', '2026-06-23 09:03:49.069198+00', '2026-06-23 09:03:49.069198+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (11, 10, 4, 'Assistant Pharmacist', false, 'Minimum 1 year of experience working in a similar role. Must be able to read prescriptions well. Should have some knowledge in stock handling, expiry handling. Must willing to work from 7am to 5pm.', 'Gampaha City, Gampaha, Sri Lanka', '2026-06-23 09:03:49.195204+00', '2026-06-23 09:03:49.195204+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (12, 11, 4, 'Assistant Manager', false, 'We are looking for a motivated and responsible Assistant Manager to join our team. Requirements: Minimum 1 years of experience in a similar role. Strong leadership and communication skills. Ability to work independently and manage daily operations. Age between 25–45 years. Responsibilities: Assist in managing day-to-day business operations. Supervise staff and ensure smooth workflow. Prepare reports and maintain records. Coordinate with customers, suppliers, and management. Support business growth and operational efficiency. Salary: Negotiable based on qualifications and experience.', 'Avissawella, Colombo', '2026-06-23 09:03:49.224723+00', '2026-06-23 09:03:49.224723+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (13, 12, 4, 'Accounts Executive - Male', false, 'Bachelor''s degree in Accounting, Finance or in the related field. Professional qualifications (CA/ACCA/CIMA or equivalent). Preparing Tax returns (Income Tax, VAT, WHT, APIT). 3-5 years working experience. Experience with QuickBooks, MYOB, Xero. Excellent attention to detail and management.', 'Galle City, Galle, Sri Lanka', '2026-06-23 09:03:49.305869+00', '2026-06-23 09:03:49.305869+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (14, 13, 4, 'Assistant Clerk', false, 'Vacancy Asst Clerk PERFETTI MELLE LANKA (PVT) LTD Center Fresh consumer Product Distribution - Badulla Asst. Clerk (Female). We are inviting applications from suitable and enthusiastic candidates for the position of Distribution Asst.Clerk at our organization. Requirements: Age between 20 – 35 years, Passed G.C.E. Advanced Level Examination, Basic computer knowledge will be an added advantage. Priority will be given to candidates residing in the Badulla / Haliela area. Working Hours: 8.00 a.m. – 4.00 p.m. Monthly Salary: Rs. 18,000/- to 40,000/- With EPF ETF.', 'Badulla City, Badulla, Sri Lanka', '2026-06-23 09:03:49.322179+00', '2026-06-23 09:03:49.322179+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (15, 14, 4, 'Baby Sitter', false, 'නිවසේ නැවතී සිට ළමයන් බලා ගැනීමට කාන්තාවක් අවශ්‍යයි. වයස අඩු අය විශේෂයි. රාත්‍රි 8න් පසු අමතන්න./call කරන්න. මෙම නම්බරයට විස්තර whatsapp කරලා තියන්න නම/වයස/ සිංහල /දෙමල 0702993647', 'Panadura, Kalutara', '2026-06-23 09:03:49.338081+00', '2026-06-23 09:03:49.338081+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (16, 15, 4, 'Admin Assistant', false, 'We are seeking a responsible and dedicated admin assistant to join our team. Key Responsibilities: Organize daily documents, Maintain and manage all administrative documents, Administrative documents are properly filed and maintained. Requirements: Basic Pass of O/Levels, IT basic skills (MS Office, Email handling). With or without working experience will be accepted. Training will be provided. School leavers looking for a steady job can apply, no experience needed.', 'Ratmalana, Colombo', '2026-06-23 09:03:49.348327+00', '2026-06-23 09:03:49.348327+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (17, 16, 4, 'Cashier (Male) - Colombo 06', false, 'Requirements: Age between 18 and 40. Ability to work with friends at the same location. Ability to work in groups. Full shave is mandatory. O/L Mathematics with S pass or cashier experience. 12-hour shifts (including 3 hours OT). Benefits: High salary + OT, Free food/accommodation, Life insurance, Permanent employment from day one, Promotions after 6 months. Required documents for interview: Copy of National Identity Card, Copy of Birth Certificate, Copy of Bank Passbook, Copy or original Grama Niladhari certificate, Copy of O/L certificate, Pen for writing.', 'Colombo 6, Sri Lanka', '2026-06-23 09:03:49.36819+00', '2026-06-23 09:03:49.36819+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (18, 17, 4, 'Grill Chef', false, 'We are looking for a talented Grill chef to join our dynamic kitchen team in Colombo 3. If you''re ready to inspire, innovate, and elevate, we want you to shape the future of our kitchen. The ideal candidate can be someone with great experience, with a passion for spice based cuisine. You will thrive in an environment where attention to detail is high and you''ll have a passion for culinary creativity, and are committed to delivering exceptional dining experiences. Key Responsibilities: Hands-on approach with a passion for active involvement in kitchen operations. Innovative mindset with a track record of contributing creative menu ideas. Ability to maintain a creative, visually appealing, and high-quality culinary offer. Commitment to using only premium ingredients, with no compromises on quality. Strong attention to detail paired with efficient workflow management. Experience in maintaining a smooth, clean, and professional kitchen environment. Leadership by example, setting high standards for the team. Qualifications & Skills: Formal culinary education and 3–5 years of professional kitchen experience. Creative, enthusiastic, and dedicated to delighting guests with exceptional experiences. Knowledgeable about current food trends, dietary restrictions, culinary techniques, and execution. Strong understanding of hygiene and food safety standards. Collaborative team player who works seamlessly across departments. Enjoys building relationships with a close-knit team and loyal guests.', 'Colombo 3, Sri Lanka', '2026-06-23 09:03:49.38689+00', '2026-06-23 09:03:49.38689+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (28, 25, 5, 'Online Data Entry / Typing - Part Time | (Works from Homes)', true, 'Work From Home Working Community. Sri Lankan Projects. Data Entry Works, Online Data Submit, Copy Typing, Simple Typing. Qualifications: Basic computer knowledge, ability to use email, any gender, anyone across the island can join. Can work from computer, laptop, or smartphone. Minimum 1 hour per day. Suitable for employed persons, unemployed, housewives, school leavers, university students, anyone seeking extra income. Benefits: Full Sinhala or English Guidelines, Daily job options (Typing, Simple Data Submits, Data Entry), Work from home any time, Withdraw money via eZ Cash/Bank deposit, 24hr support, Lifetime access.', 'Malabe, Colombo', '2026-06-23 09:03:49.542241+00', '2026-06-23 09:03:49.542241+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (19, 17, 4, 'In House Videographer', false, 'We''re looking for a talented Photographer/Videographer + Editor to join our team and bring our signature content to life. Under the guidance of our Creative Director, you''ll be responsible for shooting + editing short form, multi-camera photographs and videos, ensuring they align with the Open Door Policy style and storytelling. Key Responsibilities: Shoot and edit short-form, multi-camera videos for social channels, Work closely with the Creative Director to execute the vision of each brief, Maintain high attention to detail, ensuring seamless edits and engaging storytelling, Meet consistent deadlines while keeping the brand''s style and quality intact. Requirements: Proven experience editing how-to videos and multi-camera shoots, Expertise in Adobe + other editing software, Strong sense of storytelling, pacing, and attention to detail, Ability to take creative feedback and work collaboratively. Why Join Us? Be part of an ambitious and creative environment in a top Colombo restaurant, Opportunity to learn and develop under an experienced creative team.', 'Colombo 3, Sri Lanka', '2026-06-23 09:03:49.404289+00', '2026-06-23 09:03:49.404289+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (20, 18, 4, 'Juki Machine Operator', false, 'Sewing Machine Operator position at Madhumali Fashion located in Gampola Hinnarangadeniya. Responsibilities include operating sewing machines. Qualifications: Ordinary Level education, 1 year of work experience required. Benefits: Salary Rs 38,000 - 55,000 per month.', 'Gampola, Kandy, Sri Lanka', '2026-06-23 09:03:49.418726+00', '2026-06-23 09:03:49.418726+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (21, 19, 4, 'මැණික් කැපීමේ ශිල්පිනියන් – අකුරණ', false, 'ගැහැණු ළමුන් සඳහා නොමිලේ මැණික් කැපීමේ වෘත්තීය පුහුණුව ලබා දෙන අතර, පුහුණුව සාර්ථකව අවසන් කරන අයට ඉහළ වැටුපක් සහිත ස්ථිර රැකියාවක් ලබා දේ. අවශ්‍ය සුදුසුකම්: කාන්තා අයදුම්කරුවන් වයස අවුරුදු 18 සිට 25 දක්වා Akurana සහ ඒ අවට ප්‍රදේශවල පදිංචි අය. වටිනා වෘත්තීය කුසලතාවයක් ඉගෙන ගනිමින් මැණික් කර්මාන්තයේ සාර්ථක වෘත්තියක් ගොඩනඟා ගැනීමට කැමති අය සඳහා.', 'Akurana, Kandy, Sri Lanka', '2026-06-23 09:03:49.428554+00', '2026-06-23 09:03:49.428554+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (22, 20, 4, 'Office Assistant', false, 'Assist the Procurement Department with daily operational tasks. Travel to suppliers and vendors to purchase required items. Assist with receiving, checking, and organizing stock and supplies. Help move materials and equipment between locations. Support inventory and store-related activities. Qualifications: Good communication and interpersonal skills. Ability to work independently and follow instructions. Honest, responsible, and trustworthy. Physically fit and willing to handle light lifting and movement of goods. Prior experience in procurement, stores, logistics, or office support is an added advantage. Valid motorcycle riding license (preferred). Able to commute to and from work (Colombo 03). Salary and Benefits: Basic salary. Attractive package incentives. Overtime included (OT). Full-time job earns up to: LKR 50,000 - LKR 60,000 per month.', 'Colombo 3, Sri Lanka', '2026-06-23 09:03:49.451329+00', '2026-06-23 09:03:49.451329+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (23, 21, 4, 'Hardware Technician', false, 'Perfect IT Solutions is seeking an enthusiastic Computer Hardware Technician to join our team. This opportunity for those with IT Support & Hardware troubleshooting. Age between 20-30. No need experience. Requirements: 1. Need Bike License. 2. Provide support and troubleshooting for desktops, laptops, operating systems and applications. 3. Install, configure and maintain hardware and software. 4. Assist in deploying and maintaining IT services. Benefits: Attractive salary and many other benefits.', 'Kadawatha, Gampaha, Sri Lanka', '2026-06-23 09:03:49.470948+00', '2026-06-23 09:03:49.470948+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (24, 22, 4, 'Office Assistant', false, 'We are seeking a dedicated and organized Office Assistant to join our team. Requirements: Age between 20 – 40 years, Minimum 1 year of office work experience, Good communication and organizational skills, Basic knowledge of MS Office (Word, Excel, Email), Ability to work independently and as part of a team. Responsibilities: Handle daily office administrative tasks, Maintain files and records, Assist with data entry and document preparation, Answer phone calls and respond to emails, Support office staff and management as required. Salary: Negotiable based on qualifications and experience.', 'Battaramulla, Colombo, Sri Lanka', '2026-06-23 09:03:49.490293+00', '2026-06-23 09:03:49.490293+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (25, 23, 4, 'Office Supervisor', false, 'ඔබත් රැකියාවක් අපේක්ෂාවෙන් සිටින අයෙක්ද..? දිවයිනෙ සෑම දිස්ත්‍රික්කයක්ම ආවරණය වන පරිදි අප ආයතනයේ නව ශාඛාවන් 12 ක කඩිනම් පුරප්පාඩු සදහා ආධුනිකයින් පුහුනු කර බදවා ගැනේ. රැකියාව: සුපරීක්ෂක. පුහුනු කාලය තුල:- 40000 - 45000 අතර දීමනා, සෞඛ්‍ය ආවරණයක්, නවාතැන් පහසුකම් හා ආහාර පාන, කෙටිකාලීන උසස් වීම. පුහුනුවෙන් පසුව: 75000 මූලික වැටුපක්, ETF, EPF ඇතුලු වරප්‍රසාද, ජීවිත රක්ෂණ ආවරණයක්, විදෙස් සංචාර.', 'Kurunegala City, Kurunegala, Sri Lanka', '2026-06-23 09:03:49.501732+00', '2026-06-23 09:03:49.501732+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (26, 24, 4, 'Light vehicle Driver', false, 'We are searching for Driver to join our company. Requirements: Residing near Homagama, Pannipitiya, Kottawa, Maharagama, and Piliyanadala areas. Age 20-50 years. GEC O/ls. Valid driving license. Male. Benefits: Salary + OT. Please send your CV to bhumina.kothalawala@isiramedical.com or WhatsApp 0701083839.', 'Pannipitiya, Colombo', '2026-06-23 09:03:49.512067+00', '2026-06-23 09:03:49.512067+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (27, 17, 4, 'In House Photographer', false, 'We’re looking for a talented Photographer/Videographer + Editor to join our team and bring our signature content to life. Under the guidance of our Creative Director, you’ll be responsible for shooting + editing short form, multi-camera photographs and videos, ensuring they align with the Open Door Policy style and storytelling. Key Responsibilities: Shoot and edit short-form, multi-camera videos for social channels, Work closely with the Creative Director to execute the vision of each brief, Maintain high attention to detail, ensuring seamless edits and engaging storytelling, Meet consistent deadlines while keeping the brand’s style and quality intact. Requirements: Proven experience editing how-to videos and multi-camera shoots, Expertise in Adobe + other editing software, Strong sense of storytelling, pacing, and attention to detail, Ability to take creative feedback and work collaboratively. Why Join Us? Be part of an ambitious and creative environment in a top Colombo restaurant, Opportunity to learn and develop under an experienced creative team.', 'Colombo 3, Sri Lanka', '2026-06-23 09:03:49.523713+00', '2026-06-23 09:03:49.523713+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (193, 145, 4, 'Delivery Rider', false, 'We are hiring Join E-Dine Services as a Delivery Rider. Ideal for individuals seeking independence, steady income, and growth opportunities.', 'Colombo 8, Sri Lanka', '2026-06-23 17:15:25.803782+00', '2026-06-23 17:15:25.803782+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (29, 26, 4, 'Sous Chef', false, 'We are looking for a talented Senior Sous or Sous Chef to join our dynamic kitchen team in Colombo 3. If you''re ready to inspire, innovate, and elevate, we want you to shape the future of our kitchen. The ideal candidate can be someone with great experience, with a passion for spice based cuisine. You will thrive in an environment where attention to detail is high and you''ll have a passion for culinary creativity, and are committed to delivering exceptional dining experiences. Key Responsibilities: Hands-on approach with a passion for active involvement in kitchen operations. Innovative mindset with a track record of contributing creative menu ideas. Ability to maintain a creative, visually appealing, and high-quality culinary offer. Commitment to using only premium ingredients, with no compromises on quality. Strong attention to detail paired with efficient workflow management. Experience in maintaining a smooth, clean, and professional kitchen environment. Leadership by example, setting high standards for the team. Qualifications & Skills: Formal culinary education and 3–5 years of professional kitchen experience. Creative, enthusiastic, and dedicated to delighting guests with exceptional experiences. Knowledgeable about current food trends, dietary restrictions, culinary techniques, and execution. Strong understanding of hygiene and food safety standards. Collaborative team player who works seamlessly across departments. Enjoys building relationships with a close-knit team and loyal guests.', 'Colombo 3, Sri Lanka', '2026-06-23 09:03:49.573092+00', '2026-06-23 09:03:49.573092+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (30, 27, 5, 'Teacher Female- Battaramulla', false, 'We are looking for a young female who can engage in activities (playing, dancing and etc) with our daughter who has special educational needs during weekday evenings. Requirements: Female, aged between 18 and 25 years. Energetic, patient, and kind-hearted. Good English communication skills are a must. Available to visit our home between 5:00 PM and 7:00 PM on weekdays. Experience or knowledge in dancing, special education, early childhood education, or preschool teaching will be an added advantage.', 'Battaramulla, Colombo', '2026-06-23 09:03:49.594716+00', '2026-06-23 09:03:49.594716+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (31, 28, 4, 'Sales Executive', false, 'We are looking for enthusiastic and customer-oriented Sales Executives to be part of our growing fashion family. If you have a passion for fashion, love interacting with people, and have a drive to achieve targets, we would love to hear from you. Key responsibilities: Welcome and assist customers in a friendly and professional manner, understand customer needs and recommend suitable products, achieve individual sales targets and contribute to store goals, maintain product knowledge and stay updated on new arrivals and promotions, ensure attractive presentation of products and store cleanliness, handle billing, payments, and returns efficiently, build and maintain strong customer relationships, provide excellent customer service and ensure customer satisfaction. Requirements: Previous experience in sales or customer service is an added advantage, good communication and interpersonal skills, pleasant personality with a positive attitude, passion for fashion and helping customers, ability to work flexible hours including weekends and holidays, basic knowledge of computer operations will be an advantage, ability to work in a team and under pressure to achieve targets.', 'Boralesgamuwa, Colombo', '2026-06-23 09:03:49.60918+00', '2026-06-23 09:03:49.60918+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (32, 17, 4, 'Senior Chef', false, 'We Are Looking for A Talented Senior Sous or Sous Chef to Join Our Dynamic Kitchen Team in Colombo 3. if You''re Ready to Inspire, Innovate, and Elevate, We Want You to Shape the Future of Our Kitchen. the Ideal Candidate Can Be Someone with Great Experience, with A Passion for Spice Based Cuisine. You Will Thrive in An Environment Where Attention to Detail Is High and You''ll Have a Passion for Culinary Creativity, and Are Committed to Delivering Exceptional Dining Experiences. Key Responsibilities: Hands-On Approach with A Passion for Active Involvement in Kitchen Operations. Innovative Mindset with A Track Record of Contributing Creative Menu Ideas. Ability to Maintain a Creative, Visually Appealing, and High-Quality Culinary Offer. Commitment to Using only Premium Ingredients, with No Compromises on Quality. Strong Attention to Detail Paired with Efficient Workflow Management. Experience in Maintaining a Smooth, Clean, and Professional Kitchen Environment. Leadership by Example, Setting High Standards for The Team. Qualifications & Skills: Formal Culinary Education and 3–5 Years of Professional Kitchen Experience. Creative, Enthusiastic, and Dedicated to Delighting Guests with Exceptional Experiences. Knowledgeable About Current Food Trends, Dietary Restrictions, Culinary Techniques, and Execution. Strong Understanding of Hygiene and Food Safety Standards. Collaborative Team Player Who Works Seamlessly Across Departments. Enjoys Building Relationships with A Close-Knit Team and Loyal Guests.', 'Colombo 3, Sri Lanka', '2026-06-23 09:03:49.620951+00', '2026-06-23 09:03:49.620951+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (33, 29, 4, 'Supervisor', false, 'Aqua Life (Pvt) Ltd is hiring supervisors and other positions. Training provided for newcomers. Requirements: O/L or A/L passed, age 25-45. Benefits: Rs 55,000 during training, Rs 125,000+ after training, quick promotions, foreign trips. Eligible areas: Kiribathgoda, Wattala, Kadawatha, Kandana, Ja-Ela. Apply if you have a friendly personality, independent and open mindset. Call 0724442164 for interview appointment.', 'Wattala, Gampaha, Sri Lanka', '2026-06-23 09:03:49.630457+00', '2026-06-23 09:03:49.630457+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (34, 14, 4, 'Room Boy', false, 'An experienced all-round room boy and butler/caretaker or chef/cook with experience in cooking for foreign guests are urgently wanted to work in boutique hotel in Kandy. Attractive salary, food and lodging.', 'Kandy City, Kandy, Sri Lanka', '2026-06-23 09:03:49.644387+00', '2026-06-23 09:03:49.644387+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (35, 30, 4, 'Warehouse Assistant', false, 'පමුණුගම පිහිටි ඇගලුම් බෙදා හැරීමේ අප ආයතනයේ Warehouse එක සඳහා Warehouse Assistant තනතුර සඳහා පිරිමි අයවලුන්ට රැකියා අවස්ථාවන්. ඔබට අපෙන් ලැබෙන ප්‍රතිලාභ: නිල ඇදුම් සහ ආරක්ශිත පාවහන්, ප්‍රවාහන දීමනා, ආකර්ශනීය වැටුප් (70,000 වැඩි), සුවපහසු වැඩ බිම, රක්ෂණ දීමනා, අතිකාල දීමනා. ඔබට තිබිය යුතු සුදුසුකම්: අපොස සාපෙල සමත් වීම හෝ පෙනී සිටීම, පුහුණු හෝ නුපුහුණු බව, කණ්ඩායම් ලෙස රැකියාව කිරීමේ හැකියාව.', 'Ja-Ela, Gampaha', '2026-06-23 09:03:49.652575+00', '2026-06-23 09:03:49.652575+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (36, 31, 4, 'Crew Member', false, 'කොළඹ කොටුව පොත් හලකට ගැහැණු සහ පිරිමි පුහුණු/ නුපුහුණු සේවකයින් අවශ්‍ය කර තිබේ. වයස අවුරුදු 25 ත් 35 ත් අතර. මෝටර් සයිකල් බලපත්‍රය තිබීම අමතර සුදුසුකමක් සේ සැලකේ.', 'Maharagama, Colombo', '2026-06-23 09:03:49.659891+00', '2026-06-23 09:03:49.659891+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (170, 127, 4, 'Call Center Executive', false, 'Call Center Executive position in Colombo. Salary Rs 65,000 - 70,000 per month. Requires Ordinary Level education. No prior work experience required. Branches available in Nawała, Nugegoda, Maharagama, Kottawa, Homagama, Pitakotuwa, Bambalapitiya, Kollupitiya, Boralesgamuwa. Contact via WhatsApp at 0776962219 for details. Interviews conducted daily until 30 vacancies are filled.', 'Colombo, Sri Lanka', '2026-06-23 17:09:09.048877+00', '2026-06-23 17:09:09.048877+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (37, 32, 4, 'Team Leader''s Manager - Matara', false, 'Professional Wealth Planner. Opportunity to join the world''s largest company. Leading global career, rapid income growth with professional competence, financial freedom and time freedom, promotions with professional excellence, local and international recognition, local and foreign travel opportunities. Suitable for those with good social networks, professional connections, trustworthiness in society, willing to achieve professional goals through commitment. Experienced in financial services, marketing, banking services, insurance services.', 'Matara City, Matara, Sri Lanka', '2026-06-23 09:03:49.677652+00', '2026-06-23 09:03:49.677652+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (38, 33, 5, 'Online Data Entry Typing - Part Time (Works from Homes)', true, 'Data Entry Typing, Online Data Submit, Copy Typing, Simple Typing. Work from home. Sri Lankan Projects. Requires basic computer knowledge and email usage ability. Suitable for anyone including employed, unemployed, housewives, school leavers, university students. Full Sinhala or English Guidelines provided. Daily job options. Withdraw money via eZ Cash / Bank deposit. 24/7 support. Lifetime access. 15 minutes to start work.', 'Kandy City, Kandy, Sri Lanka', '2026-06-23 09:03:49.697546+00', '2026-06-23 09:03:49.697546+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (39, 34, 4, 'Sales Support Coordinator', false, 'Coordinate and support day-to-day sales operations. Process sales orders and ensure timely follow-up with relevant departments. Maintain and update customer records, sales databases, and reports. Assist the Sales Team in preparing presentations, reports, and marketing materials. Support the preparation of sales forecasts and performance reports. Ensure proper filing and maintenance of sales-related documents. Requirements: Diploma or Degree in Business Administration, Marketing, Management, or a related field. Minimum 1–2 years of experience in sales coordination, administration, or a similar role. Strong communication and interpersonal skills. Excellent organizational and multitasking abilities. Proficiency in Microsoft Office applications. Experience with ERP systems will be an added advantage. Ability to work independently and meet deadlines.', 'Kalubowila, Colombo', '2026-06-23 09:03:49.71277+00', '2026-06-23 09:03:49.71277+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (40, 17, 4, 'Photographer', false, 'We’re looking for a talented Photographer/Videographer + Editor to join our team and bring our signature content to life. Under the guidance of our Creative Director, you’ll be responsible for shooting + editing short form, multi-camera photographs and videos, ensuring they align with the Open Door Policy style and storytelling. You’re an experienced photographer and videographer with a passion for high-quality storytelling/how-to content. You have a keen eye for detail, pacing, and visual storytelling, and you thrive in a fast-paced, creative environment. While this role is primarily on-site, there is some flexibility for remote work—as long as deadlines are met. Key Responsibilities: Shoot and edit short-form, multi-camera videos for social channels, Work closely with the Creative Director to execute the vision of each brief, Maintain high attention to detail, ensuring seamless edits and engaging storytelling, Meet consistent deadlines while keeping the brand’s style and quality intact. Requirements: Proven experience editing how-to videos and multi-camera shoots, Expertise in Adobe + other editing software, Strong sense of storytelling, pacing, and attention to detail, Ability to take creative feedback and work collaboratively. Why Join Us? Be part of an ambitious and creative environment in a top Colombo restaurant, Opportunity to learn and develop under an experienced creative team.', 'Colombo 3, Sri Lanka', '2026-06-23 09:03:49.723032+00', '2026-06-23 09:03:49.723032+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (41, 35, 4, 'පුහුණු / නුපුහුණු CCTV කාර්මික ශිල්පීන්', false, 'නවාතැන් / ETF EPF / රක්ෂණ / OT සහා අනෙකුත් දීමනා. පළපුරුද්දක් නොමැති අයටද අයදුම් කළ හැකිය. අමතන්න.', 'Piliyandala, Colombo', '2026-06-23 09:03:49.73919+00', '2026-06-23 09:03:49.73919+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (42, 36, 5, 'Private Lifestyle Manager (Part-Time)', false, 'I am looking for a mature, responsible, and professional Private Lifestyle Manager to assist with my daily routines and personal organization. Responsibilities: Remind me of appointments, meetings, and schedules; Help manage daily tasks and routines; Remind me about diet plans, exercise, and healthy habits; Accompany me to meetings, errands, or work-related activities when required; Assist with personal planning and time management. Requirements: Preferably 25 years old or above; Well-organized and reliable; Good communication skills; Professional, trustworthy, and punctual. Work Schedule: Approximately 3 days per week; Flexible schedule, but must be available for a full day when requested in advance.', 'Colombo 3, Sri Lanka', '2026-06-23 09:03:49.751194+00', '2026-06-23 09:03:49.751194+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (43, 37, 4, 'Restuarant Waiter', false, 'මහනුවර ප්‍රදානපෙලේ ආපනශාලාවක් සඳහා වේටර්වරුන් අවශ්‍ය කර තිබේ.. ඔබත් වයස අවු 18 - 25 ත් අතර නම් සාමන්‍ය ඉංග්‍රීසි කථන හැකියාව ඇත්නම් නවාතැන් පහසුකම් , ආහාරපාන සමග ඉහළ වැටුප් හා දීමනා සමග ඔබත් අප හා එක්වන්න', 'Kandy City, Kandy', '2026-06-23 09:03:49.761087+00', '2026-06-23 09:03:49.761087+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (44, 26, 4, 'Social Media Creator', false, 'IN HOUSE CREATIVE ROLE: We''re looking for a talented Social Media Executive/Manager who is also a Photographer/Videographer + Editor to join our team and bring our signature content to life. Under the guidance of our Creative Director, you''ll be responsible for shooting + editing short form, multi-camera photographs and videos, ensuring they align with the Open Door Policy style and storytelling. You''re an experienced photographer and videographer with a passion for high-quality storytelling/how-to content. You have a keen eye for detail, pacing, and visual storytelling, and you thrive in a fast-paced, creative environment. Key Responsibilities: Shoot and edit short-form, multi-camera videos for social channels, Work closely with the Creative Director to execute the vision of each brief, Maintain high attention to detail, ensuring seamless edits and engaging storytelling, Meet consistent deadlines while keeping the brand''s style and quality intact. Requirements: Proven experience editing how-to videos and multi-camera shoots, Expertise in Adobe + other editing software, Strong sense of storytelling, pacing, and attention to detail, Ability to take creative feedback and work collaboratively. Why Join Us? Be part of an ambitious and creative environment in a top Colombo restaurant, Opportunity to learn and develop under an experienced creative team.', 'Colombo 3, Sri Lanka', '2026-06-23 09:03:49.771791+00', '2026-06-23 09:03:49.771791+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (45, 38, 4, 'Stores Helper - (Male) Nugegoda', false, 'Support unloading, loading and arranging goods in the warehouse. Must be able to assist with delivery tasks when needed. Must be enthusiastic, responsible and able to work as a team. Priority given to those who can reside at the company premises. Benefits include free food, free accommodation, EPF and ETF benefits.', 'Colombo 6, Sri Lanka', '2026-06-23 09:03:49.785551+00', '2026-06-23 09:03:49.785551+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (278, 195, 4, 'Sales Executive (Male)', false, 'We are looking for a dynamic and motivated Sales Executive to join our growing lighting showroom. Requirements: Male candidates (Age 18 – 35). Sales experience will be an added advantage. Benefits: Attractive salary package, additional incentives, commission on sales – earn more with performance. Working Hours: 9:30 AM – 6:30 PM. Sundays & Mercantile Holidays OFF.', 'Colombo 11, Sri Lanka', '2026-06-23 17:39:28.056623+00', '2026-06-23 17:39:28.056623+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (46, 39, 4, 'පිරිසිදු කිරීමේ මහත්මීන් - කොහුවල', false, 'තනතුර : පිරිසිදු කිරීමේ මහත්මීන් - කොහුවල. ස්ථානය : කොහුවල. සේවා කාලය - උදේ 7.00 - සවස 4.00. සුදුසුකම් : වයස අවුරුදු 25ත් - 58 ත් අතර ගැහැණු පිරිමි පිරිසිදු කිරීමේ මහත්මීන් බඳවා ගැනේ. ප්‍රතිලාභ : සේවක සුබසාධක අරමුදල මඟින් ණය පහසුකම්, නොමිලේ නිල ඇඳුම්, EPF/ETF සඳහා දායකත්වය, පාරිතෝෂික දීමනා.', 'Kohuwala, Colombo', '2026-06-23 09:03:49.801811+00', '2026-06-23 09:03:49.801811+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (47, 40, 4, 'Sales Representatives', false, 'Sales Representatives (trained/untrained) for Kandy region. Qualifications: GCE O/L passed, age 18-35, excellent communication and interpersonal skills, experience not required, driving license is an added advantage, must reside in Kandy or nearby. Benefits: Basic salary + additional allowances + sales commission (income over Rs 70,000), EPF and ETF, accommodation facilities. Contact for interview: 0773882852 / 0773882850. Send CV to WhatsApp: 0777502930. Grace Cosmetics, No.04, Jambugasmulla Rd, Nugegoda.', 'Kandy City, Kandy', '2026-06-23 09:03:49.820535+00', '2026-06-23 09:03:49.820535+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (48, 41, 4, 'Relationship Manager', false, 'Relationship Manager hir in Kurunegala salary 150,000/-', 'Kurunegala City, Kurunegala, Sri Lanka', '2026-06-23 09:03:49.832997+00', '2026-06-23 09:03:49.832997+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (49, 42, 4, 'Showroom Sales Executive', false, 'This is a Shoe Showroom and the right candidate will be selected upfront from the interview. We are looking for an energetic and customer-focused Sales Executive to join our FashionXpo.lk showroom team. The ideal candidate should be passionate about fashion, confident in communication, and driven to achieve sales targets. A strong ability to understand customer needs, suggest products, and foster long-term relationships is key to success. Key Responsibilities: Greet and assist customers in a friendly and professional manner, Understand customer needs and recommend suitable products, Achieve daily and monthly sales targets, Promote ongoing offers, accessories, and new arrivals, Maintain showroom cleanliness and product displays, Handle billing, stock support, and basic POS activities, Build long-term relationships with customers. Requirements: Minimum O/L or A/L qualification, Previous experience in retail or fashion sales is an advantage, Good communication skills (Sinhala / Tamil, basic English preferred), Pleasant personality and positive attitude, Ability to work flexible hours and weekends, Target-oriented and team player. Benefits: Attractive basic salary + Food Allowance + commission, Sales incentives & bonuses, Staff discounts, Growth opportunities in a fast-growing fashion brand.', 'Wattala, Gampaha', '2026-06-23 09:03:49.845064+00', '2026-06-23 09:03:49.845064+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (50, 43, 4, 'Waiters', false, 'Positions are available across all our branches. Waiters we''re looking for passionate individuals to join our team!', 'Colombo 10, Sri Lanka', '2026-06-23 09:03:49.85378+00', '2026-06-23 09:03:49.85378+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (160, 118, 4, 'Assistant Supervisor', false, 'Assistant Supervisor for branch operations management at a leading delivery service company. Qualifications: Age 18-35, GCE A/L passed, basic computer knowledge, must have a motorcycle and valid license, willingness for full-time service and ability to work actively with a team. Benefits: High salary Rs 50,000-60,000, EPF/ETF payments, performance allowances, promotion opportunities based on skills. Special opportunity: If performance targets are met, promotion to Supervisor within 6 months to 1 year.', 'Nugegoda, Colombo', '2026-06-23 17:04:28.356339+00', '2026-06-23 17:04:28.356339+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (161, 119, 4, 'AC Technician', false, 'වායුසමීකරණ කාර්මික ශිල්පින් බදවා ගැනේ. ඉහල වැටුප් සහ දීමනා. ස්ථිර බදවා ගැනීම. සෑම වසරකම වැටුප් වැඩිවීම් සහ බෝනස්. අත්දැකීම් සහ පළපුරුද්ද මත ඔබගේ වැටුප සාකච්චා කරගත හැක. වායුසමීකරණ සවිකිරීම/ ගෑස් කිරීම/ කැපසිටර් මාරු කිරීම/ සවිස් කිරීම /දෝෂ හදුනා ගැනීම සහ අලුත් වැඩියා කිරීම පිලිබදව දැනුම තිබිය යුතුවේ.', 'Colombo 5, Colombo, Sri Lanka', '2026-06-23 17:04:28.711852+00', '2026-06-23 17:04:28.711852+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (162, 120, 4, 'Accounts Assistant Cum Office Coordinator', false, 'We are a footwear manufacturing company based in Homagama. Seeking suitable and enthusiastic candidates for the position of Accounts Assistant Cum Office Coordinator. Requirements: Minimum 1 year experience in Invoicing, Inventory Maintaining, Coordinating with Sales Representatives or similar capacity. Part qualification in AAT or equivalents. Qualifications in HR Related education and experience will added advantage. General knowledge of accounting package including MS Office. Should be around Homagama Area.', 'Homagama, Colombo, Sri Lanka', '2026-06-23 17:04:28.795543+00', '2026-06-23 17:04:28.795543+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (163, 118, 4, 'Assistant Supervisor', false, 'Assistant Supervisor for branch operations management at Sri Lanka''s number 1 delivery service company. Qualifications: Age 18-35, GCE A/L passed, basic computer knowledge, must have a motorcycle and valid license, willingness for full-time service and ability to work actively with a team. Benefits: High salary Rs 50,000-60,000, EPF/ETF payments, performance allowances, promotion opportunities based on skills. Special opportunity: If you meet the expected performance level, you can be promoted to Supervisor within 6 months to 1 year.', 'Ambalantota, Hambantota', '2026-06-23 17:04:28.857456+00', '2026-06-23 17:04:28.857456+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (164, 121, 4, 'Air Conditioning Technicians', false, 'WE ARE HIRING AIR-CONDITIONING TECHNICIANS (4 Positions). Digitech Holdings (Pvt) Ltd is looking for skilled and dedicated Air-Conditioning Technicians to join our growing team based in Malabe. Key Responsibilities: Installation, servicing, maintenance, and repair of residential and commercial air-conditioning systems. Diagnose and troubleshoot faults in air-conditioning units and associated equipment. Perform preventive maintenance and system inspections. Carry out refrigerant charging, leak detection, and repairs. Ensure all work is completed in accordance with safety and quality standards. Attend customer service calls and provide technical support when required. Maintain accurate service records and reports. Requirements: NVQ Qualification or equivalent technical certification in Refrigeration and Air Conditioning. Minimum 1–3 years of experience in the installation and maintenance of air-conditioning systems. Knowledge of split, cassette, floor-standing, and VRF/VRV systems will be an added advantage. Ability to diagnose and rectify technical faults independently. Good communication and customer service skills. Possession of a valid riding or driving license will be an added advantage. Ability to work independently and as part of a team. We Offer: Attractive remuneration package. Overtime and performance incentives. Opportunities for training and career advancement. Friendly and professional working environment.', 'Malabe, Colombo', '2026-06-23 17:04:28.943462+00', '2026-06-23 17:04:28.943462+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (165, 122, 4, 'Accounts Clerk', false, 'JOB VACANCY – ACCOUNTS CLERK. Company: MS Motors Holdings Co. (Pvt) Ltd (Authorized Sales, Service & Spare Parts Dealer – Stafford Motor Co. Pvt Ltd). Work Location: Kottawa / Maharagama. Requirements: GCE O/L Pass, Good communication skills, Computer knowledge will be an added advantage.', 'Kottawa, Colombo, Sri Lanka', '2026-06-23 17:04:29.041548+00', '2026-06-23 17:04:29.041548+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (166, 123, 4, 'Account Manager', false, 'We are a rapidly growing Chinese electric vehicle company seeking qualified and experienced professionals to join our team in Sri Lanka. Available Positions: Finance Manager Human Resources Manager. Requirements: Proven work experience in the relevant field. Strong professional knowledge and practical experience. Excellent communication and organizational skills. Ability to work independently and as part of a team. Advanced educational qualifications will be an added advantage. Proficiency in Chinese language will be given special preference. We Offer: Attractive salary package. Career growth opportunities in the EV industry. Dynamic and international working environment. Opportunity to work with a leading Chinese electric vehicle company.', 'Colombo 3, Sri Lanka', '2026-06-23 17:04:29.088727+00', '2026-06-23 17:04:29.088727+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (167, 124, 4, 'Account clerk & assistant', false, 'අනුරාධපුර නගරයේ පිහිටි ගිණුම් උපදේශන ආයතනය සදහා පුහුණු නුපුහුණු ලිපිකාරිණියන් අවශ්‍යයි. # අ.පො.ස. උසස් පෙල හා උපාධිදාරීන් සදහා ඇබෑර්තු ඇත. # අනුරාධපුර නගරය අවටින්.', 'Anuradhapura City, Anuradhapura, Sri Lanka', '2026-06-23 17:04:29.118655+00', '2026-06-23 17:04:29.118655+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (168, 125, 4, 'බැංකු සහකාර ලිපිකරු (පුහුණු නුපුහුණු)', false, 'නුවරඑළිය දිස්ත්‍රික්කය තුළ විහිදී ඇති වානිජමය බැංකු සහ මූල්‍ය‍ය ආයතන කීපයක් සඳහා කඩිනමින් පුහුණු නුපුහුණු සේවක සේවිකාවන් සඳහා අයදුම්පත් භාරගනු ලබයි. සුදුසුකම්: සාමාන්‍ය පෙළ (O/L) පෙනී සිටීම අනිවාර්ය වේ. වයස අවුරුදු 18-40 අතර සියලුම දෙනාට අයදුම්පත් භාරදිය හැක. ප්‍රතිලාභ: පුහුණු කාලය තුළද ඉහළම වැටුප් හා දීමනා (පුහුණු කාලය තුළද 35000-50000 අතර මූලික වැටුප් ගෙවීම්). පුහුණු කාලයෙන් පසු රැකියාව ස්ථිර වීමත් සමග ඉහළම වැටුප් හා දීමනා (50000-100000 මූලික වැටුප් ගෙවීම්). මූලික වැටුප් වලට අමතරව අධිකාලදීමනා, ආයතනික ගෙවීම්, ප්‍රවාහන දීමනා, දිරි දීමනා ඔබට හිමිවනු ඇත. ඔබට රැකියාව කරන අතරතුර අධ්‍යාපන කටයුතුවල නීලීමට හැකියාව ඇත. මෙවර උසස් පෙළ පෙනී සිටින සිසුන්ටද අයදුම්පත් භාරදිය හැක. කෙටි කාලීන මෙන්ම දීර්ඝ කාලීනවද රැකියාව නියැලීමට හැකියාව ඇත. දිවයිනේ ඕනෑම ප්‍රදේශයක පදිංචි අයෙකුට අයදුම්පත් බාර දිය හැක. ආයතන පුහුණුව සහ දීර්ඝ කාලීනව රැඳීම මත උසස් වීම් ලබාදේ. ලිපිකරු සහ සහකාර ලිපිකරු තනතුරු වලට බඳවා ගැනීම් කරන අතර පුහුණුව හා අධ්‍යාපන සුදුසුකම් මත ඉහළ තනතුරු සඳහා යොමු කිරීම් (ගිණුම් ලිපිකරු, ගිණුම් සහායක, පරිගණක දත්ත ක්‍රියාකරුවන්, කැෂියවරුන්, දුරකථන ක්‍රියාකරුවන්, පිළිගැනීමේ නිලධාරීන්).', 'Nuwara Eliya City, Nuwara Eliya, Sri Lanka', '2026-06-23 17:04:29.172727+00', '2026-06-23 17:04:29.172727+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (169, 126, 4, 'Cake Decorator / Cake Artist', false, 'We are looking for a creative and skilled Cake Decorator / Cake Artist to join our team. The ideal candidate should be passionate about cake designing and able to produce high-quality decorative cakes for various occasions. Requirements: Experience in cake decorating (fondant, buttercream, icing), Knowledge of piping techniques, Skills in fondant shaping and cake design, Ability to mix colors and create creative designs, Strong attention to detail, Ability to work under pressure (especially during rush orders), Age: 18 – 40 years. Benefits: Food provided, Accommodation provided.', 'Colombo 6, Sri Lanka', '2026-06-23 17:04:29.255058+00', '2026-06-23 17:04:29.255058+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (171, 128, 4, 'බැංකු සහකාර ලිපිකරු(පුහුණු /නුපුහුණු)', false, 'මොනරාගල දිස්ත්‍රික්කය තුළ විහිදී ඇති වානිජමය බැංකු සහ මූල්‍ය‍ය ආයතන කීපයක් සඳහා කඩිනමින් පුහුණු නුපුහුණු සේවක සේවිකාවන් සඳහා අයදුම්පත් මේ දින වලදී භාරගනු ලබයි. සුදුසුකම්-: #සාමාන්‍ය පෙළ (O/L)පෙනී සිටීම අනිවාර්ය වේ. # වයස අවුරුදු 18-40 අතර සියලුම දෙනාට අයදුම්පත් භාරදියය හැක. ප්‍රතිලාභ-: #පුහුණු කාලය තුළද ඉහළම වැටුප් හා දීමනා.(පුහුණු කාලය තුළද 35000-50000 අතර මූලික වැටුප් ගෙවීම්) # පුහුණු කාලයෙන් පසු රැකියාව ස්ථිර වීමත් සමග ඉහළම වැටුප් හා දීමනා.(50000-100000 මූලික වැටුප් ගෙවීම්) #මූලික වැටුප් වලට අමතරව අධිකාලදීමනා,ආයතනික ගෙවීම්,ප්‍රවාහන දීමනා ,දිරි දීමනා ඔබට හිමිවනු ඇත. # ඔබට රැකියාව කරන අතරතුර අධ්‍යාපන කටයුතුවල නීලීමට හැකියාව ඇත.(එවැනි අවස්ථාවකදී මූල්‍යමය සහ අධ්‍යාපන කටයුතු සඳහා සහයෝගය ආයතනය ලබාදෙයි) #මෙවර උසස් පෙළ පෙනී සිටින සිසුන්ටද අයදුම්පත් භාරදිය හැක. #කෙටි කාලීන මෙන්ම දීර්ඝ කාලීනවද රැකියාව නියැලීමට හැකියාව ඇත. # දිවයිනේ ඕනෑම ප්‍රදේශයක පදිංචි අයෙකුට අයදුම්පත් බාර දිය හැක.ඔබගේ ළඟම ප්‍රදේශයට පුහුණුව සහ රැකියාව ලබාදේ. # ආයතන පුහුණුව සහ දීර්ඝ කාලීනව රැඳීම මත උසස් වීම් ලබාදේ. ලිපිකරු සහ සහකාර ලිපිකරු තනතුරු වලට බඳවා ගැනීම් කරන අතර පුහුණුව හා අධ්‍යාපන සුදුසුකම් මත ඉහළ තනතුරු සඳහා යොමු කිරීම්.(ගිණුම් ලිපිකරු,ගිණුම් සහායක,පරිගණක දත්ත ක්‍රියාකරුවන්,කැෂියවරුන්,දුරකථන ක්‍රියාකරුවන්,පිළිගැනීමේ නිලධාරීන්) ඔබත් රැකියාවක් බලාපොරොත්තුවෙන් සිටින පුහුණු හෝ නුපුහුණු අයෙකු නම් අදම අප බඳවා ගැනීමේ නිලධාරීන් අමතන්න.', 'Monaragala City, Monaragala', '2026-06-23 17:09:09.25258+00', '2026-06-23 17:09:09.25258+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (172, 129, 4, 'Bartender', false, 'We are looking for energetic and motivated individuals to join our restaurant team for the following positions: Salary: Rs. 50,000 + Service Charge 100% Benefits: Accommodation provided, Staff meals provided, Uniforms provided, 6 days leave per month. If you are passionate about working in the hospitality industry and ready to grow with us, please send your CV or contact us today. Contact - MR Dasun 0777403052', 'Dehiwala, Colombo', '2026-06-23 17:09:09.331375+00', '2026-06-23 17:09:09.331375+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (173, 125, 4, 'බැංකු සහකාර ලිපිකරු(පුහුණු /නුපුහුණු)', false, 'රත්නපුර දිස්ත්‍රික්කය තුළ විහිදී ඇති වානිජමය බැංකු සහ මූල්‍ය‍ය ආයතන කීපයක් සඳහා කඩිනමින් පුහුණු නුපුහුණු සේවක සේවිකාවන් සඳහා අයදුම්පත් මේ දින වලදී භාරගනු ලබයි. සුදුසුකම්-: #සාමාන්‍ය පෙළ (O/L)පෙනී සිටීම අනිවාර්ය වේ. # වයස අවුරුදු 18-40 අතර සියලුම දෙනාට අයදුම්පත් භාරදියය හැක. ප්‍රතිලාභ-: #පුහුණු කාලය තුළද ඉහළම වැටුප් හා දීමනා.(පුහුණු කාලය තුළද 35000-50000 අතර මූලික වැටුප් ගෙවීම්) # පුහුණු කාලයෙන් පසු රැකියාව ස්ථිර වීමත් සමග ඉහළම වැටුප් හා දීමනා.(50000-100000 මූලික වැටුප් ගෙවීම්) #මූලික වැටුප් වලට අමතරව අධිකාලදීමනා,ආයතනික ගෙවීම්,ප්‍රවාහන දීමනා ,දිරි දීමනා ඔබට හිමිවනු ඇත. # ඔබට රැකියාව කරන අතරතුර අධ්‍යාපන කටයුතුවල නීලීමට හැකියාව ඇත.(එවැනි අවස්ථාවකදී මූල්‍යමය සහ අධ්‍යාපන කටයුතු සඳහා සහයෝගය ආයතනය ලබාදෙයි) #මෙවර උසස් පෙළ පෙනී සිටින සිසුන්ටද අයදුම්පත් භාරදිය හැක. #කෙටි කාලීන මෙන්ම දීර්ඝ කාලීනවද රැකියාව නියැලීමට හැකියාව ඇත. # දිවයිනේ ඕනෑම ප්‍රදේශයක පදිංචි අයෙකුට අයදුම්පත් බාර දිය හැක.ඔබගේ ළඟම ප්‍රදේශයට පුහුණුව සහ රැකියාව ලබාදේ. # ආයතන පුහුණුව සහ දීර්ඝ කාලීනව රැඳීම මත උසස් වීම් ලබාදේ. ලිපිකරු සහ සහකාර ලිපිකරු තනතුරු වලට බඳවා ගැනීම් කරන අතර පුහුණුව හා අධ්‍යාපන සුදුසුකම් මත ඉහළ තනතුරු සඳහා යොමු කිරීම්.(ගිණුම් ලිපිකරු,ගිණුම් සහායක,පරිගණක දත්ත ක්‍රියාකරුවන්,කැෂියවරුන්,දුරකථන ක්‍රියාකරුවන්,පිළිගැනීමේ නිලධාරීන්) ඔබත් රැකියාවක් බලාපොරොත්තුවෙන් සිටින පුහුණු හෝ නුපුහුණු අයෙකු නම් අදම අප බඳවා ගැනීමේ නිලධාරීන් අමතන්න.', 'Ratnapura City, Ratnapura', '2026-06-23 17:09:09.369408+00', '2026-06-23 17:09:09.369408+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (174, 130, 4, 'Business Development Executive', false, 'We are seeking a highly motivated and results-driven Client Relationship Specialist to join our dynamic team. The ideal candidate should have excellent communication skills, a positive team attitude, and a strong focus on achieving targets. Key Responsibilities: Build and maintain strong relationships with clients to ensure long-term satisfaction, Identify client needs and provide effective solutions to enhance business opportunities, Collaborate with internal teams to ensure smooth and efficient service delivery, Achieve individual targets within set timelines. Requirements: Fluency in Sinhala & Tamil is essential, Strong interpersonal and communication skills, Goal-oriented mindset with a proactive approach, Ability to work effectively as part of a team, Prior experience in client relations or similar roles will be an added advantage. What We Offer: Attractive remuneration package, Performance-based commissions and incentives, Supportive and growth-oriented work environment.', 'Colombo 3, Sri Lanka', '2026-06-23 17:09:09.537726+00', '2026-06-23 17:09:09.537726+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (279, 166, 4, 'Sales Assistant', false, 'Sales Assistant role at a showroom in Katugastota area. Qualifications: Age 18-35, passed GCE O/L, open to both males and females. Benefits: Competitive salary, training provided, safe work environment, friendly staff. Experience is an advantage. Contact: 070 463 6235, 074 124 3099. WhatsApp CV to: 076 966 4065.', 'Katugastota, Kandy, Sri Lanka', '2026-06-23 17:39:28.081084+00', '2026-06-23 17:39:28.081084+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (175, 131, 4, 'Call Center Executive', false, 'Handle inbound and outbound customer calls professionally. Respond to customer inquiries and provide accurate information. Maintain customer records and update databases. Resolve customer complaints and ensure customer satisfaction. Meet performance and quality targets. Requirements: Excellent communication skills in English and Sinhala/Tamil. Strong interpersonal and customer service skills. Basic computer knowledge. Previous call center experience is an advantage. Ability to work in a fast-paced environment. What We Offer: Attractive salary package. Performance-based incentives. Career growth opportunities. Friendly and professional work environment.', 'Kiribathgoda, Colombo', '2026-06-23 17:09:09.602095+00', '2026-06-23 17:09:09.602095+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (176, 132, 4, 'Call Centre Officer', false, 'Salary Rs 65,000 - 70,000 per month. Required education: Ordinary Level. No prior work experience required. Job involves handling regular calls (not WhatsApp). Multiple branches available: Nāvala, Nugegoda, Maharagama, Kottawa, Homagama, Pitakotuwa, Bambalapitiya, Kollupitiya, Boralesgamuwa. Interviews held daily until 30 vacancies filled. This is direct hiring by the company, not an agency.', 'Colombo 12, Sri Lanka', '2026-06-23 17:09:09.624456+00', '2026-06-23 17:09:09.624456+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (177, 133, 4, 'Business Development Executive (Male/Female) - Colombo', false, 'Achieve the set sales targets and KPIs within the stipulated time frame. Carry out relevant tasks set out by the Team Lead towards achieving set goals. Create / manage / nurture / maintain a strong customer pipeline to ensure continuous sales growth. Provide relevant market / competitor feedback regularly to the respective Team Lead. Educate and train customers to maximize the benefit of their membership through effective ad posting / boosting at the right times. Maintain the highest level of integrity and work ethic at all times. Candidate Requirements: 1+ years of experience in sales / business development. Outstanding communication and negotiation skills. Resides in or around Colombo. Benefits: We offer an attractive remuneration package & incentives that are above market standards for the suitable candidate.', 'Colombo 2, Colombo, Sri Lanka', '2026-06-23 17:09:09.65654+00', '2026-06-23 17:09:09.65654+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (187, 140, 4, 'Consultant', false, 'Student Consultant (Freshers Welcome!) We are expanding our team and looking for motivated, energetic, and career-driven individuals to grow with us. Available Positions: Student Consultant. Requirements: Fresh graduates / school leavers are welcome, Good communication skills (English preferred), Basic computer knowledge, Willingness to learn with a positive attitude. Responsibilities: Student counselling & client handling, University application support, Follow-ups with students & partner institutions. What We Offer: Friendly and supportive working environment, Full training provided (for freshers), Career growth opportunities, Attractive salary + incentives.', 'Colombo 5, Sri Lanka', '2026-06-23 17:12:46.959214+00', '2026-06-23 17:12:46.959214+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (188, 141, 4, 'වරාය දෙස් විදෙස් නවුකා අලුත් වැඩියා අංශ සේවක මහතුන්', false, 'Port domestic and foreign ship repair department new job opportunities for energetic youth aged 18-50. No educational qualifications required. Unskilled workers can apply for welding department (company provides free training). Even during training period, salary of 80,000/= or more. Anyone aged 18-53 can apply. Can apply from any area of the island. Food and accommodation facilities provided. Friends and groups can work in the same department. No caste discrimination, anyone can apply. Salary Rs 85,000 - 125,000 per month.', 'Colombo, Sri Lanka', '2026-06-23 17:12:47.007794+00', '2026-06-23 17:12:47.007794+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (178, 134, 4, 'Call Center Executive(Female & male) – Real Estate Property Management', false, 'Call Center Executive (Female & male) – Real Estate & Property Management. Property Deal Real Estate is a leading real estate and property management company specializing in luxury apartments, houses, and investment properties. We serve a diverse international client base including customers from foreign, and Sri Lanka. We are looking for a dynamic and customer-focused Call Center Executive to join our growing team. Key Responsibilities: Answer incoming calls from local and international clients. Respond to property inquiries professionally and efficiently. Record and update customer information and inquiries in the CRM/lead management system. Follow up with prospective buyers, tenants, and property owners. Coordinate appointments and property viewings with agents and management. Provide accurate information about available properties and services. Maintain high standards of customer service and client satisfaction. Handle WhatsApp, email, and online inquiries when required. Assist with general customer support and administrative tasks. Requirements: Female candidate aged 21 – 30 years. 2 years of experience in Customer Care, Call Center, or Customer Service. Basic computer literacy (MS Office, Email, Internet). Excellent communication skills. Ability to speak English and Sinhala fluently. Ability to speak Tamil will be an added advantage. Pleasant personality with strong interpersonal skills. Ability to work in a fast-paced environment. What We Offer: Attractive salary package. Performance-based incentives. Career growth opportunities in the real estate industry. Friendly and professional working environment. Opportunity to work with international clients.', 'Colombo 6, Sri Lanka', '2026-06-23 17:09:09.69595+00', '2026-06-23 17:09:09.69595+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (179, 135, 4, 'Call Center Officer - Colombo', false, 'Call Center Officer role in Colombo. Salary Rs 60,000 - 65,000 per month. Required education: Ordinary Level. Required work experience: 0 years. Application deadline: 2026-06-26. The job involves handling calls (only regular calls, not WhatsApp). Multiple branches available: Nāvala, Nugegoda, Maharagama, Kottawa, Homagama, Pettah, Bambalapitiya, Kolpitiya, Boralesgamuwa. Interviews conducted daily until 30 vacancies are filled. This is a direct hire by the company, not an agency.', 'Colombo, Sri Lanka', '2026-06-23 17:09:09.806327+00', '2026-06-23 17:09:09.806327+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (180, 136, 4, 'Cashier', false, 'අයකැමි සහ වෙළද සහයක අවශ්‍යයි - සමුද්‍රා සුපර්මාර්කට් (කුරුණෑගල) කුරුණෑගල නගරයේ පිහිටි ප්‍රමුඛ පෙළේ සුපිරි වෙළෙදසලක් වන සමුද්‍රා සුපර් මාර්කට් (Samudra Super Market ) ප්‍රධාන ශාඛාව සඳහා අයකැමි (Cashier) තනතුරට දක්ෂ සුහදශීලී තරුණ තරුණියන් වහාම බඳවා ගැනේ. සුදුසුකම් • වයස අවරුදු 18-30 අතර (ගැහැණු/ පිරිමි ) • අ.පො.ස. (සා/පෙළ) හෝ (උ.පෙළ) පෙනී සිට තිබීම. • මූලික පරිඝනක දැනුම සහ pos පද්ධති හැසිරවීමේ හැකියාව(පළපුරුද්දක් තිබීම අමතර සුදුසුකමකි, නමුත් පලපුරුදක් නොමැති අයට ද පුහුණුව ලබා දී බඳවා ගැනේ). • පාරිභෝගිකයින් සමඟ සුහදශීලිව කටයුතු කිරීමේ හැකියාව. • කුරුණෑගල අවට පදිංචිකරුවන් වීම. ප්‍රතිලාභ • ආකර්ශනීය වැටුප් • ETF/EPF දීමනා. • සුහදශීලි සේවා පරිසරය.', 'Kurunegala City, Kurunegala, Sri Lanka', '2026-06-23 17:12:46.765028+00', '2026-06-23 17:12:46.765028+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (181, 137, 4, 'Cashier - Work from Home', true, 'online Cashier Work from Home Male Female Need Smartphone only Know to transfer p2p Binance Crypto all crypto buy sale Salary + commission above RS 150000 + send you cv WhatsApp +94723431687', 'Nugegoda, Colombo', '2026-06-23 17:12:46.833814+00', '2026-06-23 17:12:46.833814+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (182, 129, 4, 'Cashier', false, 'We are looking for energetic and motivated individuals to join our restaurant team for the following positions: Salary: Rs. 50,000 + Service Charge 100%. Benefits: Accommodation provided, Staff meals provided, Uniforms provided, 6 days leave per month. If you are passionate about working in the hospitality industry and ready to grow with us, please send your CV or contact us today. Contact - MR Dasun 0777403052', 'Dehiwala, Colombo', '2026-06-23 17:12:46.851549+00', '2026-06-23 17:12:46.851549+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (183, 16, 4, 'Cashier - Jampatah Street', false, 'Requirements: Age between 18 and 40. O/L Mathematics with S pass is mandatory. Cashier experience is an added advantage. 12-hour shifts (including 3 hours OT). Willingness to work night shifts. Minimum 2 years of supermarket cashier experience. Benefits: High salary + OT, Free food/accommodation, Life insurance, Permanent employment from day one, Promotions after 6 months. Interview documents required: National ID copy, Birth certificate copy, Bank passbook copy, Grama Sevaka certificate copy or original, O/L certificate copy, Pen for writing. Limited positions available. Interview at Kirulapana LAUGFS main office from 9 AM to 3 PM. Phone: 0762536891 - Keshani.', 'Colombo 6, Sri Lanka', '2026-06-23 17:12:46.86864+00', '2026-06-23 17:12:46.86864+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (184, 16, 4, 'Cashier', false, 'Cashier position at LAUGFS Supermarkets. Requirements: Age between 18 and 40, O/L Mathematics with S pass (mandatory), cashier experience is an added advantage, 12-hour shifts (including 3 hours OT), willing to work night shifts, minimum 2 years supermarket cashier experience. Benefits: High salary + OT, free food/accommodation, life insurance, permanent employment from day one, promotion opportunities after 6 months. Interview location: LAUGFS Head Office, Kirulapana, 9am to 3pm. Contact: 0762536891 - Keshani.', 'Colombo 6, Sri Lanka', '2026-06-23 17:12:46.888017+00', '2026-06-23 17:12:46.888017+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (185, 138, 4, 'Cash Collector', false, 'ගෙවීමේ ක්‍රමයට පවත්වාගෙන යනු ලබන ආයතනකට වයස අවු- 20 - 30 අතර සාමාන්‍ය පෙල සමත් යතුරුපැදි රියදුරු බලපත්‍රය සහිත නියෝජිතයකු වහාම අවශ්‍යයි. නවාතැන් පහසුකම් නොමිලේ.', 'Homagama, Colombo', '2026-06-23 17:12:46.906802+00', '2026-06-23 17:12:46.906802+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (186, 139, 4, 'Clerk', false, 'කිරිබත්ගොඩ පිහිටි පුද්ගලික ආයතනයක් සදහා පරිගණක ටයිප්සෙටින් ක්‍රියාකරුවන් අවශ්‍යයි. වෙනත් දීමනා හා ETF EPF සහිතයි. Required education: Advanced Level. Required work experience (years): 0.', 'Kelaniya, Gampaha, Sri Lanka', '2026-06-23 17:12:46.930619+00', '2026-06-23 17:12:46.930619+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (244, 32, 4, 'Team Leader''s Manager - Kadugannawa', false, 'Professional Wealth Planner. Join the world''s largest company as a Professional Wealth Planner. If selected: leading global career, rapid income growth with professional competence, financial freedom and time freedom, promotions with professional excellence, local and international recognition, domestic and foreign travel opportunities. This opportunity is for those with: good social network, professional connections, trustworthiness in society, willing to achieve professional goals through commitment, experienced in financial services, marketing, banking services, insurance services.', 'Kadugannawa, Kandy, Sri Lanka', '2026-06-23 17:29:25.175184+00', '2026-06-23 17:29:25.175184+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (189, 142, 4, 'Counter Staff (Male Female)', false, 'Welcome customers and provide friendly, professional service. Take customer orders accurately and efficiently. Handle billing and payment transactions when required. Assist customers with menu information and product recommendations. Ensure proper display and presentation of food and beverage items. Maintain cleanliness and organization of the counter area. Coordinate with kitchen and service staff to ensure smooth operations. Handle customer inquiries and complaints professionally. Support daily restaurant and catering operations as required. Requirements: Previous experience in a restaurant, café, bakery, supermarket, or retail environment will be an advantage. Good communication skills in Sinhala. Basic knowledge of English will be an added advantage. Pleasant personality with strong customer service skills. Ability to work in a fast-paced environment. Good teamwork and interpersonal skills. Ability to work shifts, weekends, and public holidays when required. Additional advantages: Basic computer knowledge and POS system experience. Previous experience in food and beverage service. Experience handling customer orders and cash transactions.', 'Colombo 3, Sri Lanka', '2026-06-23 17:12:47.031459+00', '2026-06-23 17:12:47.031459+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (190, 33, 5, 'Data Entry Typing Operators - (Online Part Time) Works at Home', true, 'Data Entry Typing Operators - (Online Part Time) Works at Home. Employer: IIF HOLDIN PVT LTD. Role: Data Entry Operator. Job type: Part Time. Salary per month: Rs 45,000 - 85,000. Required education: Ordinary Level. Required work experience (years): 0. Employer Website: https://forms.gle/rcs2xWtcnWhnqJt5A. About the role: Apply via the link in Employer Website. 15 minutes within we will contact you. (Government registered institution). Our institution is a Software Company over 10 years old, with projects through many departments. Work From Home Working Community is one project, mainly providing Data Entry Typing or other projects to you, giving good stable monthly income. Sri Lankan Projects: Data Entry Works, Online Data Submit, Copy Typing, Simple Typing. Required skills: Basic IT knowledge, only email. Male/Female work from home. Anyone across the island can join and start today. You can choose job categories under various fields and work at convenient times. Requirements: 1 - Computer or Laptop or Smart Phone. 2 - Minimum one hour of time is sufficient. 3 - Employed persons, unemployed, housewives, school leavers, university students, anyone seeking extra income can work. 4 - Even if you are employed in another job, you can work in your free time. We provide: Full Sinhala or English Guidelines (Call or Email reply), Daily job options (Typing, Simple Data Submits, Data Entry), Work from home – any time, Withdraw money via eZ Cash / Bank deposit, Support available - 24 hrs, Lifetime access (Within 30 minutes). If you join us, you can start work within 30 minutes.', 'Mawanella, Kegalle', '2026-06-23 17:15:25.692048+00', '2026-06-23 17:15:25.692048+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (191, 143, 4, 'Crew Member', false, 'Responsibilities: Manage customer transaction process, customer service and marketing activities, maintain restaurant environment. Qualifications: Age 18-24, ability to work in a team, experience in quick service field, good personal grooming, multilingual knowledge (beneficial). Benefits: Attractive salary (Rs 55,000 - 65,000), training opportunities, working hours: 12:00PM to 02:00AM (with breaks).', 'Mount Lavinia, Colombo', '2026-06-23 17:15:25.741727+00', '2026-06-23 17:15:25.741727+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (192, 144, 4, 'Computer Technician', false, 'WANTED Computer Technician. Job Duties: Computer Assembling, laptop assemble and disassemble, Computer Hardware repairs, Carrying the new equipment (Kottawa to Colombo city). Required Skills: Bike license required, Basic computer knowledge is enough. Working Hours: 9:00am – 7.00pm (Mon - Sat) Kottawa. Also includes: Printer LQ-310 / tally 1145 assemble and disassemble, office work document handling, Software Installation, Good Communication Skills. Working Experience of more than one year is preferred.', 'Kottawa, Colombo', '2026-06-23 17:15:25.778455+00', '2026-06-23 17:15:25.778455+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (194, 146, 4, 'Data Entry Operator', true, 'Work-from-Home Opportunity. Our organization specializes in preparing detailed sales reports for large-scale international shopping malls and retail complexes located overseas. Your Primary Responsibility: Collect, Organize, and Input daily/weekly sales & transaction data using our proprietary software. What We Provide: Comprehensive 1-month full training on our specialized data-entry and reporting software, all necessary software access and tools, ongoing support after training. Work Arrangement: 100% Work from Home full-time position, flexible hours (as long as daily targets are met). Compensation: Attractive fixed base salary, unlimited performance-based incentives (no cap). Required education: Ordinary Level. Required work experience (years): 0.', 'Colombo 1, Sri Lanka', '2026-06-23 17:15:25.825265+00', '2026-06-23 17:15:25.825265+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (195, 147, 4, 'Delivery Helpers -Mattegoda', false, 'බෙදා හැරීමේ සහයකයින් – Delivery Helpers > උද්යෝගිමත් සහ වැඩ කිරීමට කැමති පුද්ගලයින් > නවාතැන් දීමනාස මගින් ආකර්ශනීය වැටුපක් ගෙවනු ලැබේ’ +++ පරීක්ෂණ සඳහා විමසන්න – 0773576444', 'Kottawa, Colombo', '2026-06-23 17:15:25.85177+00', '2026-06-23 17:15:25.85177+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (196, 148, 4, 'Crew Member', false, 'JOIN US! START YOUR CAREER JOURNEY WITH THE FAST-GROWING GOURMET BURGER CHAIN OF SRI LANKA. Position: Crew Member. Location: Nawala. Opportunity for all: Experienced or Freshers, School Leavers or Hotel School Students. Minimum Requirements: Minimum Qualification - Sat for G.C.E (A/L) or (O/L); Energetic & eager to learn. Benefits: An attractive remuneration package based on experiences; Duty Meals, Uniforms and Accommodation provided; Performance based promotion; Internal & External training on job skills and personal development; Staff Outings, Awards & Target Incentives & Many more.', 'Nawala, Colombo', '2026-06-23 17:15:25.885439+00', '2026-06-23 17:15:25.885439+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (197, 149, 4, 'Waiter', false, 'Maharaja Palace Restaurant is urgently looking for enthusiastic and hardworking staff to join our team. Available Positions: Waiters, Waitresses. We Offer: Good Salary, Service Charge, Free Staff Meals, Accommodation Provided. Location: 1A, Royal Avenue, Colombo 07 (Opposite Royal College).', 'Colombo 7, Sri Lanka', '2026-06-23 17:15:25.900464+00', '2026-06-23 17:15:25.900464+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (198, 150, 4, 'Waiters', false, 'තිස්සමහාරාමයේ ප්‍රසිද්ධ සංචාරක අවන්හලක් සඳහා පළපුරුදු වේටර්වරුන් සඳහා කඩිනමින් ඇබෑර්තු ඇත. විමසීම් – 0774440374 / 0769856699 (whatsapp). Required education: Skilled Apprentice. Required work experience (years): 0.', 'Tissamaharama, Hambantota, Sri Lanka', '2026-06-23 17:15:25.914328+00', '2026-06-23 17:15:25.914328+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (260, 186, 5, 'Public Relation Officer', false, 'Female age 20 to 30. Shift duty. Well reputed medical centre in colbo 06. Shift 9 am to 3 pm & 3 pm to 8 pm. Salary 50000 per shift, every 6 months 10000 increase. Accommodation not provided. Should be fluent in English and sinhala. Tamil speaking additional advantage.', 'Colombo 6, Sri Lanka', '2026-06-23 17:35:53.631215+00', '2026-06-23 17:35:53.631215+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (199, 33, 5, 'Data Entry Operators - (Online / Part Time) Works at Home', true, 'Data entry operators needed for online part-time work from home. Basic IT skills required, email only. Male/Female can work from home. Anyone across the island can join and start today. You can choose job categories under various fields and work at your convenient time. Requires a Computer, Laptop, or Smart Phone. Minimum one hour of time commitment is sufficient. Suitable for employed persons, unemployed, housewives, school leavers, university students, and anyone seeking additional income. Even if you are already employed, you can work during your free time. Salary range Rs 45,000 - 85,000 per month. Required education: Ordinary Level. No prior work experience required.', 'Akurana, Kandy, Sri Lanka', '2026-06-23 17:15:25.931968+00', '2026-06-23 17:15:25.931968+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (200, 36, 4, 'Driver', false, 'රැකියා ඇබෑර්තු වෘත්තීමය රැකියාවක් සොයන ඔබට මත්තේගොඩ පිහිටි ප්‍රධාන පෙළේ පෞද්ගලික ආයතනයක රැකියා අවස්ථාවක්. රියදුරු – Driver. නවාතැන් දීමනා සමගින් ආකර්ශනීය වැටුපක් ගෙවනු ලැබේ. සම්මුඛ පරීක්ෂණ සඳහා විමසන්න –0773576444', 'Kottawa, Colombo, Sri Lanka', '2026-06-23 17:17:03.017213+00', '2026-06-23 17:17:03.017213+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (201, 151, 5, 'Data Entry Operator - (Part Time) Works from Home', true, 'Data Entry Operator - (Part Time) Works at Home. Male Female Need Smartphone only. Know to transfer p2p Binance Crypto all crypto buy sale. Salary + commission above RS 150000 + send you cv WhatsApp +94723431687', 'Dehiwala, Colombo', '2026-06-23 17:17:03.028768+00', '2026-06-23 17:17:03.028768+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (202, 129, 4, 'Electrician', false, 'We are looking for energetic and motivated individuals to join our restaurant team for the following positions: Salary: Rs. 60,000 + Service Charge 100%. Benefits: Accommodation provided, Staff meals provided, Uniforms provided, 6 days leave per month. If you are passionate about working in the hospitality industry and ready to grow with us, please send your CV or contact us today. Contact - MR Dasun 0777403052', 'Dehiwala, Colombo', '2026-06-23 17:17:03.04402+00', '2026-06-23 17:17:03.04402+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (203, 152, 4, 'Digital Printing Machine Operator', false, 'Job Vacancy: Digital Printing Machine Operator. We are well established outdoor advertising company located in Himbutana, Angoda and we are looking for a DIGITAL PRINTING MACHINE OPERATOR to support our team. Requirements: Minimum 1 year experience in operating and maintaining Digital Printing Machine. Good knowledge in Graphic Designing (Photoshop, Illustrator, Corel-draw, Premiere Pro, and Cap Cut) will be an added advantage. Familiar with current outdoor advertising trends. Ability to work under pressure and handle multiple jobs. Salary - Rs.65,000 – 75,000.', 'Angoda, Colombo', '2026-06-23 17:17:03.077284+00', '2026-06-23 17:17:03.077284+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (204, 153, 5, 'Data Entry Operator - Part Time', true, 'WE ARE HIRING – DATA ENTRY OPERATORS (HOME BASED). Position: Data Entry Operator. Work Type: Work From Home. Working Hours: 2– Hours Per Day. Job Type: Part-Time. Gender: Male / Female. Age: No Age Limit. Requirements: Basic Computer Knowledge, Ability to Read & Type English, Smartphone or Computer Required, Internet Access Required, Responsible & Punctual Individuals. Job Responsibilities: Enter data into system or forms, Copy typing and simple data entry tasks, Maintain accuracy in data entry, Submit completed work on time. Income: Attractive Part-Time Earnings. Training: Step-by-step guidance provided for beginners.', 'Kandy City, Kandy, Sri Lanka', '2026-06-23 17:17:03.113501+00', '2026-06-23 17:17:03.113501+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (205, 126, 4, 'Data Entry Operator', false, 'We are looking for a detail-oriented and efficient Data Entry Operator to join our team. The ideal candidate should have good computer knowledge and the ability to manage data accurately. Requirements: G.C.E. A/L passed, Basic computer knowledge, Good typing and data handling skills, Accuracy and attention to detail, Age: 18 – 40 years.', 'Colombo 6, Sri Lanka', '2026-06-23 17:17:03.12769+00', '2026-06-23 17:17:03.12769+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (280, 120, 4, 'Supervisor - Injection Molding', false, 'Homagama based injection molding and footwear company requires supervisors. Experience in injection molding, footwear or other production supervision required. Free accommodation provided. Age 30+. High salary. For more details call 0778884352.', 'Homagama, Colombo, Sri Lanka', '2026-06-23 17:39:35.280126+00', '2026-06-23 17:39:35.280126+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (206, 33, 5, 'Data Entry Operators - (Typing Online Part Time) Works at Home', true, 'Work From Home. Sri Lankan Projects. Data Entry Works, Online Data Submit, Copy Typing, Simple Typing. Required skills: Basic IT knowledge, email only. Males and females can work from home. Anyone across the island can join and start today. You can choose job categories under different fields and work at your convenient time. Requirements: 1 - Computer or Laptop or Smart Phone. 2 - Minimum one hour of time is sufficient. 3 - Those who are employed, unemployed, housewives, school leavers, university students and anyone looking for extra income can work. 4 - Even if you are already employed, you can work in your free time. We provide: Full Sinhala or English Guidelines (Call or Email reply), Daily job options (Typing, Simple Data Submits, Data Entry), Work from home – any time, Withdraw your money via eZ Cash / Bank deposit, Support available - 24 hrs, Lifetime access (Within 30 minutes). Salary per month: Rs 45,000 - 85,000.', 'Kurunegala City, Kurunegala, Sri Lanka', '2026-06-23 17:17:03.14953+00', '2026-06-23 17:17:03.14953+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (207, 32, 4, 'Team Leaders - Warakapola', false, 'Professional Wealth Planner. Join the world''s largest company as a Professional Wealth Planner. If selected: leading global career, rapid income growth with professional competence, financial freedom and time freedom, promotions with professional excellence, local and international recognition, domestic and foreign travel opportunities. This opportunity is for those with: good social network, professional connections, trustworthiness in society, willing to achieve professional goals through commitment, experienced in financial services, marketing, banking services, insurance services. Contact Suranga at 0719592445 or email suranga.elikewala@aia.com.', 'Warakapola, Kegalle', '2026-06-23 17:17:03.167329+00', '2026-06-23 17:17:03.167329+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (208, 32, 4, 'Team Leader', false, 'Become a Financial Consultant Manager in Colombo! Are you an experienced professional ready for your next big step? Join the AIA team in Sri Lanka and build a rewarding career with unlimited growth potential. What You’ll Get: High Earning Potential — Attractive monthly salary income + generous commissions + performance bonuses. Clear Career Progression — Comprehensive training, tools, and support to help you advance professionally. Be Your Own Leader — Full flexibility to manage your time and grow your own business with complete independence. Local & Global Recognition — Opportunities to be celebrated both in Sri Lanka and internationally, including exclusive travel rewards. We’re Looking For Someone Who: Has a proven track record in sales, marketing, or financial services. Excels at building and maintaining strong client relationships. Brings a positive, proactive, and goal-driven mindset.', 'Piliyandala, Colombo', '2026-06-23 17:17:03.19361+00', '2026-06-23 17:17:03.19361+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (270, 120, 4, 'Production Supervisor - Injection Molding', false, 'Supervisor position for a footwear and injection molding company located in Homagama. Requires experience in footwear, injection molding, or other production supervision. Free accommodation provided. Age 30+. High salary. Contact 0778884352 for more details.', 'Homagama, Colombo', '2026-06-23 17:39:27.713412+00', '2026-06-23 17:39:27.713412+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (271, 193, 4, 'Sales Executive', false, 'SALES EXECUTIVE (COLOMBO) Are you a results-driven sales professional looking for your next big move? A leading company is seeking a dynamic Sales Executive to join our team. Requirements: Valid Driving License is mandatory. Experience in Hardware, Tools, and Safety items is highly preferred. Strong communication and negotiation skills. What We Offer: Competitive High Salary, Company Vehicle + Fuel Allowance, Attractive Sales Commissions.', 'Colombo 10, Sri Lanka', '2026-06-23 17:39:27.777449+00', '2026-06-23 17:39:27.777449+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (209, 33, 5, 'Data Entry Typing - Part Time (Works from Homes) Online', true, 'Data Entry Typing - Part Time (Works from Homes) Online. Employer: IIF HOLDIN PVT LTD. Role: Data Entry Operator. Job type: Part Time. Salary per month: Rs 45,000 - 85,000. Required education: Ordinary Level. Required work experience (years): 0. Employer Website: https://forms.gle/TdTK2znBRnCjy9es6. About the role: Apply by clicking the link in Employer Website and filling the form. Do not apply via WhatsApp. We will contact you within 15 minutes. Our company is a registered government institution and a Software Company over 10 years old. We provide Data Entry Typing or other projects. Qualifications: Basic computer knowledge, ability to use email, any gender, any location in Sri Lanka. Can work from home using computer, laptop, or smartphone. Minimum 1 hour per day. Suitable for employed, unemployed, housewives, school leavers, university students, anyone seeking extra income. Benefits: Full Sinhala or English Guidelines, Daily job options (Typing, Simple Data Submits, Data Entry), Work from home any time, Withdraw money via eZ Cash/Bank deposit, 24hr support, Lifetime access within 30 minutes.', 'Panadura, Kalutara', '2026-06-23 17:17:03.210067+00', '2026-06-23 17:17:03.210067+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (210, 154, 4, 'Experienced Pharmacy Assistant (Male)', false, 'Join Royal Nursing Home (Pvt) Ltd. – Sri Lanka’s leading healthcare service provider! Location: Maharagama Branch (New Medical Equipment & Pharmacy Outlet). Requirements: Male candidate, Minimum 3 years experience in the pharmacy field, Friendly, responsible, and well-mannered personality, Valid motorcycle license. Salary: From Rs. 80,000/- upwards (based on experience). Additional Benefits: Free accommodation & meals (as required).', 'Maharagama, Colombo', '2026-06-23 17:19:00.792976+00', '2026-06-23 17:19:00.792976+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (211, 155, 4, 'Facility Executive', false, 'Facility Executive role in Kurunegala. Required qualifications: Full/Part Qualification in Facility Management or similar field. Minimum 2-5 years experience in a similar position. Good knowledge of: Housekeeping Operations, Electrical Maintenance, Plumbing Repairs, A/C Installation & Maintenance, Building Maintenance. Ability to lead Housekeeping and Maintenance teams to achieve organizational goals. Ability to negotiate with external Suppliers and manage Service & Supply Agreements. Send CV and details of two non-contactable Referees to careers@lyceum.lk. WhatsApp: 074 050 3067. Employer: Lyceum Global Holdings. Salary: Rs 80,000 - 90,000 per month.', 'Kurunegala City, Kurunegala, Sri Lanka', '2026-06-23 17:19:00.838894+00', '2026-06-23 17:19:00.838894+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (212, 156, 4, '𝐄-𝐁𝐈𝐊𝐄 - 𝐒𝐀𝐋𝐄𝐒 𝐀𝐒𝐒𝐈𝐒𝐓𝐀𝐍𝐓 𝐆𝐈𝐑𝐋', false, 'Sales Assistant role at NWOW E-Bike showroom in Divulapitiya. Responsibilities include selling company products, warehouse management, friendly customer service, daily office tasks. Qualifications: Female aged 18-28, willing to learn Sales/Marketing, English speaking ability. Benefits: Salary Rs 40,000 upwards, attendance and overtime allowances, annual bonuses, employee benefits.', 'Divulapitiya, Gampaha, Sri Lanka', '2026-06-23 17:19:00.859793+00', '2026-06-23 17:19:00.859793+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (213, 157, 4, 'Electronic Repairing Technician - Trainee', false, 'We need Trainee or experienced Mobile technician who can enroll into our technical team. Candidates should have completed Ordinary level examination, completed NVQ level 4 or equivalent qualification, age should be around 17-24 only, living around Panadura, Moratuwa, Kalutara or Pettah would be an advantage. Company will provide Attractive Salary Package, Monthly Target Allowance, EPF, ETF, Annual Bonuses, Annual Performance Allowance.', 'Panadura, Kalutara', '2026-06-23 17:19:00.8811+00', '2026-06-23 17:19:00.8811+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (283, 198, 5, 'Data Analyst', false, 'Analyze job market trends and prepare reporting dashboards for stakeholders.', 'Galle', '2026-07-30 08:31:45.200712+00', '2026-07-30 08:31:45.200712+00', 3);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (743, 430, 4, 'Sales Ninja', false, 'Take Your Career To The Are You Looking For ANew Challenge? Work times: Mon - Fri 12.00PM - 9.30PM Saturday - 12.00PM - 6.00PM Work Location: Colombo 3 (Onsite)', 'Colombo 3, Sri Lanka', '2026-08-07 03:15:53.788569+00', '2026-08-07 03:15:53.788569+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (214, 158, 4, 'Driver', false, 'Safely transport signage materials, finished products, tools, equipment, and personnel to project sites across Sri Lanka. Load, unload, secure, and inspect materials to prevent damage during transportation. Ensure timely delivery and collection of materials according to project schedules. Perform daily vehicle inspections and report any maintenance or repair requirements. Maintain vehicle cleanliness and ensure all required documents are up to date. Assist installation and production teams with loading, unloading, and site logistics when required. Follow all road safety regulations and company transportation procedures. Maintain accurate records of trips, fuel usage, and vehicle maintenance activities. Requirements: Valid Sri Lankan driving license with the required vehicle classes. Minimum 2 years of driving experience, preferably in logistics, construction, manufacturing, or a related field. Good knowledge of road networks and routes throughout Sri Lanka. Ability to handle and transport materials safely and responsibly. Basic knowledge of vehicle maintenance and safety inspections. Willingness to travel island-wide and work flexible hours when required. Good communication skills and a positive attitude. Clean driving record and commitment to safe driving practices. Benefits: Competitive salary package. Overtime and travel allowances. EPF & ETF benefits. Career growth opportunities. Training and skill development. Friendly and professional work environment.', 'Colombo 7, Colombo, Sri Lanka', '2026-06-23 17:19:00.915346+00', '2026-06-23 17:19:00.915346+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (215, 159, 4, 'Graphic Designer (Female) - Moratuwa', false, 'අප ආයතනයේ ග්‍රැෆික් ඩිසයින් වැඩ කිරීමට ගැහැණු ළමයෙකු අවශ්‍යයි. මසකට නිවාඩු 4. මාසික වැටුප 35000/= අමතන්න – 0755729848 මංජුල ෆර්නිචර්ස්, මොරටුමුල්ල.', 'Moratuwa, Colombo', '2026-06-23 17:19:00.940251+00', '2026-06-23 17:19:00.940251+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (216, 32, 4, 'Financial Consultant', false, 'Become a Financial Consultants and Financial Consultants Manager in Colombo! Are you an experienced professional ready for your next big step? Join the AIA team in Sri Lanka and build a rewarding career with unlimited growth potential. What You’ll Get: - High Earning Potential — Attractive monthly income + generous commissions + performance bonuses - Clear Career Progression — Comprehensive training, tools, and support to help you advance professionally - Be Your Own Leader — Full flexibility to manage your time and grow your own business with complete independence - Local & Global Recognition — Opportunities to be celebrated both in Sri Lanka and internationally, including exclusive travel rewards. We’re Looking For Someone Who: - Has a proven track record in sales, marketing, or financial services - Excels at building and maintaining strong client relationships - Brings a positive, proactive, and goal-driven mindset.', 'Nugegoda, Colombo', '2026-06-23 17:19:00.966235+00', '2026-06-23 17:19:00.966235+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (217, 160, 4, 'වෙල්ඩර් - ඔරුගොඩවත්ත', false, 'සුමති හෝල්ඩින්ස් ආයතනයට අනුබද්ධිත නඩත්තු කිරීම් අංශයට වෙල්ඩර්වරුන් (Welders) ඉක්මනින් බඳවා ගැනේ. අවශ්‍ය සුදුසුකම්: වයස අවුරුදු 55 ට අඩු පිරිමි, වෙල්ඩින් කටයුතු පිළිබඳ දැනුම සහ අවම වසරකවත් පළපුරුද්ද තිබීම, කණ්ඩායම් වශයෙන් වැඩ කිරීමේ හැකියාව, වගකීමෙන් හා කැපවීමෙන් සේවය කිරීම. ප්‍රතිලාභ: දැනුම, කුසලතාවය සහ අත්දැකීම් අනුව වැටුප සාකච්චා කල හැක, අතිකාල දීමනා, වෛද්‍ය රක්ෂණාවරන පහසුකම්, EPF/ETF, ස්ථිර සහ සුරක්ෂිත රැකියාවක්.', 'Peliyagoda, Gampaha, Sri Lanka', '2026-06-23 17:19:01.006648+00', '2026-06-23 17:19:01.006648+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (218, 161, 4, 'வீட்டுப் பணிப் பெண்', false, 'வீட்டுப் பணிப் பெண் தேவை. யாழ்ப்பாணத்தில் அமைந்துள்ள வீடொன்றிற்கு வீட்டு சமையல், வீட்டு வேலைகள், முதியவர் ஒருவருக்கு உதவியாக பணிபுரிய 45 வயதிலிருந்து 60 வயதிற்கு உட்பட்ட பணிப்பெண் தேவை. 👉(இந்து சமயத்தவர்கள் விரும்பத்தக்கது.) 👉தெரிவு செய்யப்படுபவர்கள் கிராம சேவகர் (G. S) உறுதிப்படுத்திய நற்சான்றிதழினை கையளித்தல் வேண்டும்.', 'Nuwara Eliya City, Nuwara Eliya', '2026-06-23 17:19:01.077551+00', '2026-06-23 17:19:01.077551+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (219, 162, 4, 'Garment Technical Executive', false, 'Prepare and manage garment technical specifications, tech packs, and measurement charts. Monitor garment construction, fitting, and technical requirements. Coordinate with merchandising, production, and quality teams to ensure smooth production flow. Identify technical issues and provide effective solutions during production. Conduct garment fitting evaluations and ensure required standards are maintained. Support production teams in improving quality and efficiency. Ensure buyer requirements and product specifications are properly followed. Requirements: 2-3 years of previous experience in the garment/apparel industry. Good knowledge of garment construction and production processes. Experience in technical operations, fitting, and quality standards. Ability to coordinate with different departments. Good communication and problem-solving skills. Experience in a similar role will be an added advantage.', 'Kurunegala City, Kurunegala', '2026-06-23 17:19:01.123949+00', '2026-06-23 17:19:01.123949+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (220, 163, 4, 'House Maid', false, 'வீட்டுப் பணிப் பெண் தேவை. யாழ்ப்பாணத்தில் அமைந்துள்ள வீடொன்றிற்கு வீட்டு சமையல், வீட்டு வேலைகள், முதியவர் ஒருவருக்கு உதவியாக பணிபுரிய 45 வயதிலிருந்து 60 வயதிற்கு உட்பட்ட பணிப்பெண் தேவை. 👉(இந்து சமயத்தவர்கள் விரும்பத்தக்கது.) 👉தெரிவு செய்யப்படுபவர்கள் கிராம சேவகர் (G. S) உறுதிப்படுத்திய நற்சான்றிதழினை கையளித்தல் வேண்டும்.', 'Badulla City, Badulla, Sri Lanka', '2026-06-23 17:22:13.912406+00', '2026-06-23 17:22:13.912406+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (221, 164, 4, 'Kitchen Helper', false, 'Kitchen Helpers Wanted. A leading restaurant located in Colombo 03 is looking for Kitchen Helpers for immediate recruitment. Qualifications: Both experienced and inexperienced (trainees) candidates are welcome to apply. Salary: (Based on experience/qualifications).', 'Colombo 3, Sri Lanka', '2026-06-23 17:22:14.009698+00', '2026-06-23 17:22:14.009698+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (222, 154, 4, 'ගෘහස්ථ හෙද පිරිමි සහ ගැහැණු සහාය රැකියා', false, 'ගෘහස්ථ හෙද රැකියා ඇබෑර්තුව. ගෞරවාන්විත ප්‍රබෝධමත් ස්ථිර රැකියාවක් එක්වන්න අප සමග. EPF, ETF සමග වැඩිම වැටුප් ගෙවන හා ස්ථිර රැකියාව ලබාදෙන දිවයිනේ එකම ආයතනය. මාසික වැටුප රු. 79,500/= සිට රු. 135,000/= දක්වා. වර්ෂ 2007 ආරම්භ වූ හෙද සේවිකාවන් 1600 රැකියාවේ යෙදෙන ISO 9001-2015 ජාත්‍යන්තර තත්ව සහතිකයෙන් හා 2023 වර්ෂයේ ආසියාවේ විශිෂ්ටතම හෙද සේවා ආයතනය වශයෙන් සම්මානයෙන් පිදුම් ලැබූ ශ්‍රී ලංකාවේ ප්‍රමුඛතම හා විශාලතම හෙද සේවා ආයතනය. අවශ්‍ය සුදුසුකම්: වයස අවුරුදු 20-50 අතර, උස අඩි 4යි අඟල් 10ට වැඩි, සාමාන්‍ය පෙළ දක්වා අධ්‍යාපනය, කායික හා මානසික නිරෝගී. ප්‍රතිලාභ: නොමිලේ ආහාර පාන, නේවාසික පහසුකම්, නිල ඇඳුම්, රාජකාරි ප්‍රවාහන පහසුකම්, EPF/ETF, නුපුහුණු අය සඳහා දින 28 ක නොමිලේ පුහුණුවක්.', 'Mount Lavinia, Colombo', '2026-06-23 17:22:14.041468+00', '2026-06-23 17:22:14.041468+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (223, 165, 4, 'Factory Laborer', false, 'International tyre manufacturing company. There is only employment opportunity for factory assistants. Benefits include excellent accommodation, electricity and water, meals and tea, snacks, transportation (accommodation to factory, factory to accommodation). All of this will cost only Rs. 200 per day. Only men are required for the job. Age (18-40).', 'Kaduwela, Colombo', '2026-06-23 17:22:14.077714+00', '2026-06-23 17:22:14.077714+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (224, 166, 4, 'Heavy Vehicle Driver', false, 'Heavy Vehicle Driver for a water distribution company in Rajagiriya area. Qualifications: Age 20-55, valid heavy vehicle driving license, responsible and disciplined. Experience preferred but not required. High salary with allowances, free food and drinks, safe work environment, holidays, EPF/ETF benefits. Contact: 071 012 0933, WhatsApp: 076 966 4065.', 'Rajagiriya, Colombo', '2026-06-23 17:22:14.096682+00', '2026-06-23 17:22:14.096682+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (225, 167, 4, 'HELPERS', false, 'Urgently hiring helpers for a leading institution in Colombo 12. Monthly salary: Rs 60,000 - 70,000. Benefits include: food allowance, attendance bonus for punctual reporting, high overtime pay, EPF and ETF contributions, and special incentive bonuses based on efficiency. Qualifications: healthy individuals aged 18-55, ability to work in a team and discipline, experience in delivery field is an added advantage. Accommodation not provided. Location: No. 206, Old Moor Street, Colombo 12.', 'Colombo 12, Sri Lanka', '2026-06-23 17:22:14.130063+00', '2026-06-23 17:22:14.130063+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (272, 36, 4, 'Store Keeper', false, 'Store Keeper Job Vacancy. Position: Store Keeper. Vacancies: 10. Employment Type: Full-Time. Salary: Rs. 40,000 – 90,000 per month. No prior experience required.', 'Malabe, Colombo, Sri Lanka', '2026-06-23 17:39:27.828586+00', '2026-06-23 17:39:27.828586+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (226, 158, 4, 'Welder', false, 'Perform welding, fabrication, and assembly of metal structures used in signage, branding, and advertising projects. Read and interpret fabrication drawings, shop drawings, and technical specifications. Carry out MIG, TIG, Arc, and other welding processes as required. Fabricate sign frames, support structures, mounting brackets, and custom metal components. Ensure all welding work meets quality, safety, and project requirements. Assist installation teams with the erection and fitting of signage structures on-site. Inspect completed work for dimensional accuracy, strength, and finish quality. Maintain welding equipment, tools, and work areas in safe and operational condition. Requirements: NVQ, Technical College qualification, or equivalent certification in Welding, Metal Fabrication, or a related field. Minimum 2 years of experience as a Welder or Fabricator. Ability to read and work from technical and fabrication drawings. Experience with mild steel, stainless steel, aluminum, and related fabrication materials. Familiarity with welding safety procedures and the proper use of PPE. Ability to work at heights and travel for island-wide installation projects. Ability to work independently and as part of a team. Valid riding or driving license will be an added advantage. Benefits: Competitive salary package. Overtime and travel allowances. EPF & ETF benefits. Career growth opportunities. Training and skill development. Friendly and professional work environment.', 'Colombo 7, Colombo, Sri Lanka', '2026-06-23 17:22:14.159169+00', '2026-06-23 17:22:14.159169+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (227, 168, 4, 'OFFICE ASSISTANT - (FEMALE)', false, 'ABILITY TO CALL FOLLOW UP AND REGISTER STUDENTS. COUNSELL STUDENTS ON OVERSEAS STUDY PROGRAMMES. BUILDING STRONG RELATIONSHIP WITH STUDENTS AND PARENTS. ASSIST WITH COURSE SELECTIONS AND APPLICATION PROCESS. EXCELLENT COMMUNICATION AND COUNSELLING SKILLS. EXPERIENCE IN STUDY ABROAD EDUCATION CONSULTANCY IS AN ADVANTAGE. TARGET DRIVEN AND STUDENT FOCUSED MINDSET. SALARY + ATTRACTIVE COMMISSIONS + OTHER BENEFITS.', 'Kottawa, Colombo', '2026-06-23 17:22:14.196129+00', '2026-06-23 17:22:14.196129+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (228, 169, 4, 'Kitchen Helper', false, 'We are looking for energetic and motivated individuals to join our restaurant team for the following positions: Salary: Rs. 35,000 + Service Charge 100%. Benefits: Accommodation provided, Staff meals provided, Uniforms provided, 6 days leave per month. If you are passionate about working in the hospitality industry and ready to grow with us, please send your CV or contact us today. Contact - MR Dasun 0777403052', 'Dehiwala, Colombo', '2026-06-23 17:22:14.209491+00', '2026-06-23 17:22:14.209491+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (229, 170, 4, 'Machine Operator', false, 'සමාගමේ නිෂ්පාදන හා මෙහෙයුම් කටයුතු සඳහා සහාය වීම', 'Wattala, Gampaha, Sri Lanka', '2026-06-23 17:22:14.218644+00', '2026-06-23 17:22:14.218644+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (230, 119, 4, 'Mechanical Generator Technician', false, 'Generator Technician needed for Powernet at No.74, Pansala Para, Maradana. High salary and allowances. Permanent employment. Annual salary increments and bonuses. Diploma from a recognized institution (NVQ) certificates given special attention. Salary negotiable based on experience and expertise. Must have knowledge of generator installation, ATS panels, installation, fault finding and repair.', 'Colombo 5, Sri Lanka', '2026-06-23 17:25:53.06647+00', '2026-06-23 17:25:53.06647+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (231, 166, 4, 'IT Assistant', false, 'IT Assistant role at a well-known educational institution in the Halavata area. Qualifications: Age 18-35, sat for GCE A/L, open to both trained and untrained individuals, basic English knowledge is an advantage, must have completed a computer course. Training provided. Competitive salary. Friendly, safe work environment. Working hours: 8:00 AM to 5:00 PM. Sundays and Poya days off.', 'Chilaw, Puttalam, Sri Lanka', '2026-06-23 17:25:53.117973+00', '2026-06-23 17:25:53.117973+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (284, 199, 4, 'Admin Coordinator', false, 'Office Coordinator job with a salary of Rs 65,000/-. Contact 0779161559 via WhatsApp for details. Job vacancies (trained/untrained) available. Interviews held daily until 30 vacancies are filled. This is not an agency; direct recruitment by the company. Choose from branches in Nawaala, Nugegoda, Maharagama, Kottawa, Homagama, Boralesgamuwa.', 'Maharagama, Colombo', '2026-08-05 03:56:20.836909+00', '2026-08-05 03:56:20.836909+00', 30);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (232, 171, 4, 'ලිපිකරු / ගිණුම් ලිපිකාරිණි - Kandy', false, 'WE ARE HIRING – OFFICE ASSISTANTS / ACCOUNTS CLERKS. Position: Office Assistant / Accounts Clerk. Gender: Male & Female. Age: 17 – 35 Years. Experience: Trainees & Experienced Welcome. Education: GCE O/L or Above. Job Responsibilities: Assist with basic office work, Help manage files and documents, Support daily office activities, Handle simple computer work (training provided), Maintain office cleanliness and organization. Salary: Attractive Salary + Allowances. Career Growth: Training Provided for Beginners.', 'Kandy City, Kandy', '2026-06-23 17:25:53.137415+00', '2026-06-23 17:25:53.137415+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (233, 36, 4, 'Injection and Blow Moulding Machine Operator', false, 'Injection Molding & Blow Molding Machine Operator (Setter) Technicians required for a well-known plastic manufacturing company located in Ratmalana. Responsibilities include operating and maintaining injection molding and blow molding machines. Qualifications: Minimum 5 years of hands-on experience required. Candidates with knowledge of other maintenance work related to the plastic manufacturing industry will be given preference. Millwright knowledge is an added advantage. Attractive salary package for suitable candidates.', 'Ratmalana, Colombo', '2026-06-23 17:25:53.153128+00', '2026-06-23 17:25:53.153128+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (234, 32, 4, 'Team Leader''s Manager - Wariyapola', false, 'Professional Wealth Planner opportunity with the world''s largest insurance company. Benefits include: leading global career, rapid income growth with professional competence, financial freedom and time freedom, promotions with professional excellence, local and international recognition, domestic and foreign travel opportunities. This opportunity is for those with good social networks, professional connections, trustworthiness in society, willingness to achieve professional goals through commitment, and experience in financial services, marketing, banking services, or insurance services. Required education: Ordinary Level. Required work experience: 3 years.', 'Wariyapola, Kurunegala', '2026-06-23 17:25:53.194987+00', '2026-06-23 17:25:53.194987+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (235, 172, 4, 'Technician - Computer Hardware', false, 'ගම්පහ නගරයේ පිහිටි පරිඝණක අළුත්වැඩියා සහ අලවිසැලකට පළපුරුදු Technician කෙනෙකු අවශ්‍යව ඇත. Sales සහ පරිඝණක අලවිය පිළිබද දැනුම අමතර සුදුසුකමකි. පළපුරුද්ද සහ දක්ෂතාවය මත වැටුප් සහ අමතර දීමනා. ගම්පහ අවට අය පමණක් අයදුම් කරන්න.', 'Gampaha City, Gampaha, Sri Lanka', '2026-06-23 17:25:53.213112+00', '2026-06-23 17:25:53.213112+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (236, 127, 4, 'Office Coordinator- Colombo', false, '💰රු. 60,000/- ක පඩියක් ලැබෙන, ලංකාවේ එකම Office Coordinator Job එක🖤 0776962219 අංකයට WhatsApp කර විස්තර දැනගන්න. දිවයින පුරා රැකියා ඇබෑර්තු Job Vacancy (පුහුණු/නුපුහුණු) විශේෂ කරුණු 01) ඔබගේ සියලුම විමසීම් (FAQ) වලට පිළිතුරු WhatsApp Catalog 1,Catalog 2,Catalog 3, Catalog 4හි තබා ඇත. 02) Vacancies 30ක් පමණක් සම්පූර්ණ වනතුරු අද දින සිට සෑම දිනකම සම්මුඛ පරීක්ෂණ පැවැත්වේ. වේලාවක් වෙන්කරගෙන පැමිණෙන්න. 03) සම්මුඛ පරීක්ෂණයට පැමිණිය යුතු ස්ථානය හා පැමිණෙන ආකාරය WhatsApp Catalog 1,Catalog 2,Catalog 3, Catalog 4හි ඇත.. 04) මෙය රැකියා Agency එකක් නොවන අතර අප ආයතනයටම බඳවා ගැනේ. 05) Call ලබා ගැනීමේදී සාමාන්‍ය ඇමතුම් පමණක් ගන්න (WhatsApp නොගන්න) 06) ඔබ කැමැති ශාඛාවක් තෝරා ගන්න. නාවල, නුගේගොඩ, මහරගම, කොට්ටාව, හෝමාගම, පිටකොටුව, බම්බලපිටිය, කොල්ලුපිටිය, බොරලැස්ගමුව.', 'Kotte, Colombo', '2026-06-23 17:25:53.221926+00', '2026-06-23 17:25:53.221926+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (237, 173, 4, 'Office Assistant (කාර්‍යාල සහායක)', false, 'කොළඹ 01 පිහිටි ප්‍රධාන පෙලේ බැංකුව මූලස්ථානයේ සහ පහත සදහන් ශාඛාවන් සදහා කොන්ත්‍රාත් පදනම් මත කාර්යාල සහායකයින් සදහා (Office Assistants) සේවයේ යෙදව්ම සඳහා පහත සඳහන් සුදුසුකම් ඇති අය වෙතින් (පිරීම් අයදුම්කරුවන් පමණි) අයදුම්පත් කැඳවේ. සුදුසුකම්: 1 වයස 18-24 අතර, 2 විෂයයන් 3කට සම්මාන සාමාර්ථ සහිතව මව් භාෂාව, ගණිතය සහ ඉංග්‍රීසි ව්ෂය ඇතුලත් වනසේ අ. පො. ස. (සා. පෙ.) විභාගය එකවර සමත්ව තිබීම (Same sitting), 3 කණ්ඩායම් හැගිමෙන් කටයුතු කිරීමේ සහ ඉහළ කැපවීමකින් යුතුව සේවයේ යෙදීමේ හැකියාව.', 'Colombo 1, Sri Lanka', '2026-06-23 17:25:53.235608+00', '2026-06-23 17:25:53.235608+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (238, 174, 4, 'New Supervisor', false, 'Supervisor position. Training period includes allowance of 40,000 - 45,000, health coverage, accommodation and food, short-term promotion. After training: basic salary of 75,000, ETF, EPF, life insurance, foreign travel. Candidates should SMS name, address, phone number or call the provided number. Required education: Ordinary Level. No prior work experience required.', 'Kegalle City, Kegalle, Sri Lanka', '2026-06-23 17:25:53.250773+00', '2026-06-23 17:25:53.250773+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (239, 175, 4, 'Marketing Executive', false, 'Metro is looking for energetic and target-oriented Marketing Executives to promote and market our electronics and battery products. Key Responsibilities: Promote and sell electronics and battery products to dealers and retail customers. Identify and develop new business opportunities. Visit customers and maintain good business relationships. Achieve monthly sales targets. Prepare sales and market reports. Requirements: G.C.E. O/L or A/L qualification. Good communication and negotiation skills. Previous marketing/sales experience is an advantage. Valid riding/driving licence will be an added advantage. Age between 20–35 years preferred. Salary & Benefits: Monthly Salary: Rs. 25,000 – 100,000 (based on experience and performance) Sales Incentives / Commission Career Growth Opportunities', 'Colombo 3, Sri Lanka', '2026-06-23 17:25:53.263741+00', '2026-06-23 17:25:53.263741+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (285, 200, 4, 'Accounts Assistant', false, 'A vacancy exists for an experienced Accounts Assistant / Assistant Accountant in a company at Katana, Demanhandiya. Full-time / Part-time. Knowledge of working in QuickBooks accounting software is essential. Retired persons are also considered. Please email the application/biodata to vacatchfc62@gmail.com', 'Negombo, Gampaha, Sri Lanka', '2026-08-05 03:56:20.846054+00', '2026-08-05 03:56:20.846054+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (799, 449, 4, 'Senior Manager – IT Governance', false, 'Degree in Computer Science/IT/related field, 4-5 years managing IT Governance and IT Security in banking/financial industry including managerial experience, certifications like CISA/CRISC/ISO 27001 Lead Implementer/CISM/CISSP required. Age below 50.', 'Kelaniya, Sri Lanka', '2026-08-18 10:03:49.488685+00', '2026-08-18 10:03:49.488685+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (240, 176, 4, 'Packing Officer', false, 'දිවයිනේ සුප්‍රසිද්ධ නිෂ්පාදන කර්මාන්ශාලා කිහිපයකට කඩිනමින් කාන්තා පිරිමි දෙපාර්ශ්වයේම සේවක, සේවිකාවන් බදවා ගැනීම් දැන් ඇරඹුනා. අභිමානවත් රැකියාවකට හිමිකම් කීමට මෙන්න ඔබට අනගි අවස්ථාවක්. චොකලට්, ටොෆි, ටිපිටිප්, වතුර බෝතල්, පළතුරු වර්ග, කේක් වර්ග, ප්ලාස්ටික් ඇසුරුම්, සබන් ක්‍රීම් පව්ඩර් කර්මාන්ශාලා කිහිපයකට ඇසුරුම් අංශය, ලේබල් අංශ, නිෂ්පාදන අංශය, Superwiser/Qc අංශය සදහා නවක සේවක සේවිකාවන් බදවා ගනු ලැබේ. වැටුප 55000-85000 අතර, අතිකාල දීමනා, ආහාර නවාතැන් පහසුව, කණ්ඩායම් වශයෙන් පැමිනීමට අවස්තා, වැටුපට අමතරව තවත් සුවිශේෂී දීමනා රැසක්.', 'Kurunegala City, Kurunegala', '2026-06-23 17:29:25.031049+00', '2026-06-23 17:29:25.031049+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (241, 177, 4, 'Playhouse Assistant', false, 'Supervise children during play sessions, ensure a safe, clean, and welcoming play area, assist with activities, events, and birthday parties, communicate with parents and visitors, support day-to-day playhouse operations. Requirements: Female candidates only, friendly, patient, and reliable, passion for working with children, good communication and teamwork skills, previous experience is an advantage but not required.', 'Colombo 03, Sri Lanka', '2026-06-23 17:29:25.088197+00', '2026-06-23 17:29:25.088197+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (242, 178, 4, 'Packing Officer', false, 'Recruiting trained and untrained male and female workers urgently for several well-known manufacturing factories in Sri Lanka. Departments include Packing, Labeling, Production, Supervisor/QC. Benefits include overtime allowance, food and accommodation, group/friend applications allowed, and special allowances. Salary Rs 65,000-75,000. Locations include Colombo, Horana, Piliyandala, Peliyagoda, Rajagiriya, Kelaniya, Bandaragama, Kadawatha, Wattala, Divulapitiya, Minuwangoda, Katunayake, Negombo, Ja-Ela, Kadana, Seeduwa, Gampaha, Ratmalana, Panadura. Minimum education: GCE O/L. No experience required.', 'Colombo 3, Sri Lanka', '2026-06-23 17:29:25.117723+00', '2026-06-23 17:29:25.117723+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (243, 32, 4, 'Team Leader''s Manager - Bandaragama', false, 'Professional Wealth Planner opportunity with the world''s largest insurance company. If selected: leading global career, rapid income growth with professional competence, financial freedom and time freedom, promotions with professional excellence, local and international recognition, domestic and foreign travel opportunities. Suitable for those with good social connections, professional networks, trustworthiness in society, willingness to achieve professional goals through commitment, and experience in financial services, marketing, banking, or insurance services.', 'Bandaragama, Kalutara', '2026-06-23 17:29:25.148009+00', '2026-06-23 17:29:25.148009+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (245, 179, 4, 'පාරිභෝගික සේවා සහයිකා (Female)-කුරුණෑගල', false, 'තනතුර : පාරිභෝගික සේවා සහයිකා (Female) – කුරුණෑගල. සුදුසුකම් : අ.පො.ස. (සා/පෙළ) සමත් වී තිබිය යුතුය. වයස අවුරුදු 18 සිට 40 දක්වා විය යුතුය. ඉක්මන් සහ යහපත් සන්නිවේදන හැකියාව තිබිය යුතුය. පාරිභෝගික සේවය පිළිබඳ උනන්දුවක් සහ කැපවීමක් තිබිය යුතුය. රැකියාවේ කාර්ය භාරය : පාරිභෝගිකයන්ට මිත්‍රශීලීව හා කාර්යක්ෂමව සේවය සැපයීම. පාරිභෝගික විමසීම් හා පැමිණිලි විසඳීම. පාරිභෝගිකයන්ට නිෂ්පාදන තෝරා ගැනීමට සහය වීම. ප්‍රතිලාභ : ආකර්ශනීය වැටුපක් සහ අනෙකුත් වරප්‍රසාද රැසක් පිරිනැමේ. ඉහළ හා තරඟකාරී වැටුප් වේතනය. රැකියාවට අමතරව වෘත්තීය පුහුණුව. අභ්‍යන්තර උසස්වීම් අවස්ථා හා වෙනත් බොහෝ ප්‍රතිලාභ. රක්ෂනාවරනයක් ලබා දීම.', 'Kurunegala City, Kurunegala, Sri Lanka', '2026-06-23 17:29:25.201096+00', '2026-06-23 17:29:25.201096+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (246, 121, 4, 'Network and Systems Engineer', false, 'WE ARE HIRING Systems & Network Engineer Digitech Holdings (Pvt) Ltd is seeking a dynamic, motivated, and technically competent Systems & Network Engineer to join our growing team at our Head Office in Malabe. Key Responsibilities: - Design, implement, monitor, and maintain enterprise network infrastructure. - Manage and support Windows and Linux servers. - Configure and maintain routers, switches, firewalls, VPNs, and wireless networks. - Ensure network security, system reliability, and business continuity. - Troubleshoot hardware, software, server, and network-related issues. - Manage backups, disaster recovery procedures, and data protection measures. - Monitor system performance and recommend infrastructure improvements. - Provide technical support to users and coordinate with vendors when required. - Maintain IT documentation, policies, and operational procedures. Requirements: - Bachelor''s Degree or Higher Diploma in Information Technology, Computer Science, Network Engineering, or a related field. - Minimum 2–5 years of experience in Systems and Network Administration. - Sound knowledge of Windows Server, Active Directory, Microsoft 365, and virtualization technologies. - Experience with network devices, firewalls, VPNs, and cybersecurity best practices. - Familiarity with cloud platforms such as Microsoft Azure or AWS will be an added advantage. - Professional certifications such as CCNA, CCNP, MCSA, Microsoft Certified, CompTIA Network+, or equivalent will be advantageous. - Strong troubleshooting and analytical skills. - Excellent communication and teamwork abilities. What We Offer: - Competitive remuneration package. - Opportunities for professional growth and career advancement. - Exposure to modern technologies and enterprise systems. - Friendly and professional working environment.', 'Malabe, Colombo, Sri Lanka', '2026-06-23 17:29:25.263386+00', '2026-06-23 17:29:25.263386+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (247, 132, 4, 'Office Coordinator - Colombo', false, 'Office Coordinator job in Colombo. Salary Rs 65,000 - 70,000 per month. Required education: Ordinary Level. No prior work experience required. Branches available in Nugegoda, Maharagama, Kottawa, Homagama, Pettah, Bambalapitiya, Kollupitiya, Boralesgamuwa. Interviews conducted daily until 30 vacancies are filled. Contact via WhatsApp at 0776716233 for details.', 'Colombo, Sri Lanka', '2026-06-23 17:29:25.289485+00', '2026-06-23 17:29:25.289485+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (248, 180, 4, 'Office Assistant', false, 'Office Assistant. Gender: Male / Female. Age: 18 years or Above. Qualifications: Good Computer Knowledge, Basic English & Communication Skills. Location: Minuwangoda & Nuwara Eliya.', 'Minuwangoda, Gampaha, Sri Lanka', '2026-06-23 17:29:25.307097+00', '2026-06-23 17:29:25.307097+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (249, 181, 4, 'Recruitment Executive', false, 'Key Responsibilities: Attract suitable candidates for relevant positions from Colombo and outstation locations. Handle end-to-end recruitment and onboarding processes. Guide suitable candidates to the relevant locations to fill vacancies. Manage bulk recruitment requirements within defined timelines. What We Are Looking For: Degree or professional qualification in HRM or related field. 1–3 years of experience in Recruitment. Sale & Marketing Experience will be an added advantage. Experience in technical hiring will be an added advantage. Ability to work independently and meet deadlines. Valid riding license with own motorcycle is mandatory.', 'Colombo 3, Sri Lanka', '2026-06-23 17:29:25.325464+00', '2026-06-23 17:29:25.325464+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (250, 121, 4, 'Office Coordinator', false, 'WE ARE HIRING OFFICE COORDINATOR. Digitech Holdings (Pvt) Ltd, a growing technology and engineering solutions provider based in Malabe, is looking for a dynamic and organized Office Coordinator / Project Coordinator to join our team. Key Responsibilities: Coordinate and monitor ongoing projects undertaken by the company. Liaise with customers, suppliers, technicians, subcontractors, and project teams to ensure smooth project execution. Schedule site visits, installations, maintenance work, and service calls. Follow up on project progress and maintain project records and documentation. Prepare quotations, reports, invoices, and other office correspondence as required. Coordinate day-to-day office operations and administrative activities. Handle customer inquiries and maintain professional communication with stakeholders. Assist management with project coordination, procurement, and operational support. Maintain project schedules and ensure timely follow-up on pending tasks and deliverables. Requirements: Minimum one (1) year of experience in administration, office coordination, customer service, project coordination, or a related field is preferred. Good communication skills in Sinhala and English. Proficiency in Microsoft Office applications (Word, Excel, Outlook). Strong organizational, coordination, and multitasking abilities. Ability to work independently and manage multiple tasks simultaneously. Positive attitude, willingness to learn, and strong interpersonal skills. School leavers with strong communication and organizational skills are also encouraged to apply. What We Offer: Attractive salary package. Friendly and professional working environment. Opportunities for career growth and professional development. Exposure to project coordination and management activities across diverse technology and engineering projects.', 'Malabe, Colombo, Sri Lanka', '2026-06-23 17:33:01.829107+00', '2026-06-23 17:33:01.829107+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (251, 182, 4, 'Operations Analyst', false, 'We are seeking a dynamic and detail-oriented Operations Analyst to join our team at SA Carz Holdings - Nugegoda. This role bridges logistics, basic finance, and daily administration, making it ideal for a proactive professional who excels at organizing data and managing essential business documentation. Key Responsibilities: • Import Documentation: Prepare and manage import-related documents, including Commercial Invoices, Bills of Lading, and other clearing requirements. • Financial Tracking: Prepare and update regular cash flow statements, tracking both inflows and outflows. • Banking Coordination: Communicate and negotiate with banks regarding import documentation, trade financing, and general finance matters. • Reporting: Prepare comprehensive economic, financial, and management reports for review. • Administration: Handle day-to-day office administrative documentation and maintaining organized filing systems. Skills & Qualifications Needed: • Education: A Diploma-level qualification is required; an undergraduate Degree is an added advantage. • Technical Skills: Strong proficiency in Microsoft Excel (must know how to use Pivot Tables, graphs, and summarize data) and ability to create PowerPoint presentations. • Finance Knowledge: A solid basic understanding of fundamental accounting principles. • Communication: Good written and verbal communication skills with a sound command of English. • Work Ethic: Highly reliable, with the ability to work independently and make data-driven decisions when required.', 'Nugegoda, Colombo', '2026-06-23 17:33:02.414844+00', '2026-06-23 17:33:02.414844+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (252, 160, 4, 'මුදල් ආරක්ශක නිලධාරී - මීගමුව', false, 'සුමති හෝල්ඩින්ස් ආයතනයට අනුබද්ධිත මීගමුව ශාඛාවට මුදල් ආරක්ශක නිලධාරීන් ඉක්මනින් බඳවා ගනු ලැබේ. අවශ්‍ය සුදුසුකම්: වයස අවුරුදු 55 ට අඩු පිරිමි, මීගමුව අවට පදිංචි, විශ්‍රාමික හමුදා නිළධාරීන්, පොලිස් නිළධාරීන් සඳහා ප්‍රමුඛතාවය දෙනු ලැබේ, විශ්වාසවන්ත සහ අවංක බව. සේවා කාලය - උදෑසන 07.00 - සවස 04.30, සවස 04.30න් පසු අතිකාල දීමනා ගෙවනු ලැබේ. ප්‍රතිලාභ: රුපියල් 65,000/= ක ස්ථීර මාසික වැටුපක්, අතිකාල දීමනා සමග මාසිකව රුපියල් 85,000 කට වැඩි වැටුපක්, වෛද්‍ය රක්ෂණාවරන පහසුකම් සහ තවත් අමතර ප්‍රතිලාභ රැසක්, EPF / ETF, ස්ථිර සහ සුරක්ෂිත රැකියාවක්.', 'Negombo, Gampaha, Sri Lanka', '2026-06-23 17:33:02.543763+00', '2026-06-23 17:33:02.543763+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (253, 183, 4, 'Storekeeper', false, 'CCTVPARTNERS – Storekeeper வேலைவாய்ப்பு. Responsibilities: Arrange goods arriving at the store properly, unload & upload goods, record item details correctly in the system, carefully maintain stock levels, keep the store area clean and tidy, work responsibly with the team. Qualifications: Young and energetic male applicant, must be ready for physical work, basic computer knowledge preferred, punctual, responsible and honest worker. Benefits: Accommodation provided.', 'Nugegoda, Colombo', '2026-06-23 17:33:02.569366+00', '2026-06-23 17:33:02.569366+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (254, 156, 4, 'Sales Assistant', false, 'Sales Assistant for E-Bike showroom in Marawila. Responsibilities include: selling company products, warehouse management, friendly customer service, daily office tasks. Qualifications: Female aged 18-28, willingness to learn Sales/Marketing, English speaking ability. Benefits: Salary from Rs 40,000 upwards, attendance and overtime allowances, annual bonuses, employee benefits.', 'Marawila, Puttalam, Sri Lanka', '2026-06-23 17:33:02.589956+00', '2026-06-23 17:33:02.589956+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (255, 184, 4, 'Production Quality Supervisor', false, 'Production Quality Supervisor position at a coir product manufacturing factory located in Dankotuwa. Responsibilities include production supervision. Benefits include high salary, accommodation and food. Must be able to work night shifts as required. Qualifications: Male, age between 30-50 years, Advanced Level education, 2 years work experience.', 'Negombo, Gampaha, Sri Lanka', '2026-06-23 17:33:02.611209+00', '2026-06-23 17:33:02.611209+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (256, 120, 4, 'Store Helper', false, 'හෝමාගම පිහිටි නිෂ්පාදන ආයතනයක් සදහා ගබඩා සහයක, මැෂින් ඔපරේටර්, ඉන්ජෙක්ෂන් මොල්ඩින් මැෂින් ඔපරේටර් , හෙල්පර් ඇබැර්තු ඇත. පුහුණු / නුපුහුණු නොමිළේ නවාතැන් පහසුකම් ඇත. ඉහල වැටුප්.', 'Homagama, Colombo', '2026-06-23 17:33:02.630947+00', '2026-06-23 17:33:02.630947+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (257, 185, 4, 'පාරිභෝගික අලෙවි නියෝජිත', false, 'Camozee (Pvt) Ltd is a leading photography and videography equipment retailer in Sri Lanka, offering cameras, lenses, accessories, studio equipment, film photography products, and printing solutions. We are looking for an energetic and responsible individual to join our team as a Customer Sales Representative. Key Responsibilities: 1. Assist customers in selecting suitable photography, videography, and related products. 2. Provide excellent customer service both in-store and through online platforms. 3. Handle daily sales transactions and customer inquiries. 4. Manage inventory and stock movements. 5. Receive, label, organize, and maintain stock accurately. 6. Monitor stock levels and report low-stock items. 7. Prepare products for display and maintain showroom appearance. 8. Assist with packing and dispatching customer orders. 9. Support social media and promotional activities when required. 10. Maintain accurate sales and inventory records. 11. Work closely with the management team to achieve sales targets. Requirements: 1. Good communication and interpersonal skills. 2. Friendly, customer-focused attitude. 3. Basic computer knowledge. 4. Ability to work independently and as part of a team. 5. Strong organizational and stock management skills. 6. Interest in photography, cameras, or technology is an advantage. 7. Previous retail or sales experience is preferred but not mandatory. Salary per month: Rs 40,000 - 50,000.', 'Colombo 4, Colombo, Sri Lanka', '2026-06-23 17:33:02.678567+00', '2026-06-23 17:33:02.678567+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (258, 129, 4, 'Supervisor', false, 'We are looking for energetic and motivated individuals to join our restaurant team for the following positions: Salary: Rs. 70,000 + Service Charge 100%. Benefits: Accommodation provided, Staff meals provided, Uniforms provided, 6 days leave per month. If you are passionate about working in the hospitality industry and ready to grow with us, please send your CV or contact us today. Contact - MR Dasun 0777403052', 'Dehiwala, Colombo', '2026-06-23 17:33:02.730147+00', '2026-06-23 17:33:02.730147+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (259, 120, 4, 'Production Manager - Injection Molding', false, 'Production Manager role for a footwear and injection molding company located in Homagama. Requires experience in footwear or injection molding supervision. Free accommodation provided. Age 35+. High salary. For more details call 0778884352.', 'Homagama, Colombo', '2026-06-23 17:33:02.744737+00', '2026-06-23 17:33:02.744737+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (261, 187, 4, 'රූපලාවන්‍ය ශිල්පිනි', false, 'අපගේ රූපලාවණ්‍ය සලූනයට එකතු වීමට මේක්අප් සහ හේයා සලූන් සේවාවන් පිළිබඳ බහු දක්ෂතා ඇති කාන්තා අපේක්ෂිකාවක් සොයමින් සිටිමු මෙය කාන්තාවන් පමණක් සේවයකරන (ladies only salon). ගනුදෙනුකරුවන්ට උසස් මට්ටමේ සේවාවන් ලබාදීමට හා වෘත්තීයමය පරිසරයක් තුළ වැඩ කිරීමට හැකියාව තිබිය යුතුය. වයස අවුරුදු 18ත් - 28ත්. අවම වසරක පලපුර්ද්ද. කාන්තාවන් සදහා පමණනි. ප්‍රතිලාභ: ඉහල වැටුප්, ඇතිකල දීමණා, සියලුම වැඩ සදහා 15% කොමිස් ලබාදේ, වසරකට දෙවරක් බෝනස්, පිට පළත් අය සදහා නැවතීමට පහසුකම් නොමිලේ ලබාදේ, මිතුරාත්මක සේවා පරිසරය, වෘත්තීය වර්ධන අවස්ථා, පුහුණු ලබාදේ.', 'Kotikawatta, Colombo', '2026-06-23 17:35:53.672823+00', '2026-06-23 17:35:53.672823+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (262, 32, 4, 'Team Leader''s Manager - Dehiattakandiya', false, 'Professional Wealth Planner opportunity with the world''s largest insurance company. Benefits include: leading global career, rapid income growth with professional competence, financial freedom and time freedom, promotions with professional excellence, local and international recognition, domestic and foreign travel opportunities. Suitable for those with good social networks, professional connections, trustworthiness in society, commitment to achieve professional goals, and experience in financial services, marketing, banking, or insurance services.', 'Dehiattakandiya, Ampara', '2026-06-23 17:35:53.700496+00', '2026-06-23 17:35:53.700496+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (263, 188, 4, 'Supervisor', false, 'රාජගිරියේ වාහන අමතර කොටස් ගෙන්වා බෙදා හරින ආයතනයක් හා ගොඩනැගිලි ද්‍රව්‍ය විකිණීමේ ආයතනයක් සඳහා සුපරීක්ෂක තනතුරු පුරප්පාඩු ඇත. සුදුසුකම් : *මෙහෙයුම් කටයුතු සඳහා පලපුරුද්ද. *වයස අවුරුදු 20-30ත් අතර. *සාමාන්‍ය පෙළ සමත්. *වැටුප රු. 70,000/= සිට *නවාතැන් පහසුකම් ඇත. *කෑම බීම සකසා ගැනීම සඳහා පහසුකම් ඇත.', 'Rajagiriya, Colombo', '2026-06-23 17:35:53.720342+00', '2026-06-23 17:35:53.720342+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (264, 189, 4, 'Supervisor', false, 'ඔබත් රැකියාවක් අපේක්ෂාවෙන් සිටින අයෙක්ද..? දිවයිනෙ සෑම දිස්ත්‍රික්කයක්ම ආවරණය වන පරිදි අප ආයතනයේ නව ශාඛාවන් 12 ක කඩිනම් පුරප්පාඩු සදහා ආධුනිකයින් පුහුනු කර බදවා ගැනේ. රැකියාව: සුපරීක්ෂක. පුහුනු කාලය තුල:- 40000 - 45000 අතර දීමනා, සෞඛ්‍ය ආවරණයක්, නවාතැන් පහසුකම් හා ආහාර පාන, කෙටිකාලීන උසස් වීම. පුහුනුවෙන් පසුව: 75000 මූලික වැටුපක්, ETF, EPF ඇතුලු වරප්‍රසාද, ජීවිත රක්ෂණ ආවරණයක්, විදෙස් සංචාර.', 'Peradeniya, Kandy, Sri Lanka', '2026-06-23 17:35:53.75076+00', '2026-06-23 17:35:53.75076+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (265, 190, 4, 'Sales Assistant', false, 'Position: Sales Assistant - Pettah. Requirements: Gender: Male candidates only; Age Limit: 18 – 35 years; Experience: Minimum 1 year experience in the supermarket field is required; Working Days: 7 days per week; Working Hours: 8.45 AM – 6:00 PM; Important Notice: During seasonal months (July, August, September, December, and January), employees are required to work every day, including Poya days and mercantile holidays. Working hours during these months may vary depending on operational requirements. Responsibilities: Must be hardworking, customer-focused, and ready to grow with the team. Provide efficient service to customers within the supermarket environment. Benefits: Leave: 1½ days off on a roster basis. We offer an attractive remuneration package with above market standards & other benefits for the suitable candidate.', 'Colombo 14, Sri Lanka', '2026-06-23 17:35:53.759801+00', '2026-06-23 17:35:53.759801+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (266, 120, 4, 'Production Coordinator - Footwear', false, 'Position : Production Coordinator. Please refer below advertisement for more information', 'Homagama, Colombo', '2026-06-23 17:35:53.771202+00', '2026-06-23 17:35:53.771202+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (267, 191, 4, 'Spare Parts Store Keeper', false, 'ගබඩා පාලක (වාහන අමතර කොටස් සහ උපාංග ) අපගේ වාහන අමතර කොටස් සහ උපාංග (Vehicle Spare Parts & Body Parts) ගබඩාව ක්‍රමවත්ව කළමනාකරණය කිරීම සඳහා කාර්යක්ෂම, පළපුරුදු ගබඩා පාලකවරයෙකු (Storekeeper) වහාම බඳවා ගැනේ. ප්‍රධාන වගකීම් සහ රාජකාරි: •තොග පාලනය: ලැබෙන වාහන අමතර කොටස් සහ බොඩි පාට්ස් ඇනවුම් කිරීම සහ පරික්ෂා කර, ක්‍රමවත්ව ගබඩා කිරීම සහ නිකුත් කිරීම. •දත්ත පවත්වා ගැනීම: පරිගණක මෘදුකාංග (Software/Excel) ආධාරයෙන් තොග වාර්තා නිවැරදිව පවත්වා ගැනීම සහ මාසිකව තොග පරීක්ෂා කිරීම. •ඇණවුම් නිකුත් කිරීම: කාර්මික ශිල්පීන්ට හෝ පාරිභෝගිකයින්ට අවශ්‍ය නිවැරදි අමතර කොටස් ප්‍රමාදයකින් තොරව ඇවුම් කිරීම සහ නිකුත් කිරීම. •සුදුසුකම් සහ පළපුරුද්ද:පළපුරුද්ද: වාහන අමතර කොටස් ක්ෂේත්‍රයේ අවම වශයෙන් වසර 2-3 ක සේවා පළපුරුද්ද. අධ්‍යාපනය: අ.පො.ස. (සා.පෙ.) හෝ (උ.පෙ.) සමත් වීම. (සැපයුම් දාම හෝ ලොජිස්ටික්ස් පිළිබඳ පාඨමාලාවක් හදාරා තිබීම අමතර සුදුසුකමකි). තාක්ෂණික දැනුම: MS Excel හෝ ගබඩා කළමනාකරණ මෘදුකාංග හැසිරවීමේ මූලික පරිගණක දැනුම. විශේෂ දැනුම: ප්‍රරමුඛ පෙළේ වාහන මාදිලි, එන්ජින් කොටස් සහ බොඩි පාට්ස් පිළිබඳව ඇති මනා දැනුම.', 'Matara City, Matara, Sri Lanka', '2026-06-23 17:35:53.787763+00', '2026-06-23 17:35:53.787763+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (268, 192, 4, 'පුහුණු / නුපුහුණු ලොන්ඩ්‍රි සහයකයින්', false, 'ශ්‍රී ලංකාවේ උසස් තත්ත්වයේ අතිනවීන රෙදි සේදුම් යන්ත්‍ර වලින් සමන්විත, කොළඹ සහ කළුතර නගරයන්හි පාරිභෝගික ඇඟලුම් සහ හෝටල් රෙදිපිළි පිරිසිදු කිරීමේ විශාලම ආයතනය වන ද ලොන්ඩ්‍රොමැට් ආයතනය සමඟ ඔබේ අනාගතය ඇරඹුමට අවස්ථාවක්. සුදුසුකම්: කලුතර නගරය අවට පදිංචිය, වයස 18-45 ත් අතර වීම. කාර්‍ය සාධන දීමනා, ආහාර සඳහා ලබාදෙන දීමනා සමඟ නොමිලේ ලබාදෙන පුහුණුව.', 'Kalutara City, Kalutara', '2026-06-23 17:35:53.858825+00', '2026-06-23 17:35:53.858825+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (269, 190, 5, 'Sales Assistant', false, 'Assist with daily store operations. Support customers in a friendly manner. Maintain cleanliness and organization of the workplace. Handle assigned duties responsibly. Requirements: Male candidates only, Age between 18 – 45 years, Good communication and interpersonal skills, Ability to work in a team environment, Part-time availability is required. Benefits: Attractive salary package and other benefits for suitable candidates, Friendly and supportive working environment.', 'Colombo 14, Sri Lanka', '2026-06-23 17:35:53.866053+00', '2026-06-23 17:35:53.866053+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (273, 190, 5, 'Sales Assistant - Part Time', false, 'Explore the World of Jeya Book Center. තනතුර : අර්ධකාලීන විකුණුම් සහායක (Part Time Sales Assistant). සුදුසුකම් : පිරිමි අපේක්ෂකයින් සඳහා පමණි. වයස් සීමාව: අවුරුදු 30 – 45 දක්වා. ගනුදෙනුකරුවන් සමඟ සුහදව කටයුතු කිරීමේ හැකියාව තිබිය යුතුය. විකුණුම් ක්ෂේත්‍රයේ පළපුරුද්ද ඇති අය සඳහා ප්‍රමුඛත්වය ලබා දේ. රැකියාවේ කාර්ය භාරය : පාරිභෝගිකයන්ට භාණ්ඩ තෝරා ගැනීම සඳහා සහාය වීම. භාණ්ඩ ප්‍රදර්ශනය හා අලෙවි කටයුතු සිදු කිරීම. පාරිභෝගික සේවාව උසස් මට්ටමක පවත්වා ගැනීම. ප්‍රතිලාභ : ආකර්ශනීය වැටුපක්. හොඳ සේවා පරිසරයක්. අනෙකුත් වරප්‍රසාද රැසක්.', 'Colombo 14, Colombo, Sri Lanka', '2026-06-23 17:39:27.870443+00', '2026-06-23 17:39:27.870443+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (274, 169, 4, 'Steward', false, 'We are looking for energetic and motivated individuals to join our restaurant team for the following positions: Salary: Rs. 50,000 + Service Charge 100%. Benefits: Accommodation provided, Staff meals provided, Uniforms provided, 6 days leave per month. If you are passionate about working in the hospitality industry and ready to grow with us, please send your CV or contact us today. Contact - MR Dasun 0777403052', 'Dehiwala, Colombo', '2026-06-23 17:39:27.886619+00', '2026-06-23 17:39:27.886619+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (275, 158, 4, 'Spray Painter', false, 'SPRAY PAINTER / ස්ප්‍රේ පේන්ටර් Join our growing team specializing in signage fabrication, branding, and installation projects across Sri Lanka. Key Responsibilities: Prepare surfaces for painting by cleaning, sanding, masking, and priming various materials including metal, aluminum, acrylic, wood, and composite panels. Apply paint, primers, clear coats, and protective finishes using spray-painting equipment. Ensure high-quality finishes that meet project specifications and company standards. Mix paints and coatings to achieve the required colors, textures, and finishes. Inspect completed work and perform touch-ups when necessary. Maintain spray guns, compressors, paint booths, and other painting equipment. Follow safety procedures when handling paints, solvents, thinners, and other coating materials. Coordinate with fabrication and production teams to meet project deadlines. Requirements: NVQ, Technical College qualification, or equivalent experience in Spray Painting, Automotive Painting, Industrial Painting, or a related field. Minimum 2 years of experience as a Spray Painter. Knowledge of surface preparation, paint mixing, coating systems, and finishing techniques. Experience working with metal, aluminum, acrylic, and other materials used in signage production. Ability to achieve smooth, consistent, and high-quality finishes. Knowledge of painting safety procedures and proper use of personal protective equipment (PPE). Ability to work independently and as part of a team. Strong attention to detail and commitment to quality workmanship. Benefits: Competitive salary package. Overtime and performance-based incentives. EPF & ETF benefits. Career growth opportunities. Training and skill development. Friendly and professional work environment.', 'Colombo 7, Colombo, Sri Lanka', '2026-06-23 17:39:27.971477+00', '2026-06-23 17:39:27.971477+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (276, 194, 4, 'Service Coordinator - Female', false, 'We are looking for Female Candidates for the position of: Service Coordinator. Salary: Rs. 50,000-60,000. Experience: No experience needed. Training: Provided. Job Type: Full-time. Requirements: Good communication skills, Friendly and positive attitude, Basic computer knowledge, Ability to coordinate with customers and team members, Willingness to learn. Responsibilities: Handling customer inquiries, Coordinating sales and service jobs, Updating customer details and service records, Following up with customers, Supporting the sales and service teams. Freshers are welcome to apply!', 'Colombo 3, Sri Lanka', '2026-06-23 17:39:28.010343+00', '2026-06-23 17:39:28.010343+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (277, 36, 4, 'Sales Assistant (Female)', false, 'We are looking for a friendly, energetic, and motivated female Sales Girl to join our textile shop in Maharagama. The ideal candidate should have good communication skills and a positive attitude towards customer service. Requirements: Minimum G.C.E. O/L qualification, Good communication skills, Friendly and customer-oriented personality, Willingness to work in a retail environment. Working Hours: 9.00 AM – 7.30 PM.', 'Maharagama, Colombo', '2026-06-23 17:39:28.025608+00', '2026-06-23 17:39:28.025608+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (281, 196, 4, 'Senior Backend Engineer', false, 'Build and maintain Go microservices for the job market platform.', 'Colombo', '2026-07-30 08:31:45.173233+00', '2026-07-30 08:31:45.173233+00', 2);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (282, 197, 4, 'Frontend Developer', true, 'Develop responsive React interfaces for the analytics dashboard.', 'Kandy', '2026-07-30 08:31:45.198685+00', '2026-07-30 08:31:45.198685+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (286, 201, 4, 'ඇසූරුම් සේවක සේවිකාවන්', false, 'ඇසුරුම් අංශ සඳහා නවකයින් බඳවා ගැනීම. බටර්, බීම, බිස්කට්, කේක්, නූල්ඩස්, ජෑම් යන ප්රසිද්ධ කර්මාන්තශාලා සඳහා. සති, මාසික වැටුප් සමග දීමනා. අතිකාල දීමනා, පැමිණීමේ දීමනා, ඩබල් බෝනස්. ආහාර, නවතැන් පහසුකම් සැපයේ. නිල ඇදුම් සැපයේ. කණ්ඩායම්, යහලුවන්/couple වශයෙන් එකම තැන රැකියා අවස්ථා.', 'Colombo 3, Sri Lanka', '2026-08-05 03:56:20.84863+00', '2026-08-05 03:56:20.84863+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (287, 202, 4, 'බැංකු හා මූල්‍ය ආයතන සහකාර', false, 'ප්‍රමුඛ බැංකු සහ මූල්‍ය ආයතන සඳහා රැකියා අවස්ථා. අවශ්‍ය සුදුසුකම්: සාමාන්‍ය පෙළ (O/L) විභාගය සමත් වීම, අවම වයස අවුරුදු 18ක් වීම, පිරිමි/ගැහැණු සියලුදෙනා සඳහා සුදුසුය, උසස් වෘත්තීය සුදුසුකම් තිබේ නම් අමතර වාසියක්. තනතුරු: බැංකු ලිපිකරු, ඩේටා එන්ට්‍රි ඔපරේටර්, උපදේශක, නියෝජිත, විධායක, ව්‍යාපාර සංවර්ධන නිලධාරී, පාරිභෝගික සේවා නිලධාරී, ඇමතුම් මධ්‍යස්ථානයේ නියෝජිත, අලෙවිකරණ විධායක/කළමනාකරු, රක්ෂණ විග්‍රහ නිලධාරී. සේවක වාසි: EPF/ETF දායකත්වය, වැටුප් සහිත පුහුණුව, ප්‍රවාහන සහ ආහාර පහසුකම්, වෛද්‍ය සේවා සහ රක්ෂණ ආවරණය, අතිකාල දීමනා, විනෝද චාරිකා සහ කණ්ඩායම් ක්‍රියාකාරකම්, අඩු පොලී අනුපාතයකින් බැංකු/නිවාස/වාහන ණය, ස්ථිර රැකියා සහ උසස්වීම් අවස්ථා.', 'Anuradhapura City, Anuradhapura, Sri Lanka', '2026-08-05 03:56:20.850784+00', '2026-08-05 03:56:20.850784+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (288, 203, 4, 'ඇසුරුම් සේවක / සේවිකා ( ස්ථීර රැකියා ) - මහියංගනය', false, 'ඇසුරුම් සේවක / සේවිකා ( ස්ථීර රැකියා ) - රත්මලාන, මොරටුව. රත්මලාන, මොරටුව පිහිටි ප්‍රධාන පෙළේ නිෂ්පාදන සමාගම් සදහා ඇති පුරප්පාඩු සදහා නවක සේවක මහත්ම මහත්මීන් බදවා ගනු ලැබේ. වයස අවු 18 - 40. උප්පැන්න සහතිකය, ග්‍රාමසේවක සහතිකය (මාස 6ට අඩු), චරිත සහතිකය, O/L හෝ A/L result sheet එක හෝ පාසල් අස්විමේ සහතිකය, ID Card එක ( copy 2ක් සමග), මුද්දර ප්‍රමාණයේ photos 2ක්, ලංකා බැංකුවේ තමාගේ බැංකු ගිණුමේ copy එකක්, කාඩ්බෝඩ් ෆයිල් කවරයක්, නිල් පෑනක්. අතිකාල සේවා මුර වල යෙදීමේදී ආහාර නොමිලේ සැපයේ. වැටුප අතිකාල දීමනා සමග 75,000.00 සිට ඉහලට. නවාතැන් පහසුකම්, සොඛ්‍ය පහසුකම්, ආරක්ෂාව, ප්‍රවාහන පහසුකම් සැපයේ.', 'Mahiyanganaya, Badulla, Sri Lanka', '2026-08-05 03:56:20.8521+00', '2026-08-05 03:56:20.8521+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (289, 204, 4, 'Airlines Catering Food Packing Officer', false, 'Airport Food Packing Officer role at Katunayake Bandaranaike International Airport. Responsibilities include catering/belt, housekeeping/laundry sections. Qualifications: age 18-45 for males, 18-40 for females (cleaning section up to 50), free training provided. Benefits: attractive salary Rs 68,000-75,000 per month, 12-hour service (day & night), free food during service, accommodation at concessionary rates, ETF/EPF and all institutional allowances, opportunity to become permanent within 3-6 months based on performance, couples and groups can apply, all religions welcome.', 'Katunayake, Colombo, Sri Lanka', '2026-08-05 03:56:20.853344+00', '2026-08-05 03:56:20.853344+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (290, 202, 4, 'බැංකු හා මූල්‍ය ආයතන සහකාර', false, 'ප්‍රමුඛ බැංකු සහ මූල්‍ය ආයතන සඳහා රැකියා අවස්ථා. අවශ්‍ය සුදුසුකම්: සාමාන්‍ය පෙළ (O/L) විභාගය සමත් වීම, අවම වයස අවුරුදු 18ක් වීම, පිරිමි/ගැහැණු සියලුදෙනා සඳහා සුදුසුය, උසස් වෘත්තීය සුදුසුකම් තිබේ නම් අමතර වාසියක්. තනතුරු: බැංකු ලිපිකරු, ඩේටා එන්ට්‍රි ඔපරේටර්, උපදේශක/Advisor, නියෝජිත/Agent, විධායක/Executive, ව්‍යාපාර සංවර්ධන නිලධාරී, පාරිභෝගික සේවා නිලධාරී, ඇමතුම් මධ්‍යස්ථානයේ නියෝජිත, අලෙවිකරණ විධායක/කළමනාකරු, රක්ෂණ විග්‍රහ නිලධාරී. සේවක වාසි: EPF/ETF දායකත්වය, වැටුප් සහිත පුහුණුව, ප්‍රවාහන සහ ආහාර පහසුකම්, වෛද්‍ය සේවා සහ රක්ෂණ ආවරණය, අතිකාල දීමනා, විනෝද චාරිකා සහ කණ්ඩායම් ක්‍රියාකාරකම්, අඩු පොලී අනුපාතයකින් බැංකු/නිවාස/වාහන ණය, ස්ථිර රැකියා සහ උසස්වීම් අවස්ථා.', 'Hambantota City, Sri Lanka', '2026-08-05 03:56:20.854754+00', '2026-08-05 03:56:20.854754+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (299, 208, 4, 'බර වාහන රියදුරු මහතුන්', false, 'L.V. / H.V රියදුරු ඇබෑර්තු. කොළඹ සහ අවට ප්‍රදේශවල සේවය සඳහා L.V./ H.V රියදුරන් අවශ්‍යයි. වැටුප: රු. 150,000. වයස: 18 – 55. සුදුසුකම්: වලංගු L.V./ H.V රියදුරු බලපත්‍රය. ආහාර දීමනා, නවාතැන් පහසුකම් (අදාළ ස්ථාන සඳහා), පැමිණීමේ දීමනා, අතිකාල දීමනා, මාස 3න් පසු වැටුප් වැඩිවීමේ අවස්ථාව, EPF / ETF සහ අනෙකුත් දීමනා.', 'Athurugiriya, Colombo', '2026-08-05 03:58:24.686643+00', '2026-08-05 03:58:24.686643+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (291, 203, 4, 'ඇසුරුම් සේවක / සේවිකා ( ස්ථීර රැකියා ) - මාතර', false, 'ඇසුරුම් සේවක / සේවිකා ( ස්ථීර රැකියා ) - රත්මලාන, මොරටුව. රත්මලාන, මොරටුව පිහිටි ප්‍රධාන පේළියේ නිෂ්පාදන සමාගම් සදහා ඇති පුරප්පාඩු සදහා නවක සේවක මහත්ම මහත්මීන් බදවා ගනු ලැබේ. වයස අවු 18 - 40, උප්පැන්න සහතිකය, ග්‍රාමසේවක සහතිකය (මාස 6ට අඩු), චරිත සහතිකය, O/L හෝ A/L result sheet එක හෝ පාසල් අස්විමේ සහතිකය, ID Card එක ( copy 2ක් සමග), මුද්දර ප්‍රමාණයේ photos 2ක්, ලංකා බැංකුවේ තමාගේ බැංකු ගිණුමේ copy එකක්, කාඩ්බෝඩ් ෆයිල් කවරයක්, නිල් පෑනක්. අතිකාල සේවා මුර වල යෙදීමේදී ආහාර නොමිලේ සැපයේ. වැටුප අතිකාල දීමනා සමග 75,000.00 සිට ඉහලට. නවාතැන් පහසුකම්, සොඛ්‍ය පහසුකම්, ආරක්ෂාව, ප්‍රවාහන පහසුකම් සැපයේ.', 'Matara City, Matara, Sri Lanka', '2026-08-05 03:56:20.855605+00', '2026-08-05 03:56:20.855605+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (292, 201, 4, 'ඇසූරුම් අංශ සඳහා සේවක සේවිකාවන්', false, 'ඇසුරුම් අංශය සඳහා සේවක සේවිකාවන් අවශ්යයි. බටර්, බීම, බිස්කට්, කේක්, නූල්ඩස්, ජෑම් යන ප්රසිද්ධ කර්මාන්තශාලා සඳහා නවකයින් බඳවා ගැනේ. සති, මාසික වැටුප් සමග දීමනා රැසක්. අතිකාල දීමනා, පැමිණීමේ දීමනා, ඩබල් බෝනස් ඇතුළු විශේෂ දීමනා. ආහාර, නවතැන් පහසුකම් සහ නිල ඇදුම් සැපයේ. වැටුප රු. 55,000 - 95,000 අතර.', 'Kurunegala City, Sri Lanka', '2026-08-05 03:56:20.856185+00', '2026-08-05 03:56:20.856185+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (293, 202, 4, 'බැංකු හා මූල්‍ය ආයතන සහකාර', false, 'ප්‍රමුඛ බැංකු සහ මූල්‍ය ආයතන සඳහා රැකියා අවස්ථා. අවශ්‍ය සුදුසුකම්: සාමාන්‍ය පෙළ (O/L) විභාගය සමත් වීම, අවම වයස අවුරුදු 18ක් වීම, පිරිමි / ගැහැණු සියලුදෙනා සඳහා සුදුසුය, උසස් වෘත්තීය සුදුසුකම් තිබේ නම් අමතර වාසියක්. තනතුරු: බැංකු ලිපිකරු, ඩේටා එන්ට්‍රි ඔපරේටර්, උපදේශක, නියෝජිත, විධායක, ව්‍යාපාර සංවර්ධන නිලධාරී, පාරිභෝගික සේවා නිලධාරී, ඇමතුම් මධ්‍යස්ථානයේ නියෝජිත, අලෙවිකරණ විධායක/කළමනාකරු, රක්ෂණ විග්‍රහ නිලධාරී. සේවක වාසි: EPF/ETF දායකත්වය, වැටුප් සහිත පුහුණුව, ප්‍රවාහන සහ ආහාර පහසුකම්, වෛද්‍ය සේවා සහ රක්ෂණ ආවරණය, අතිකාල දීමනා, විනෝද චාරිකා සහ කණ්ඩායම් ක්‍රියාකාරකම්, අඩු පොලී අනුපාතයකින් බැංකු/නිවාස/වාහන ණය, ස්ථිර රැකියා සහ උසස්වීම් අවස්ථා.', 'Ambalangoda, Galle, Sri Lanka', '2026-08-05 03:56:20.857567+00', '2026-08-05 03:56:20.857567+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (294, 202, 4, 'බැංකු හා මූල්‍ය ආයතන සහකාර', false, 'ප්‍රමුඛ බැංකු සහ මූල්‍ය ආයතන සඳහා රැකියා අවස්ථා. අවශ්‍ය සුදුසුකම්: සාමාන්‍ය පෙළ (O/L) විභාගය සමත් වීම, අවම වයස අවුරුදු 18ක් වීම, පිරිමි/ගැහැණු සියලුදෙනා සඳහා සුදුසුය, උසස් වෘත්තීය සුදුසුකම් තිබේ නම් අමතර වාසියක්. තනතුරු: බැංකු ලිපිකරු, ඩේටා එන්ට්‍රි ඔපරේටර්, උපදේශක, නියෝජිත, විධායක, ව්‍යාපාර සංවර්ධන නිලධාරී, පාරිභෝගික සේවා නිලධාරී, ඇමතුම් මධ්‍යස්ථානයේ නියෝජිත, අලෙවිකරණ විධායක/කළමනාකරු, රක්ෂණ විග්‍රහ නිලධාරී. සේවක වාසි: EPF/ETF දායකත්වය, වැටුප් සහිත පුහුණුව, ප්‍රවාහන සහ ආහාර පහසුකම්, වෛද්‍ය සේවා සහ රක්ෂණ ආවරණය, අතිකාල දීමනා, විනෝද චාරිකා සහ කණ්ඩායම් ක්‍රියාකාරකම්, අඩු පොලී අනුපාතයකින් බැංකු/නිවාස/වාහන ණය, ස්ථිර රැකියා සහ උසස්වීම් අවස්ථා.', 'Kalutara City, Sri Lanka', '2026-08-05 03:58:24.667658+00', '2026-08-05 03:58:24.667658+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (295, 205, 4, 'Cashier/ sales assistant', false, 'Battaramulla/ Nawala pastry shop is hiring a cashier/sales assistant. Applicants must be between 18 and 40 years old. Accommodation is provided for male employees. Attractive salary and many other benefits are offered. Overtime allowances are paid. 6 days of leave per month are provided. Uniform and meals during working hours are provided. Attractive salaries for experienced workers. Immediate recruitment is conducted.', 'Battaramulla, Colombo, Sri Lanka', '2026-08-05 03:58:24.671304+00', '2026-08-05 03:58:24.671304+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (296, 206, 4, 'Bookshop Sales Assistant', false, 'Experienced Sinhala, Tamil girls needed for bookshop. Work: Sales, printout, photocopy, lamination. Good experience + special talent preferred.', 'Gampola, Kandy, Sri Lanka', '2026-08-05 03:58:24.68225+00', '2026-08-05 03:58:24.68225+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (297, 14, 4, 'Commi - Hot Kitchen', false, 'Urgently Hiring kitchen staffs for a Restaurant in Sigiriya. Please send us your CV for following numbers. +94 77 335 7478 +94 77 429 7478 Accommodation / Meals Free', 'Sigiriya, Matale, Sri Lanka', '2026-08-05 03:58:24.683422+00', '2026-08-05 03:58:24.683422+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (298, 207, 4, 'Call Center Executive', false, 'Responsibilities include handling office documents and documentation, and handling customer issues. Qualifications: GCE A/L completed, age 18-40, Sinhala language sufficient (Tamil and English separate call centers available). Benefits: Salary Rs 75,000 - 85,000 per month, vehicle allowance of Rs 20,000 after 3 months, loan of 150,000 after one year of service, smart phone and laptop provided and can be taken home. Work locations include Nawaala, Nugegoda, Maharagama, Kottawa, Homagama, Boralesgamuwa. Working hours 8am-5pm, six days per week. No remote work. Accommodation allowance provided but not accommodation itself.', 'Maharagama, Colombo', '2026-08-05 03:58:24.684652+00', '2026-08-05 03:58:24.684652+00', 5);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (300, 202, 4, 'බැංකු හා මූල්‍ය ආයතන සහකාර - වත්තල', false, 'ප්‍රමුඛ බැංකු සහ මූල්‍ය ආයතන සඳහා රැකියා අවස්ථා. අවශ්‍ය සුදුසුකම්: සාමාන්‍ය පෙළ (O/L) විභාගය සමත් වීම, අවම වයස අවුරුදු 18ක් වීම, පිරිමි/ගැහැණු සියලුදෙනා සඳහා සුදුසුය, උසස් වෘත්තීය සුදුසුකම් තිබේ නම් අමතර වාසියක්. තනතුරු: බැංකු ලිපිකරු, ඩේටා එන්ට්‍රි ඔපරේටර්, උපදේශක, නියෝජිත, විධායක, ව්‍යාපාර සංවර්ධන නිලධාරී, පාරිභෝගික සේවා නිලධාරී, ඇමතුම් මධ්‍යස්ථානයේ නියෝජිත, අලෙවිකරණ විධායක/කළමනාකරු, රක්ෂණ විග්‍රහ නිලධාරී. සේවක වාසි: EPF/ETF දායකත්වය, වැටුප් සහිත පුහුණුව, ප්‍රවාහන සහ ආහාර පහසුකම්, වෛද්‍ය සේවා සහ රක්ෂණ ආවරණය, අතිකාල දීමනා, විනෝද චාරිකා සහ කණ්ඩායම් ක්‍රියාකාරකම්, අඩු පොලී අනුපාතයකින් බැංකු/නිවාස/වාහන ණය, ස්ථිර රැකියා සහ උසස්වීම් අවස්ථා.', 'Wattala, Gampaha, Sri Lanka', '2026-08-05 03:58:24.688975+00', '2026-08-05 03:58:24.688975+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (301, 209, 4, 'Crew Member', false, 'Join the world''s number one pizza restaurant chain as a proud member and advance quickly as a respected professional in the restaurant industry. Requirements: enthusiastic and pleasant personality, age between 18-40, sat for GCE O/L examination, must have a ''Smart'' mobile phone, for Delivery Rider a valid driving license and motorcycle. Benefits: highest salaries and allowances in the restaurant industry, international level training, promotions based on skills, free food and beverages, uniforms and other allowances, special additional allowances for Delivery Riders, accommodation facilities for selected restaurants, contributions to ETF/EPF funds, staff discounts on food and beverages.', 'Colombo 7, Sri Lanka', '2026-08-05 03:58:24.690507+00', '2026-08-05 03:58:24.690507+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (302, 210, 4, 'Data Entry Operator', false, 'Join the Team at Emerald BPO Company! We''re Hiring: Data Entry Operators. Emerald BPO Company, a leading and fast-growing tech company in Sri Lanka, is looking for enthusiastic individuals to join our dynamic team. If you are tech-savvy and eager to build your career in a friendly and professional environment, this is your chance! Position: Data Entry Operator. Work Type: Full-Time (Night Shifts). Working Hours: 12 Hours. Location: Colombo 10 & Havelock Road Colombo - 05. Salary: Between 65,000 - 75,000 (Performance-based increments). Gender: Male or Female. Requirements: GCE O/L and A/L qualifications, Basic IT literacy, IT Diploma (completed or ongoing) is a plus, Attention to detail and strong typing skills. What We Offer: Supportive and friendly work environment, Career growth opportunities, Performance-based incentives, Valuable experience in a tech-driven company.', 'Colombo 10, Sri Lanka', '2026-08-05 03:58:24.691488+00', '2026-08-05 03:58:24.691488+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (303, 211, 4, 'Call Center Executive', false, 'Call Center Executive job with a salary of Rs 65,000 per month. Interviews held daily until 30 vacancies are filled. Candidates can choose from branches in Nawaala, Nugegoda, Maharagama, Kottawa, Homagama, or Boralesgamuwa. No prior experience required. Ordinary Level education required.', 'Maharagama, Colombo', '2026-08-05 03:58:24.692538+00', '2026-08-05 03:58:24.692538+00', 30);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (304, 212, 5, 'Data Entry Typing Operator- (Part Time) Works at Home (Online)', true, 'Sri Lankan Projects, Data Entry Works, Online Data Submission, Copy Typing, Simple Typing. Start Your Work Within 30 Minutes. Income: Daily - Rs. 500 – 2,000, Monthly - Rs. 65,000+ (Depends on your work performance). Facilities: Full Sinhala / English Guidelines (Call or Email), Daily Job Options (Typing, Data Entry & Data Submission), Work From Home – Flexible Working Hours, Payments via Bank Deposit / eZ Cash, 24×7 Support. Qualifications: Basic IT and Email knowledge, Male/Female anyone, Can work from anywhere in the island. Suitable for: Full-Time / Part-Time Employees, Job Seekers, Housewives, School Leavers, University Students, Anyone expecting extra income. Requirements: Computer, Laptop or Smartphone / iPhone, Internet Connection, At least 1 hour per day.', 'Nugegoda, Colombo', '2026-08-05 04:00:22.706509+00', '2026-08-05 04:00:22.706509+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (305, 213, 4, 'Accountant', false, 'Xellion (Pvt) Ltd is seeking a detail-oriented, analytical, and experienced Accountant to oversee the company''s financial operations. The successful candidate will be responsible for maintaining accurate financial records, ensuring compliance with Sri Lankan statutory regulations, preparing financial reports, and supporting management with financial analysis and decision-making. Key Responsibilities: Maintain accurate accounting records and financial transactions. Manage Accounts Payable (AP) and Accounts Receivable (AR). Perform bank reconciliations and monitor cash flow. Process payroll and administer salary payments. Ensure compliance with VAT, APIT, EPF, ETF, and other statutory tax requirements. Prepare monthly financial statements, management accounts, and other financial reports. Maintain the General Ledger and perform month-end and year-end closing activities. Assist in budgeting, forecasting, and financial analysis. Coordinate internal and external audits. Ensure compliance with Sri Lankan accounting standards and company financial policies. Requirements: Bachelor''s Degree in Accounting, Finance, or a related field. Professional qualification such as CA Sri Lanka, ACCA, or CIMA will be a distinct advantage. Hindi speaking is mandatory. Minimum of 2 years of experience in accounting or finance. Strong knowledge of Sri Lankan tax regulations and statutory compliance. Proficiency in Microsoft Excel and accounting software such as QuickBooks, Xero, Tally, or Sage. Excellent analytical, communication, and problem-solving skills. High level of accuracy, integrity, and attention to detail. Benefits: Attractive salary package (Negotiable). Performance-based incentives. Career growth and advancement opportunities. Professional and collaborative working environment. Learning and development opportunities.', 'Colombo 10, Sri Lanka', '2026-08-05 04:00:22.713083+00', '2026-08-05 04:00:22.713083+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (306, 214, 4, 'කර්මාන්තශාලා ඇසුරුම් සේවක සේවිකාවන්', false, 'Factory packing worker positions available. Daily, weekly, monthly salary options. Salary range Rs 65,000 - 95,000. Weekly salary from 18,000. Overtime allowances (180/200/220). Attendance allowance / double bonus. Can come in groups or with friends. Food and accommodation available. Uniform provided. Daily salary available (1800/2500/3000). Free food for overtime shifts. Requires GCE O/L completion. Contact 0740203351 (Navanjana). Special recruitment from around Colombo. Government registered institution.', 'Minuwangoda, Gampaha, Sri Lanka', '2026-08-05 04:00:22.718977+00', '2026-08-05 04:00:22.718977+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (630, 377, 4, 'Store Assistant', false, 'Store Assistant for a vehicle spare parts importing company in Malabe. Requirements: age 19-45, male/female, residing near Malabe. Benefits: fixed monthly salary of Rs 55,000, overtime allowance, medical insurance coverage, additional benefits, EPF/ETF, permanent and secure job.', 'Malabe, Colombo, Sri Lanka', '2026-08-06 09:49:40.242359+00', '2026-08-06 09:49:40.242359+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (307, 215, 4, 'Hotel Receptionist (Male / Female)', false, 'Join our friendly hospitality team and build your career in the hotel industry! Requirements: Age below 35 years, Minimum 2 years of experience in Hotel Reception or Front Office, Diploma or certification in Hospitality Management / Front Office (preferred), Good command of English (additional languages are an added advantage), Friendly, well-groomed, and customer-focused personality, Ability to work flexible shifts. We Offer: Attractive salary package, Free food and accommodation, Friendly working environment, Career growth opportunities, Training and professional development.', 'Nuwara Eliya, Sri Lanka', '2026-08-05 04:00:22.723047+00', '2026-08-05 04:00:22.723047+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (308, 205, 4, 'Kitchan helper', false, 'Battaramulla/ Nawala pastry shop is hiring a kitchen helper. Age between 18 and 40 (male). Accommodation provided for male staff. Attractive salary and many other benefits. Overtime allowance paid. 6 days leave per month. Uniform and meals during working hours provided. Experienced workers (rolls, bun curry) receive attractive salaries. Immediate recruitment.', 'Battaramulla, Colombo, Sri Lanka', '2026-08-05 04:00:22.724712+00', '2026-08-05 04:00:22.724712+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (309, 216, 7, 'Food Cart Worker', false, 'We are looking for a young, enthusiastic and responsible male team member to join our food cart in Pannipitiya. Applicants living near Pannipitiya or Kottawa will be given preference. Working hours: 5:00 PM–1:00 AM. Starting salary: LKR 50,000 per month. Benefits: Additional performance bonuses, meals during working hours, washroom facilities and Uber or PickMe transport after the shift. The ideal candidate should be punctual, hardworking, friendly and willing to learn. Please send your CV via WhatsApp to apply.', 'Nugegoda, Colombo, Sri Lanka', '2026-08-05 04:00:22.727274+00', '2026-08-05 04:00:22.727274+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (310, 217, 4, 'ගෘහ සේවිකාවන්', false, 'ගල්කිස්ස පිහිටි නිවසක කෑමපිසීම/පිරිසිදු කිරීම සඳහා වයස අවු 18-55 ත් අතර ගෘහ සේවිකාවක් අවශ්‍යයි. වැටුප රැ. 45,000/- ත් 50,000/- ත් අතර. දරුවන් දෙදෙනෙකු බලා ගැනීමට වයස අවු 18-55 ත් අතර ගෘහ සේවිකාවක් අවශ්‍යයි. වැටුප රැ. 45,000/- ත් 50,000/- ත් අතර වෙනම නිදන කාමරයක් ඇත. ආහාර පාන හා ඔෟෂධ අවශ්‍යතා සපයනු ලැබේ.', 'Ratmalana, Colombo', '2026-08-05 04:00:22.728248+00', '2026-08-05 04:00:22.728248+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (311, 218, 4, 'Light Vehicle Driver', false, 'Vacancy Light Vehicle Driver. Courier and Package Delivery. Ideal a young school leaver. Working days 6 days. Salary Starting Rs.40,000/- Need Grama Sevaka Certificate. Applicants from Nugegoda, Nawala, Rajagiriya are preferred. Call 0715990066', 'Rajagiriya, Colombo, Sri Lanka', '2026-08-05 04:00:22.729409+00', '2026-08-05 04:00:22.729409+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (312, 215, 4, 'Housekeeping Supervisor', false, 'WE''RE HIRING! Join Our team. Open Position: KANDY Housekeeping Supervisor (Male/Female), Public Area Supervisor, Linen Room Supervisor, Laundry Supervisor. We are looking for talented individuals to join our Team. Requirements: Age below 35 years, Minimum 1 year of experience in Housekeeping, Room Attendant, or a similar role, Diploma or certificate in Hospitality or Housekeeping is preferred, Good communication skills in English will be an added advantage, Applicants residing in Kandy or surrounding areas will receive preference, Positive attitude, attention to detail, and ability to work as part of a team. Please send your CV or call us 0762918423.', 'Peradeniya, Kandy, Sri Lanka', '2026-08-05 04:00:22.730641+00', '2026-08-05 04:00:22.730641+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (313, 212, 5, 'Data Entry Typing- (Part Time) Works at Home (Online)', true, 'Sri Lankan Projects, Data Entry Works, Online Data Submission, Copy Typing, Simple Typing. Start Your Work Within 30 Minutes. Income: Daily - Rs. 500 – 2,000, Monthly - Rs. 65,000+ (Depends on your work performance). Benefits: Full Sinhala / English Guidelines (Call or Email), Daily Job Options (Typing, Data Entry & Data Submission), Work From Home – Flexible Working Hours, Payments via Bank Deposit / eZ Cash, 24×7 Support. Qualifications: Basic IT and Email knowledge, open to any male/female, can work from anywhere in the island. Suitable for Full-Time/Part-Time Employees, Job Seekers, Housewives, School Leavers, University Students, anyone looking for extra income. Requirements: Computer, Laptop or Smartphone/iPhone, Internet Connection, at least 1 hour per day.', 'Kalmunai, Ampara, Sri Lanka', '2026-08-05 04:00:22.731973+00', '2026-08-05 04:00:22.731973+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (314, 214, 4, 'ලිපිකාරිනියන්', false, 'Urgently hiring female clerks from around Kurunegala for a private institution. Must be able to speak Tamil/Sinhala. Age 18-35. GCE O/L qualified. GCE A/L candidates may apply. English and computer knowledge is an additional qualification. Salary between Rs 45,000-55,000. Various benefits available. Opportunities for promotion based on qualifications. Work shift: 8:30 AM - 4:00 PM. Limited vacancies, apply today. Contact: 0762226522.', 'Kurunegala City, Sri Lanka', '2026-08-05 04:04:35.059212+00', '2026-08-05 04:04:35.059212+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (315, 219, 4, 'පුහුණු නුපුහුණු ගුරු', false, 'Teaching opportunities for preschools, international schools, and other private schools. Open to both trained and untrained teachers, as well as experienced individuals. Facilities include accommodation for selected schools, high salary packages based on skills and experience, no age limit, and open to both diploma and non-diploma holders. School selection and salary are based on qualifications, skills, and institutional requirements.', 'Piliyandala, Colombo, Sri Lanka', '2026-08-05 04:04:35.062183+00', '2026-08-05 04:04:35.062183+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (316, 156, 4, 'Office Assistant (Female)', false, 'NWOW International Trading (Pvt) Ltd, a leading electric bike brand in Sri Lanka, is looking for a dynamic, energetic, and dedicated individual to join our team at the Battaramulla Branch. Responsibilities include handling daily office operations and customer inquiries. Qualifications: Age 18-30 years, basic computer literacy, good interpersonal and communication skills. Benefits: Attractive salary package + allowances, friendly and supportive working environment.', 'Battaramulla, Colombo', '2026-08-05 04:04:35.06592+00', '2026-08-05 04:04:35.06592+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (317, 220, 4, 'Personal Driver', false, 'Driver needed for personal use. Age below 45, experience 2 years. Accommodation available. To drive van and jeep for home use. Valid license and ID must. Call to this number or visit to this address No 28 quarry road Colombo 12 0771387721.', 'Colombo 13, Sri Lanka', '2026-08-05 04:04:35.067185+00', '2026-08-05 04:04:35.067185+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (318, 221, 4, 'Packing Officer', false, 'Packing Officer position at a well-known factory producing chocolate, biscuits, and butter. Hiring from age 17. Working hours 8/12 with OT allowances. ETF/PTF provided. Free food, drinks, and accommodation. Locations: Kuliyapitiya/Polgahawela, Kurunegala/Dambulla. Daily wages between 1800/2000/2500/3000. Weekly/monthly salaries (70000/98000). Overtime allowances (150/200/220). Attendance allowance/double bonus. Opportunities for groups/friends and married couples to work at the same place. Free food/accommodation. Free uniform. Job provided on the day of arrival. Free meals during overtime shifts. Government registered institution. Contact 0740203351.', 'Kuliyapitiya, Kurunegala, Sri Lanka', '2026-08-05 04:04:35.068103+00', '2026-08-05 04:04:35.068103+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (319, 222, 4, 'Helper', false, 'Assist in Mechanical works, Machinery Repair & Maintenance, Fabrication and Engineering works, participate in Workshop and Site works as required, assist in Marine/Ship Repair works. Qualifications: interest in mechanical work, ability to work responsibly in a team, willingness to work in site/workshop environment, prior experience is an additional qualification, those without experience may also apply. Benefits: attractive salary, overtime (OT) allowance, free meals, free accommodation, free transport, free work clothes, free safety shoes, other safety equipment provided, opportunity to gain practical experience in Mechanical & Marine Engineering field, opportunity for advancement based on skill and dedication.', 'Kaduwela, Colombo, Sri Lanka', '2026-08-05 04:04:35.070375+00', '2026-08-05 04:04:35.070375+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (320, 202, 4, 'පුහුණු නුපුහුණු ගුරු', false, 'Teaching opportunities for preschools, international schools, and other private schools. Open to both trained and untrained teachers, as well as experienced individuals. Facilities include accommodation for selected schools, high salary packages based on ability and experience, no age limit, and open opportunities for both diploma and non-diploma holders. School selection and salary are tailored to qualifications, skills, and institutional needs. For more details, contact 074 3077 562, 076 4363 885, or 076 4363 886. It is best to visit the nearest branch for interviews and further information.', 'Kadawatha, Gampaha, Sri Lanka', '2026-08-05 04:04:35.071729+00', '2026-08-05 04:04:35.071729+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (321, 202, 4, 'පුහුණු නුපුහුණු ගුරු - ගාල්ල', false, 'Teaching opportunities for preschools, international schools, and other private schools. Open to both trained and untrained teachers, as well as experienced individuals. Facilities include accommodation for selected schools, high salary packages based on skills and experience, no age limit, and open to both diploma and non-diploma holders. School selection and salary are based on qualifications, skills, and institutional requirements. For more details, contact 076 4363 885, 074 3077 562, or 076 4363 886. It is recommended to visit the nearest branch for interviews and further information.', 'Galle City, Galle, Sri Lanka', '2026-08-05 04:04:35.072349+00', '2026-08-05 04:04:35.072349+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (322, 215, 4, 'Receptionist (Female)', false, 'WE''RE HIRING! Join Out team Open Position : KANDY Receptionist (Female) Reservations Executive (Female) Telephone Operator (Female) We are looking for talented individuals to join our Team. - Minimum 1 year experience in similar capacity - Age below 35 years - Good communication and interpersonal skills - Diploma or HND in Travel & Tourism or Hospitality Industry performance in to the next leve Please send me your cv through whatsapp on +94 743605564', 'Kandy City, Kandy, Sri Lanka', '2026-08-05 04:04:35.073622+00', '2026-08-05 04:04:35.073622+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (323, 223, 4, 'Villa All Rounder', false, 'ALL-ROUNDER WANTED — Rooms & Restaurant | Private Villa, Peradeniya. Small private villa near the Royal Botanical Gardens is looking for a friendly, hardworking All-Rounder. Mornings: preparing guest rooms to a high standard. Days and evenings: serving guests in our garden café — breakfast, lunch, dinner, drinks by the pool, garden barbecues. Only done rooms before? Or only service? That’s fine — we will train you in the other. You need: 1–2 years in a hotel, villa, guesthouse or restaurant; Good spoken English — international guests; Friendly, honest and well presented; Eye for detail and a high standard of cleanliness; Fit, active, flexible with shifts; Willing to learn. Accommodation available.', 'Peradeniya, Kandy, Sri Lanka', '2026-08-05 04:04:35.075295+00', '2026-08-05 04:04:35.075295+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (324, 224, 4, 'සැහැල්ලු වාහන රියදුරු මහතුන්', false, 'අප පුද්ගලික සමාගමට සැහැල්ලු/බර වාහන රියදුරු මහතුන් අවශ්‍යයි. වයස 18-50 අතර. වැටුප 80000-85000 දක්වා. ආහාර /නවාතැන් පහසුකම්, පැමිණීමේ දීමනා, අතිකාල දීමනා. දක්ෂතාවයට වැටුප් වැඩි වේ.', 'Kaduwela, Colombo', '2026-08-05 04:13:43.585219+00', '2026-08-05 04:13:43.585219+00', 1);
