INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (329, 229, 4, 'Creative Graphic Designer', false, 'We are hiring a Creative Graphic Designer. Requirements: Age 20 to 35 years. Degree or Diploma in Graphic Designing. Excellent working knowledge of Adobe Creative Suite (Illustrator, Photoshop, InDesign). Minimum 1 to 2 years of professional design experience, preferably in a digital agency or in-house design team. Working experience in the apparel or related industry will be an added advantage. A creative thinker who is aware of current design and cultural trends and is able to think conceptually. Cross-media experience and the ability to deliver content for digital platforms.', 'Ratmalana, Colombo, Sri Lanka', '2026-08-05 04:13:43.592748+00', '2026-08-05 04:13:43.592748+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (330, 230, 4, 'Sales Assistant Female', false, 'We''re Hiring – Sales Assistant (Female) at Glamon Gold Plated Jewellery, located in Dehiwala. Looking for enthusiastic female candidates with a passion for fashion and customer service. Requirements: G.C.E. Ordinary Level (O/L) passed, age between 18–30 years, passion for customer service, good communication skills, interest in fashion and jewellery. Working hours: 10:00 AM – 7:00 PM. Days off: 04 Sundays per month. Benefits: attractive salary, friendly working environment, free company uniform, career growth opportunities. How to apply: bring your CV and attend a walk-in interview at our showroom in Dehiwala. For more information, call: 0777 687 876.', 'Dehiwala, Colombo, Sri Lanka', '2026-08-05 04:13:43.594828+00', '2026-08-05 04:13:43.594828+00', 1);
