INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (576, 343, 4, 'Mechanic (Heavy Machinery), Welder, High-Bed Trailer Driver, Machine Helper (M/F), Heavy Vehicle Driver', false, 'ISO 9001:2015 / EMS 14001:2015 / OHSAS 18001:2007 certified, CIDA(ICTAD)-registered GP-B1 grade piling/construction contractor, hiring across 5 categories. Attractive salary based on age and experience.', 'Sri Lanka', '2026-08-05 13:08:46.711775+00', '2026-08-05 13:08:46.711775+00', 1);
