INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (578, 345, 4, 'General Production Worker (M/F)', false, 'Male & female production line workers, age 18-45. ~Rs. 25,000/month probation salary, +Rs. 5,000 allowance after 3 months, rising toward Rs. 35,000+ with allowances.', 'Sri Lanka', '2026-08-05 13:08:46.716531+00', '2026-08-05 13:08:46.716531+00', 1);
