INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (581, 348, 4, 'Officer (title illegible) - Grade PS1', false, '1 vacancy, salary Rs. 200,000-220,000/month, age limit 65.', 'Colombo (Ministry office)', '2026-08-05 13:08:46.723247+00', '2026-08-05 13:08:46.723247+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (582, 348, 4, 'Deputy Director (Engineering/Operations) - Grade PS2', false, 'Requires professional engineering qualification + 13 years'' post-qualification experience. Salary Rs. 185,000-205,000/month, age limit 65.', 'Colombo', '2026-08-05 13:08:46.724374+00', '2026-08-05 13:08:46.724374+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (583, 348, 4, 'Program Coordinator - Grade PS3', false, 'Requires relevant qualifications + 10 years'' experience in program coordination. Salary Rs. 180,000-195,000/month, age limit 65.', 'Colombo', '2026-08-05 13:08:56.89359+00', '2026-08-05 13:08:56.89359+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (584, 349, 4, 'Administrative Operations Associate', true, 'Support a Melbourne-based maintenance company''s day-to-day administrative operations. This is a proactive, detail-oriented role suited to someone comfortable managing multiple moving parts — from client quotes to internal job tracking — in a fast-paced service business. Key Responsibilities: Enter and update job data in the company''s online scheduling system; Prepare client quotations; Manage invoicing tasks; Respond promptly and professionally to client and team emails; Provide broader administrative support across maintenance operations. Requirements: Strong command of English (written and spoken); Proficient with Google Workspace tools; Prior experience in construction/maintenance industry is a plus; Consistent weekday schedule aligned with the Victorian calendar. Great opportunity for someone detail-oriented looking to grow within a dynamic, service-driven company.', 'Colombo, Sri Lanka', '2026-08-06 09:23:22.264646+00', '2026-08-06 09:23:22.264646+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (585, 241, 4, 'Project Coordinator', false, 'Anscom is an automation design studio established in 2011 by technology professionals. We integrate world-class ELV, audio/visual, security and automation solutions for properties, around the world. Our scope of work covers design, supply, installation, configuration, and after-sales service & support. We partner with the highest-rated brands and suppliers, to guarantee the best-in-class technology solutions. This role provides an exciting opportunity for a dynamic individual looking to grow within the AV/ELV industry and gain hands-on experience in operations management. Duties & Responsibilities: Assist in planning, organizing, and executing audio, visual, and ELV system installation projects. Oversee project timelines, ensuring tasks are completed on schedule and within scope. Coordinate resources, including personnel, equipment, and materials, for project delivery. Provide support for managing and leading the engineers, technicians, and subcontractors. Ensure team members have the necessary training and resources to execute their roles effectively. Supervise team performance and ensure adherence to company policies, safety standards, and quality control measures. Maintain strong communication with clients to ensure satisfaction and handle any project-related inquiries or issues. Prepare all initial and post-project documentation to enhance customer relations. Provide technical support and advice to clients on ELV, AV, and other related systems. Monitor inventory of materials, equipment, and supplies required for AV/ELV systems. Coordinate with the procurement team regarding the timely delivery of products and resources to meet project deadlines. Assist in developing and implementing operational policies, processes, and procedures to improve efficiency and performance. Regularly review project workflows to identify opportunities for process improvement and cost reduction. Prepare and present regular reports on project progress, financials, and any issues to senior management. Maintain project documentation, including contracts, change orders, permits, and compliance records. Ensure all work is completed in accordance with industry standards, safety regulations, and client specifications. Ensure all team members follow safety protocols and guidelines during installations and operations. Conduct site assessments to identify and mitigate potential risks. Ensure compliance with industry standards and local regulations relating to AV and ELV systems. Assist in troubleshooting any technical issues during installation or post-installation stages. Liaise with technical teams to resolve issues efficiently and ensure optimal performance of systems. Essential Skills: A degree in Electrical Engineering, Electronics, Information Technology, or a related field is an added advantage. Relevant certifications in AV/ELV systems or project management are a plus. 3 years of experience in operations management or project coordination within the AV/ELV industry. Proven experience in managing teams, coordinating projects, and working with clients in the AV/ELV field. Good knowledge of Auto CAD, audio-visual, and extra-low voltage (ELV) systems. Excellent communication, organizational, and leadership skills. Proficient in project management tools and MS Office Suite. Ability to multitask and work under pressure to meet tight deadlines. Knowledge of industry safety standards and regulations. Proactive, detail-oriented, and results-driven. Strong problem-solving skills and ability to think on your feet. Ability to work collaboratively and build strong relationships with internal and external stakeholders.', 'Colombo, Sri Lanka', '2026-08-06 09:23:22.282469+00', '2026-08-06 09:23:22.282469+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (586, 350, 4, 'Customer Care / Front Office Executive', false, 'We are seeking a highly motivated and customer-centric individual to join our clients team as Customer Care/Front Office Executive. The ideal candidate will be the first point of contact for their customers, ensuring a positive and professional experience. Responsibilities include: Greet and assist customers in a friendly and professional manner. Handle incoming calls, emails, and inquiries, providing accurate information and timely resolutions. Maintain a thorough understanding of our products/services to effectively address customer queries. Process customer orders, returns, and exchanges with attention to detail. Collaborate with internal teams to resolve customer issues and escalate when necessary. Keep accurate records of customer interactions and transactions. Assist in maintaining a clean and organized front office environment. Qualifications & Requirements: 3 - 5 years experience. Excellent communication and interpersonal skills. Strong problem-solving abilities. Proven experience in customer service or a related field. Proficient in basic computer applications. Ability to multitask and prioritize in a fast-paced environment.', 'Sri Lanka', '2026-08-06 09:23:22.288724+00', '2026-08-06 09:23:22.288724+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (587, 351, 8, 'Project Manager - Intern', true, 'Are you someone who thrives in fast-paced environments and loves making things happen? If you’re looking for a typical 9-to-5, clock-out-at-5 kind of role—this isn’t it. But if you’re hungry to learn, grow fast, and create real impact, you might just be the person we’re looking for. About Zyner.io: Zyner.io is a Global design subscription service built for speed and quality. We help startups move faster by delivering unlimited, high-quality designs on demand. From landing pages to pitch decks and branding to social media creatives, we’re the creative engine behind many fast-growing startups. The Role: Project Manager (Intern): This isn’t your average internship. You’ll step into a high-ownership role where you: Understand client needs: Talk directly to clients, gather their requirements, and translate them into clear, actionable tasks for the team. Own the project task board (ClickUp, Notion, Trello): Keep it organized, prioritized, and aligned with deadlines. Ensure on-time, high-quality delivery: Follow up with designers, unblock bottlenecks, and keep everything moving forward. Communicate clearly and often: Jump on internal and client calls to share updates, explain project scopes, and ensure alignment. Think ahead and stay proactive: Anticipate issues before they become problems and keep projects on track. Meet Your Team: Collaborate directly with senior designers and creative leads who know what it takes to deliver world-class designs. Work alongside the Founder, who partners with Y Combinator startups and drives product-first thinking. Be part of a lean, fast-moving team that values clarity, ownership, and ruthless execution. You’ll Thrive If You: Have excellent English communication skills, both written and spoken. Understand design and tech concepts—you don’t have to design, but you should be able to talk about it. Are obsessed with clarity, process, and getting things done. Can handle client discussions, team huddles, and last-minute changes with confidence. Have a hustler’s mindset—proactive, accountable, and always pushing for better. What We Offer: Real growth opportunities: Impress us, and this role can turn into a full-time, well-paid position faster than you think. Mentorship and hands-on learning: Work closely with experienced designers and a product-focused founder. A startup environment where your ideas and actions directly impact success. How to Apply: Send us: Your updated CV, LinkedIn profile link, A short video of you explaining why we should hire you—bonus points if you share a story where you took charge and made things happen! Ready to hustle, learn, and grow? Let’s build something amazing together!', 'Colombo, Sri Lanka', '2026-08-06 09:23:22.29324+00', '2026-08-06 09:23:22.29324+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (588, 350, 4, 'Management Trainees', false, 'Discover your dream career with BIGJOBS.lk...! BIGJOBS is a Colombo based executive search firm. We connect exceptional talent with top organizations across a diverse range of industries. BIGJOBS.lk specializes in personalized career matching for talented management trainees like you. We''re dedicated to understanding your unique strengths and ambitions, connecting you with top companies where you can learn, grow, and build a successful career. Find a job you''re passionate about. Submit your resume today and let BIGJOBS.lk guide your career journey.', 'Sri Lanka', '2026-08-06 09:23:22.295362+00', '2026-08-06 09:23:22.295362+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (659, 299, 4, 'Management Service Officer (Open)', false, 'Open competitive examination for recruitment to the Management Service Officer Service Grade III of the Eastern Province Public Service. Applicants must be citizens of Sri Lanka and permanent residents of the Eastern Province. Must be between 18 and 45 years of age. Educational qualifications include passing GCE O/L with six subjects including Language and Mathematics, or GCE A/L with three subjects. Salary scale: Rs. 48,470 - 10x540 - 11x630 - 10x1,010 - 10x1,190 - 82,800/-. The examination consists of two papers: Aptitude Test (100 marks, 40%) and Language Proficiency (100 marks, 40%). Candidates must obtain at least 40% in each paper and 50% overall. Recruitment is based on the provincial merit order.', 'Eastern Province, Sri Lanka', '2026-08-06 09:52:07.611515+00', '2026-08-06 09:52:07.611515+00', 123);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (589, 350, 4, 'HR Manager', false, 'We are seeking a dynamic and experienced HR Managers to join our clients team and drive the human resources function within their organization. The ideal candidate will be responsible for overseeing all aspects of HR operations, including talent acquisition, employee relations, performance management, and compliance. As the HR Manager, you will play a key role in fostering a positive workplace culture and ensuring the effective implementation of HR policies and procedures. Responsibilities: Lead and manage the full recruitment life cycle, from sourcing and interviewing to onboarding. Implement and maintain HR policies and procedures in compliance with applicable laws and regulations. Handle employee relations, addressing concerns, and fostering a positive work environment. Develop and execute strategies for talent development and retention. Manage performance appraisal processes and support career development initiatives. Stay updated on industry trends and best practices to enhance HR strategies. Collaborate with leadership to align HR initiatives with organizational goals. Qualifications: Bachelor''s degree in Human Resources, Business, or a related field. Proven experience as an HR Manager or similar role. Strong knowledge of HR best practices, employment laws, and regulations. Excellent communication and interpersonal skills. Ability to handle confidential information with discretion.', 'Sri Lanka', '2026-08-06 09:23:22.297895+00', '2026-08-06 09:23:22.297895+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (590, 350, 4, 'Mid - Level / Senior HR Professional', false, 'Key Responsibilities: 1. Recruitment and Onboarding 2. Employee Relations 3. Performance Management 4. HR Administration 5. Training and Development 6. Compliance. Qualifications: Bachelor''s degree in Human Resources, Business Administration, or a related field. Minimum 5 years of experience. Strong understanding of employment laws and regulations. Excellent communication and interpersonal skills. Proven ability to maintain confidentiality and handle sensitive information.', 'Colombo, Sri Lanka', '2026-08-06 09:23:22.301004+00', '2026-08-06 09:23:22.301004+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (591, 350, 4, 'Personal Secretary', false, 'Manage and maintain executives'' schedules, appointments, and travel arrangements. Handle confidential information with discretion and professionalism. Prepare and organize meetings, including agenda creation, minutes, and follow-up actions. Act as a liaison between executives and internal/external stakeholders. Draft and edit correspondence, reports, and presentations. Prioritize and manage multiple tasks simultaneously, demonstrating exceptional time management skills. Perform general office duties, such as filing, data entry, and office organization. Qualifications: Proven experience as a personal or confidential secretary. Strong organizational and communication skills. Proficiency in MS Office Suite. Exceptional attention to detail and the ability to maintain confidentiality. Excellent time management and multitasking abilities.', 'Colombo, Sri Lanka', '2026-08-06 09:23:22.302336+00', '2026-08-06 09:23:22.302336+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (592, 350, 4, 'Finance', false, 'Discover your dream career in Finance. BIGJOBS is a Colombo based executive search firm. We connect exceptional talent with top organizations across a diverse range of industries. BIGJOBS.lk specializes in personalized career matching for talented marketing professionals like you. We''re dedicated to understanding your unique strengths and ambitions, connecting you with top companies where you can learn, grow, and build a successful career. Tell us who you are, We will connect you to the right place. (Submit your updated resume)', 'Sri Lanka', '2026-08-06 09:23:22.304612+00', '2026-08-06 09:23:22.304612+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (593, 350, 4, 'Sales Management', false, 'Lead and motivate the sales team to achieve and exceed sales targets. Develop and implement strategic sales plans to expand our customer base. Foster strong relationships with key clients and partners. Provide coaching and guidance to sales team members for skill development. Analyze market trends and competitor activities to identify business opportunities. Collaborate with cross-functional teams to ensure effective product launches and promotions. Monitor and report on sales performance and market trends. Proven experience as a Sales Manager or in a similar role. Strong leadership and team management skills. Excellent communication and negotiation abilities. Demonstrated success in meeting and exceeding sales targets. Ability to analyze data and trends to make informed business decisions.', 'Sri Lanka', '2026-08-06 09:23:22.307385+00', '2026-08-06 09:23:22.307385+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (594, 352, 8, 'Accounts Internship', false, 'Start your career with our team as a Trainee - Accounts Executive and build a better future! We have a facility for allocating trainees for Internships in the Accounts field for those who are from recognized institutions studying under relevant courses. A training allowance will be paid. Those who complete the training successfully will have the chance to be employed in the same department in a suitable post. An attractive remuneration package will be offered to the selected candidate.', 'Moratuwa, Colombo', '2026-08-06 09:32:11.553578+00', '2026-08-06 09:32:11.553578+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (595, 353, 4, 'Accounts Executive (Female)', false, 'Minimum 2-3 years experience with Ms Office, Quick Book Knowledge. Pleasing personality. Excellent command of English and Sinhala. Age below 40 years. Salary between Rs. 45,000 and 60,000. An attractive package awaits the right candidate. Send your CV within 07 days of this advertisement to sgranite@eureka.lk or WhatsApp: 0772981172.', 'Nugegoda, Colombo, Sri Lanka', '2026-08-06 09:32:11.558282+00', '2026-08-06 09:32:11.558282+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (596, 354, 4, 'Call Center Associate', false, 'Handle inbound and outbound customer calls professionally and efficiently. Provide accurate information regarding Softlogic group products, services, and promotions. Resolve customer inquiries, complaints, and issues in a timely manner. Maintain detailed records of customer interactions and transactions. Adhere to company policies and ensure high levels of customer satisfaction. Candidates who are living within the Colombo District are highly encouraged to apply. Strong verbal communication and customer service skills. Ability to work flexible shifts and rosters. Computer literacy and the ability to multitask in a fast-paced environment. Benefits include an attractive remuneration package & incentives that are above market standards, all-inclusive salary of more than Rs. 40,000/=, flexible shift options, transport provided within Colombo city limits, and up to a 25% staff discount across all subsidiaries of the Softlogic Group companies (including Baskin Robbins, Burger King, ODEL, Bata, Glamour, Subway, Softlogic MAX, Popeyes, and Asiri Health).', 'Rajagiriya, Colombo, Sri Lanka', '2026-08-06 09:32:11.560101+00', '2026-08-06 09:32:11.560101+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (622, 372, 4, 'AAT Qualified Accountant – UK Accounts', false, 'AAT Level 4 qualified / MAAT preferred. Strong experience preparing UK statutory accounts under FRS 102. Experience working with UK accounting practices or UK SME clients. Knowledge of year-end accounts preparation and financial reporting. Understanding of trial balance review, balance sheet reconciliations, Profit & Loss preparation, accruals and prepayments, fixed asset registers, journals and adjustments, VAT returns, corporation tax support. Experience using UK accounting software: Xero, QuickBooks Online, Sage, Dext, TaxCalc (advantageous). Ability to communicate professionally with UK clients. Experience handling multiple client portfolios. Preferred experience: 2–5 years UK accounting experience, practice background (Accountancy firm experience preferred), experience preparing small company accounts, familiarity with Companies House filing requirements. ACCA/CIMA/ACA part-qualified candidates are advantageous.', 'Dehiwala, Dehiwala-Mount Lavinia, Sri Lanka', '2026-08-06 09:40:58.191574+00', '2026-08-06 09:40:58.191574+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (597, 355, 4, 'Crew Member', false, 'Job Fair - Multiple Positions Available (Crew Member / Delivery Rider / Commi Chef (Pastry & Bakery) / Supervisor / Maintenance Technician (Air Condition)). Event Details: Venue: Nuwara Eliya District Secretarial Office, Job Center. Date: 7th August 2026. Time: 9.00 a.m – 1.00 p.m. Requirements: Open to both Male & Female candidates. Energetic, reliable, and customer-service oriented. Specific qualifications/licenses may be required depending on the role (e.g., valid driving license for Delivery Rider, technical certifications for Maintenance Technician, culinary training for Commi Chef). Willingness to work in the hospitality, food service, and technical maintenance industry. Responsibilities: Carry out daily duties and tasks specific to the assigned role (Crew, Rider, Chef, Supervisor, or Technician). Deliver excellent service to customers and uphold company operational standards. Participate actively in the recruitment process at the Job Fair on August 7th. Attend and complete any provided free training & development sessions. Benefits: Attractive remuneration package & incentives that are above market standards. Additional Facilities Provided: Free Duty Meal, Accommodation, Staff Uniform, Insurance, Free Training & Development Sessions, and the opportunity to receive an NVQ Certificate.', 'Nuwara Eliya City, Nuwara Eliya, Sri Lanka', '2026-08-06 09:32:11.56314+00', '2026-08-06 09:32:11.56314+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (598, 356, 4, 'Beautician', false, 'We are looking for Male & Female unisex Salon Staff to join our team in Wattala. Requirements: Minimum 6 months of salon experience. Skilled in hair, beauty, or grooming services. Friendly, professional, and customer-focused. Ability to work well in a team.', 'Wattala, Gampaha, Sri Lanka', '2026-08-06 09:32:11.567788+00', '2026-08-06 09:32:11.567788+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (599, 357, 4, 'Accounts Assistant', false, 'Hammer BTL (Pvt) Ltd. is looking for a detail-oriented Accounts Assistant to support the finance team with day-to-day accounting and bookkeeping activities. Key responsibilities include recording daily financial transactions, invoices, bills, and receipts accurately; maintaining accounting records using QuickBooks; assisting with bookkeeping and financial documentation; preparing and updating reports using Microsoft Excel; ensuring accuracy and confidentiality of financial records; and supporting the finance team with administrative and accounting tasks. Requirements include G.C.E. Advanced Level (A/L) qualification or a relevant diploma, basic bookkeeping knowledge or a foundation-level accounting qualification, proficiency in Microsoft Excel, familiarity with QuickBooks or similar accounting software (added advantage), strong attention to detail and numerical skills, good verbal and written communication skills, and ability to work independently and meet deadlines. The company offers an attractive salary and benefits, a friendly and professional working environment, career growth and learning opportunities, and hands-on experience in accounting and finance operations.', 'Rajagiriya, Colombo', '2026-08-06 09:32:11.569355+00', '2026-08-06 09:32:11.569355+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (600, 354, 4, 'Call Center Associate', false, 'Handle inbound and outbound customer calls professionally and efficiently. Provide accurate information regarding Softlogic group products, services, and promotions. Resolve customer inquiries, complaints, and issues in a timely manner. Maintain detailed records of customer interactions and transactions. Adhere to company policies and ensure high levels of customer satisfaction. Candidates who are living within the Colombo District are highly encouraged to apply. Strong verbal communication and customer service skills. Ability to work flexible shifts and rosters. Computer literacy and the ability to multitask in a fast-paced environment. Benefits include an attractive remuneration package & incentives that are above market standards, all-inclusive salary of more than Rs. 40,000/=, flexible shift options, transport provided within Colombo city limits, and up to a 25% staff discount across all subsidiaries of the Softlogic Group companies.', 'Colombo 3, Sri Lanka', '2026-08-06 09:32:11.570651+00', '2026-08-06 09:32:11.570651+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (601, 358, 4, 'All Rounder', false, 'A young male or female is required for an all-round position at a medium-scale tourist hotel in Dambulla. Accommodation and food are provided. No experience needed. Contact for more details.', 'Dambulla, Matale, Sri Lanka', '2026-08-06 09:32:11.571523+00', '2026-08-06 09:32:11.571523+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (602, 359, 4, 'Bike Rider for Kegalle', false, 'Courier delivery rider position with a nationwide courier company in Sri Lanka. Training and untrained candidates welcome. Minimum qualifications: age 18+, valid driving license. Company provides motorcycle. Salary between Rs 40,000 and Rs 45,000. Benefits include daily fuel allowance, mobile allowance, attendance allowance, vehicle allowance, promotions based on performance, uniforms, courier bag and raincoats provided. Immediate recruitment.', 'Kegalle City, Kegalle, Sri Lanka', '2026-08-06 09:32:11.572313+00', '2026-08-06 09:32:11.572313+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (603, 354, 4, 'Crew Member', false, 'Multiple positions available including Crew Member, Delivery Rider, Commi Chef (Pastry & Bakery), Supervisor, and Maintenance Technician (Air Condition). Candidates should be energetic, reliable, and customer-service oriented. Specific qualifications/licenses may be required depending on the role. Responsibilities include carrying out daily duties specific to the assigned role, delivering excellent service to customers, participating in the recruitment process at the Job Fair on August 7th, and attending free training & development sessions. Benefits include an attractive remuneration package, free duty meal, accommodation, staff uniform, insurance, free training & development sessions, and the opportunity to receive an NVQ Certificate.', 'Nuwara Eliya City, Sri Lanka', '2026-08-06 09:32:11.573976+00', '2026-08-06 09:32:11.573976+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (604, 360, 4, 'Team Player', false, 'We are looking for a team player with multiple responsibilities. Age: below 30 years. Skills: strong communication skills and excellent attitude towards teamwork. Willingness to learn in a professional environment. Responsibilities include invoicing, inventory management, customer handling, etc. Apply by sending your CV to jincofinance@gmail.com or contact/WhatsApp 070-1516713. Address: No 73A, Old Kottawa Road, Mirihana.', 'Mirihana', '2026-08-06 09:40:06.108429+00', '2026-08-06 09:40:06.108429+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (605, 361, 4, 'Assistant Accountant', false, '', 'Colombo 10', '2026-08-06 09:40:06.113815+00', '2026-08-06 09:40:06.113815+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (614, 350, 4, 'Marketing Manager', false, 'As the Marketing Manager you will play a pivotal role in developing and executing strategic marketing initiatives to enhance brand awareness, drive customer engagement, and boost sales. Responsibilities: Develop and implement comprehensive marketing strategies to promote the brand across various channels. Conduct market research to identify trends, customer preferences, and opportunities for growth. Collaborate with cross-functional teams to ensure alignment between marketing and overall business objectives. Plan and execute integrated marketing campaigns, including digital marketing, social media, events, and partnerships. Analyze marketing performance metrics and adjust strategies as needed to achieve goals. Manage the marketing budget effectively, ensuring optimal allocation of resources. Stay abreast of industry trends and competitors to identify new opportunities. Qualifications & Requirements: BSc / MSc in Marketing, Business, or a related field. 5 - 6 Years experience. Proven experience as a Marketing Manager in the fashion or retail industry. Strong understanding of the Sri Lankan market and consumer behavior. Demonstrated success in developing and implementing successful marketing strategies. Excellent communication, interpersonal, and leadership skills. Proficiency in digital marketing tools and platforms.', 'Colombo, Sri Lanka', '2026-08-06 09:40:58.172047+00', '2026-08-06 09:40:58.172047+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (606, 362, 4, 'Sr. Executive | Assistant Manager - Procurement & Inventory', false, 'Core Responsibilities: 1. Procurement Management - Oversee both local and coordination with international procurement activities. Maintain clear, professional communication with management to obtain necessary approvals on all procurement actions. Maintain and share necessary Procurement status review track records. 2. Inventory & Warehouse Oversight - Master the warehouse inventory system to maintain necessary stocks, preventing both shortages and overstocking. Oversee the end-to-end process of inventory documentation, including the generation of Purchase Orders (PO) and Goods Received Notes (GRN). 3. Cross-Functional Coordination & Delivery - Drive seamless internal coordination with cross-functional departments, including Quality Control (QC), Production (PRD), Finance, and Engineering, to align procurement and inventory with technical requirements and budget approvals. Collaborate with superiors in real-time to ensure the seamless execution of departmental tasks and production needs. 4. Import & Statutory Compliance - Lead all import-related activities, ensuring timely coordination for statutory approvals from NMRA, MOH, ICL, and the Precursor Department. Proactive Liaison: Willingness and ability to personally visit all relevant government offices and statutory bodies whenever necessary to expedite approvals and resolve pending issues. Candidate Profile: Educational Background: A Bachelor''s Degree in Procurement, Inventory management or Transport & Logistics, Business Management, or an equivalent professional qualification from a recognized institute in Sri Lanka. Experience: Minimum 4 to 7 years of industrial experience in Procurement, Inventory management & Import. Direct experience in Pharmaceutical/FMCG or Laboratory materials is a major advantage. Technical Skills: Advanced knowledge in working with ERP systems for inventory control and PO/GRN processing. Communication: Excellent command of both English and Sinhala (written and spoken) for effective internal and external coordination. Mobility: Must be prepared to travel to various government departments as required to facilitate import approvals. Leadership: Ability to handle and mentor subordinates with various levels of experience in their respective fields. Successful candidates may look forward to an attractive remunerating package commensurate with qualification & experience.', 'Katunayaka, Sri Lanka', '2026-08-06 09:40:06.116614+00', '2026-08-06 09:40:06.116614+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (607, 363, 4, 'Accountant', false, '', 'Colombo 3', '2026-08-06 09:40:06.119969+00', '2026-08-06 09:40:06.119969+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (608, 364, 4, 'Brand Manager / Assistant Brand Manager', false, 'Develop and execute strategic marketing plans to grow the Colour Cosmetics and Fragrance portfolio. Drive brand positioning and increase market share through innovative ATL, BTL, digital, and trade marketing initiatives. Conduct regular market visits, consumer research, and competitor analysis to identify emerging trends and business opportunities. Build and maintain strong relationships with beauty salons, fancy stores, modern trade partners, distributors, influencers, and other key industry stakeholders to strengthen brand visibility. Plan and execute product launches, promotional campaigns, beauty activations, exhibitions, and marketing events. Bachelor''s Degree or Professional Qualification in Marketing such as CIM (UK), SLIM, or an equivalent marketing qualification will be a distinct advantage. Minimum 6-8 years of experience in Brand Management, preferably in Cosmetics, Beauty, Personal Care, or FMCG. Excellent communication, presentation, negotiation, and relationship-building skills. An energetic, outgoing, and confident personality who enjoys meeting customers, conducting market visits, and representing the brand at industry events.', 'Bandaragama', '2026-08-06 09:40:06.122778+00', '2026-08-06 09:40:06.122778+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (609, 365, 4, 'Trainee / Commis 3 (Full Time) / Commis 2 (Part Time)', false, 'Hiring Trainee/Commis 3 (Full-time) with salary LKR 50,000, shift time 1PM-9PM, no accommodation, no service charge. Also hiring Commis 2 (Part-time) with salary LKR 40,000, shift time 5PM-9PM, 6 off days a month, no service charge. Location: Dunkers Churros, Odel Alexandra Place, Colombo 7. WhatsApp CV to +94 76 807 1425.', 'Colombo 7, Sri Lanka', '2026-08-06 09:40:06.128583+00', '2026-08-06 09:40:06.128583+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (610, 366, 4, 'Chief Marketing Officer (CMO)', false, 'Develop and lead comprehensive marketing strategies aligned with business goals. Oversee SEO and AEO strategies to improve brand visibility and drive organic growth. Use AI tools to analyze data, identify market trends, and conduct in-depth market research. Lead and manage social media marketing across all major platforms. Manage and mentor the marketing team using AI-driven tools and performance insights. Plan, execute, and optimize marketing campaigns across multiple channels. Collaborate with leadership to drive brand positioning, demand generation, and customer acquisition. Measure performance, prepare reports, and provide actionable insights for continuous improvement. Requirements: Strong expertise in SEO and AEO. Solid understanding and practical experience with AI tools for market research and data analysis. In-depth knowledge of social media marketing and digital channels. Proven ability to manage a marketing department using modern tools and platforms. Experience in planning, executing, and optimizing marketing activities. Minimum 2 years of experience in US-based marketing or working with US clients. Excellent leadership, communication, and analytical skills.', 'Colombo 5, Sri Lanka', '2026-08-06 09:40:06.130989+00', '2026-08-06 09:40:06.130989+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (611, 367, 4, 'Internal Audit & Compliance Officer', false, '', 'Sri Jayawardanapura Kotte', '2026-08-06 09:40:06.133162+00', '2026-08-06 09:40:06.133162+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (612, 368, 4, 'Legal Officer', false, 'Assist the Conveyancing Unit of the Legal Department in the preparation of Title Reports, and the drafting and attestation of Mortgage Bonds and other notarial instruments. Support the Litigation Unit by appearing and representing the Bank before Courts and other tribunals in both civil and criminal matters, as and when required. Provide legal opinions, guidance, and advisory support on a wide range of legal and regulatory matters affecting the Bank''s operations and interests. Ensure legal documentation is prepared accurately and in compliance with applicable laws, regulations, and internal policies. Liaise with internal stakeholders, external counsel, and regulatory authorities to facilitate the effective handling of legal matters and transactions. Candidate Prerequisites: Attorney-at-Law and Notary Public authorized to practice within the jurisdiction of Negombo, holding valid Notarial Licenses to practice in both English and Sinhala. An LLB degree or higher legal qualification from a recognized institution will be considered a distinct advantage. Minimum 5-7 years of relevant experience in a commercial bank, financial institution, or reputed law firm. Strong knowledge of and hands-on experience in conveyancing and property-related legal documentation. Excellent written and verbal communication skills in English; proficiency in Tamil will be an added advantage. Strong customer service orientation, effective time-management skills, and the ability to work independently with minimal supervision, particularly in high-pressure environments. Proficient in working within a computerized and digital work environment. Remuneration: The successful candidates will be provided with an attractive remuneration package including fringe benefits, commensurate with industry standards.', 'Negombo, Sri Lanka', '2026-08-06 09:40:06.134654+00', '2026-08-06 09:40:06.134654+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (613, 369, 4, 'Sports Massage Therapist', false, 'Provide sports massage treatments to support recovery, performance, and injury prevention. Assess clients'' needs and recommend appropriate treatment plans. Maintain accurate treatment records. Educate clients on stretching, recovery, and injury prevention techniques. Work closely with other healthcare and rehabilitation professionals. Qualification in Sports Massage Therapy or a related field. Strong communication and interpersonal skills. Ability to work independently and as part of a team. Professional, reliable, and client-focused. Previous experience is an advantage. Competitive salary, friendly and supportive work environment, opportunities for professional development, modern facilities and equipment.', 'Kohuwala', '2026-08-06 09:40:06.136721+00', '2026-08-06 09:40:06.136721+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (615, 350, 4, 'Admin & Operation Management', false, 'Key Responsibilities: 1. Administrative Excellence: Ensure the smooth functioning of office operations by managing administrative tasks, including office supplies, equipment maintenance, and vendor relationships. 2. Team Coordination: Collaborate with various departments to streamline communication and coordination, fostering a positive and efficient work environment. 3. Process Improvement: Identify and implement operational enhancements to boost productivity and efficiency across the organization, maintaining a focus on continuous improvement. 4. Facility Management: Supervise office facilities, ensuring a safe and conducive working environment for all employees. 5. Project Support: Provide support for various projects, including planning, execution, and follow-up to meet organizational goals. 6. Budget Oversight: Assist in budget planning and control, monitoring expenses related to administration and operations. 7. Compliance: Stay updated on relevant regulations and ensure organizational compliance with applicable laws and standards. Qualifications & Requirements: 3-5 years experience; Bachelor''s degree in Business Administration or a related field; Proven experience in administration and operations management; Strong organizational and problem-solving skills; Excellent communication and interpersonal abilities; Proficient in Microsoft Office Suite.', 'Sri Lanka', '2026-08-06 09:40:58.175604+00', '2026-08-06 09:40:58.175604+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (616, 350, 4, 'Asst, Manager - Marketing', false, 'BIGJOBS is a Colombo based executive search firm. We connect exceptional talent with top organizations across a diverse range of industries. BIGJOBS.lk specializes in personalized career matching for talented marketing professionals like you. We''re dedicated to understanding your unique strengths and ambitions, connecting you with top companies where you can learn, grow, and build a successful career. Find a job you''re passionate about. Submit your resume today and let BIGJOBS.lk guide your career journey.', 'Panadura, Sri Lanka', '2026-08-06 09:40:58.18012+00', '2026-08-06 09:40:58.18012+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (617, 350, 4, 'Trainee Marketing Executives', false, 'We are seeking a dynamic and motivated Trainee Marketing Executive to join our clients firm. Key Responsibilities: Marketing: Assist in developing and implementing marketing strategies to promote the firm''s services. Contribute to the creation of content for social media, websites, and other digital platforms. Support in organizing and executing marketing campaigns, including email marketing, webinars, and events. Identify trends and opportunities within the recruitment and HR industry. Human Resources: Assist in the end-to-end recruitment process, from sourcing candidates to scheduling interviews. Support the HR team in managing applicant tracking systems and maintaining candidate databases. Participate in employer branding activities, such as creating job postings and updating career pages. Help in the coordination of onboarding processes and employee engagement initiatives. Provide administrative support to the HR team, including maintaining records and preparing reports. Requirements: Bachelor’s degree in Marketing, Human Resources, Business Administration, or a related field. Strong interest in developing a career in marketing or human resources. Excellent communication and interpersonal skills. Proficient in MS Office (Word, Excel, PowerPoint) and familiarity with digital marketing tools. Ability to work independently and as part of a team. High attention to detail and strong organizational skills. Previous internship or work experience in marketing or HR is a plus. What We Offer: Structured training and mentorship from industry professionals. Opportunities for career growth and development. Exposure to a wide range of marketing and HR practices. A supportive and collaborative work environment.', 'Colombo, Sri Lanka', '2026-08-06 09:40:58.182431+00', '2026-08-06 09:40:58.182431+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (618, 350, 4, 'CFO / CEO / COO / CMO', false, 'BIGJOBS is a Colombo based executive search firm. We connect exceptional talent with top organizations across a diverse range of industries. Our clients range from dynamic small and medium enterprises (SMEs) to prominent publicly listed companies (PLCs) across a wide spectrum of industries, including technology, healthcare, finance, and many more. Submit your updated resume and let us connect you with the right opportunity.', 'Colombo, Sri Lanka', '2026-08-06 09:40:58.183287+00', '2026-08-06 09:40:58.183287+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (619, 350, 4, 'Asst Manager - Legal & Company Secretarial', false, 'Our client is seeking a dynamic and experienced legal professional to lead legal and company secretarial operations while ensuring corporate compliance and governance standards. Key responsibilities include handling legal advisory matters, drafting and reviewing legal documentation, managing company secretarial functions, regulatory coordination, and leading the legal & secretarial team to deliver professional client-focused solutions. Candidate Profile: Attorney-at-Law with LL.B / LL.M qualifications. Minimum 6 years of post-qualification experience. Strong knowledge of Companies Act & ROC procedures. Experience in legal drafting, compliance & company secretarial functions. Strong communication and leadership skills. Fluent in English & Sinhala. Age below 40 years. This role is ideal for a proactive legal professional who is capable of balancing legal expertise, corporate governance, and team leadership within a fast-paced business environment.', 'Colombo, Sri Lanka', '2026-08-06 09:40:58.18427+00', '2026-08-06 09:40:58.18427+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (620, 370, 4, 'Assistant Lecturer - Finance', false, 'Deliver lectures in Finance and Accounting related modules. Prepare lesson plans, assessments, and learning materials. Guide and mentor students to achieve academic success. Maintain accurate academic records and support examination activities. Contribute to curriculum development and academic quality initiatives. Minimum 1 year of teaching experience in Finance or Accounting is preferred. Industry experience in Finance or Accounting will be an added advantage. Professional qualifications (CIMA, ACCA, CA or equivalent) will be an added advantage. Excellent communication and presentation skills.', 'Kurunegala, Sri Lanka', '2026-08-06 09:40:58.186549+00', '2026-08-06 09:40:58.186549+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (621, 371, 4, 'QA Engineer', true, 'Perform end-to-end manual QA testing across the entire Cryptoworth application. Pay close attention to specifically flagged features/modules during each testing cycle. Design and execute test cases covering functional, regression, and UI testing. Identify, document, and log bugs/issues clearly with steps to reproduce, screenshots, and severity. Create tickets for identified issues and assign them to the relevant team, tracking them through to resolution. Verify bug fixes and perform regression testing before releases. Work closely with developers and product managers to understand feature requirements and edge cases. Maintain test documentation, checklists, and QA reports. Participate in Agile ceremonies. Minimum 2 years of professional experience in manual QA / software testing. Mandatory prior experience testing accounting, fintech, or financial software platforms. Strong understanding of QA methodologies, test case design, and bug lifecycle management. Experience with bug tracking tools. Ability to read and understand basic SQL queries for data validation. Familiarity with Agile/Scrum workflows. Strong attention to detail. Benefits include team first supportive culture, fast growing crypto & blockchain industry, fully remote work setup, competitive USD compensation, and opportunity to work closely with product, engineering, and support teams.', 'Sri Lanka', '2026-08-06 09:40:58.189076+00', '2026-08-06 09:40:58.189076+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (623, 372, 4, 'QA Assistant cum Junior Trainer – UK Accountancy Operations', false, 'We are seeking a QA Assistant cum Junior Trainer to support the training, quality assurance, and continuous development of our UK Accountancy team. The ideal candidate will have a good understanding of UK accounting practices and will be responsible for assisting with new joiner training, conducting quality reviews, identifying knowledge gaps, and supporting employees to meet client expectations. Key responsibilities include: Training & Development: Assist in delivering training programs for new joiners in UK Accountancy processes; conduct refresher training sessions on accounting concepts, software usage, and client-specific procedures; support employees in developing practical knowledge of UK bookkeeping and accounting practices; prepare training materials, process guides, SOPs, and learning resources; monitor trainee progress and provide regular feedback; conduct knowledge assessments and evaluate training effectiveness. Quality Assurance: Review accounting tasks completed by team members to ensure accuracy and compliance with client requirements; conduct quality checks on bookkeeping, reconciliations, VAT-related tasks, and accounting outputs; identify recurring errors and provide coaching to improve accuracy; maintain QA scorecards and prepare quality performance reports; collaborate with Team Leaders and Managers to implement improvement plans. UK Accountancy Support: Provide guidance on UK accounting processes, including bookkeeping principles, bank reconciliations, VAT processes, purchase and sales ledger management, month-end procedures, and accounting software usage (Xero, QuickBooks, Sage, Dext, TaxCalc); support employees in understanding UK client expectations and communication standards. Reporting & Continuous Improvement: Track training completion and employee development progress; prepare weekly/monthly reports on training and QA performance; identify process improvement opportunities; support operational teams in maintaining high-quality service delivery. Requirements: 1–3 years of experience in UK Accounting, Bookkeeping, Audit, or Finance Operations; good understanding of UK accounting practices and compliance requirements; experience with accounting software such as Xero, QuickBooks, Sage, Dext, TaxCalc (added advantage); strong communication and presentation skills; ability to explain accounting concepts clearly to trainees; strong attention to detail and analytical skills. Preferred Qualifications: AAT / ACCA / CIMA / CA (completed or part-qualified) preferred; previous experience as an Accountant, Senior Associate Accountant, QA Analyst, or Trainer; experience working with UK accounting clients or offshore accounting teams.', 'Dehiwala, Dehiwala-Mount Lavinia, Sri Lanka', '2026-08-06 09:40:58.194496+00', '2026-08-06 09:40:58.194496+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (624, 373, 4, 'Restaurant Waiter', false, 'Join the BOHO Restaurant Team – Negombo! We are currently hiring Waiters to join our growing team. What we offer: Attractive monthly salary, Monthly service charge, Performance-based bonuses, Friendly and supportive working environment, Career growth opportunities. Requirements: Positive attitude and willingness to learn, Previous experience is an advantage, but not required, Honest, responsible, and hardworking, Good teamwork and customer service skills, Looking for candidates who are committed and interested in working with us for the long term.', 'Negombo, Gampaha, Sri Lanka', '2026-08-06 09:49:40.21407+00', '2026-08-06 09:49:40.21407+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (625, 374, 4, 'පිලිගැනීමේ නිලධාරිනියක් අවශ්‍යයි', false, 'ගල්කිස්ස පිහිටි නීතිගත ආයුර්වේද තෙරපි ආයතනයක් සඳහා පිලිගැනීමේ නිලධාරිනියක් අවශ්‍යයි. වැටුප රුපියල් 80000/- පිලියන්දල , දෙහිවල, රත්මලාන , අවටින් දිනපතා පැමිණිය හැකි කෙනෙක් විශේෂයි. සුහදශීලී ආරක්ෂිත වටපිටාවකි.', 'Mount Lavinia, Colombo', '2026-08-06 09:49:40.223125+00', '2026-08-06 09:49:40.223125+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (626, 148, 4, 'Training Coordinator', false, 'The Training Coordinator is responsible for delivering and coordinating training programmes across an assigned cluster of restaurants in accordance with the training plan developed by the Training Manager. Key responsibilities include delivering training programmes as per the approved training calendar, conducting refresher training sessions, providing training support to restaurants, visiting restaurants to identify training needs, coaching and mentoring employees, assessing employee learning through practical evaluations, maintaining training records, preparing weekly and monthly training reports, ensuring compliance with company policies and food safety standards, collecting feedback for continuous improvement, and assisting the Training Manager in developing new training programmes. Qualifications include G.C.E. Advanced Level or equivalent, with a Diploma or Certificate in Hospitality Management, Training & Development, or a related field as an added advantage. Minimum of 2 years'' experience in hospitality, restaurants, retail, or a training-related environment is required. Skills include excellent presentation and facilitation skills, good command of spoken and written English, strong communication and interpersonal skills, coaching and mentoring abilities, strong planning and organizational skills, good report writing and documentation skills, problem-solving and analytical skills, basic computer literacy including Microsoft Office, and ability to travel within the assigned restaurant cluster.', 'Colombo 4, Sri Lanka', '2026-08-06 09:49:40.2294+00', '2026-08-06 09:49:40.2294+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (627, 375, 4, 'Procurement Coordinator', false, 'We are looking for a dynamic and result-oriented individual to handle used plastic materials / PET bottle sourcing and supplier coordination island-wide for recycling purposes, ensuring a continuous supply of materials to meet production targets. Key responsibilities include sourcing, negotiating, and purchasing used plastic materials/PET bottles from local suppliers, collectors, vendors and businesses; ensuring continuous supply of plastic materials/PET bottles to meet production requirements; negotiating prices, quantities and delivery terms in line with company targets; coordinating with collection teams to arrange timely collection and delivery of materials; maintaining accurate purchase records, supplier details and daily collection reports; ensuring purchased materials meet company quality standards; and traveling island-wide to identify new sources of used plastic materials and maintain strong supplier networks. Requirements include G.C.E. A/L qualification or Diploma/professional qualification in Procurement (added advantage), 2–4 years’ experience in procurement or purchasing (preferably in recycling, waste management, plastic or PET material sourcing), strong negotiation and communication skills, ability to work independently and meet procurement targets, willingness to travel extensively and work in field-based conditions, and a motorcycle or vehicle with a valid Sri Lankan driving license.', 'Wellampitiya, Colombo, Sri Lanka', '2026-08-06 09:49:40.235456+00', '2026-08-06 09:49:40.235456+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (628, 376, 4, 'Marketing Executive - Nugegoda', false, 'Achieve sales targets and contribute to company revenue. Visit clients to present and promote products/services and handle distribution. Resolve customer problems and complaints to maximize satisfaction. Connect with potential corporate customers to promote products/services. Negotiate and close agreements, ensuring customer satisfaction and retention. Support the head of the division in implementing business strategies. Establish, develop, and maintain good customer relationships.', 'Nugegoda, Sri Lanka', '2026-08-06 09:49:40.238357+00', '2026-08-06 09:49:40.238357+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (629, 357, 4, 'Marketing Coordinator', false, 'Coordinate and support marketing campaigns and daily marketing operations. Communicate effectively with internal teams and external stakeholders. Handle urgent transportation and logistics requirements when necessary. Ensure assigned tasks are completed within deadlines. Adapt to changing priorities and support the team as required. Requirements: Hands-on experience in marketing support and operations coordination. Excellent verbal and written communication skills. Strong organizational and time management skills. Ability to work under pressure and meet strict deadlines. Quick decision-making and problem-solving abilities. Flexible, adaptable, and willing to handle changing work requirements. What We Offer: Attractive remuneration package. Opportunity to work with a growing and dynamic organization. Professional and supportive work environment. Career growth and development opportunities.', 'Rajagiriya, Sri Lanka', '2026-08-06 09:49:40.241023+00', '2026-08-06 09:49:40.241023+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (633, 357, 4, 'Field Operation Assistant', false, 'Hammer BTL (Pvt) Ltd. is seeking a dedicated and energetic Field Operation Assistant to support day-to-day field operations and office-related activities. The ideal candidate should be organized, adaptable, and willing to travel to different work sites as required. Key Responsibilities: Assist with daily field operations and coordinate assigned tasks. Visit work sites and carry out office-related field duties. Communicate effectively with team members and clients. Ensure assigned tasks are completed efficiently and on time. Follow company procedures and management instructions. Support operational activities as required. Requirements: Previous experience in field operations or a similar role will be an added advantage. Ability to manage work efficiently and independently. Excellent verbal and written communication skills. Willingness to travel to work sites and perform daily field-related tasks. Ability to adapt to changing priorities and management requirements. Positive attitude with strong teamwork and problem-solving skills. What We Offer: Attractive salary and benefits. Opportunities for career growth and development. Supportive and dynamic work environment. Hands-on experience in a growing organization.', 'Rajagiriya, Colombo', '2026-08-06 09:49:40.247027+00', '2026-08-06 09:49:40.247027+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (634, 244, 4, 'Client Service Associates', false, 'Provide professional and timely support to clients through phone, email, and other communication channels. Build and maintain strong relationships with clients by understanding their requirements. Handle client inquiries, requests, and complaints efficiently. Coordinate with internal departments to ensure prompt resolution of client issues. Maintain accurate records of client interactions and service requests. Prepare reports and follow up on pending client matters. Ensure high levels of customer satisfaction and service quality. Assist with onboarding new clients and maintaining client accounts. Adhere to company policies and service standards at all times. Requirements: Bachelor''s Degree or Diploma in Business Administration, Management, Marketing, or a related field. Previous experience in customer service, client relations, or account management will be an added advantage. Excellent communication and interpersonal skills. Strong problem-solving and conflict-resolution abilities. Good organizational and time management skills. Proficiency in Microsoft Office applications. Ability to multitask and work in a fast-paced environment. Customer-focused attitude with strong attention to detail. Benefits: Attractive monthly salary of LKR 160,000. Career development opportunities. Professional and supportive working environment. Performance-based growth opportunities.', 'Colombo, Sri Lanka', '2026-08-06 09:50:18.406356+00', '2026-08-06 09:50:18.406356+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (635, 244, 4, 'Junior Accountants', false, 'Assist in maintaining accurate financial records and accounting documents. Prepare journal entries, invoices, and payment vouchers. Reconcile bank statements and company accounts. Assist in preparing monthly financial reports and management accounts. Process accounts payable and accounts receivable transactions. Maintain petty cash records and expense reports. Support payroll processing and statutory payments where required. Ensure compliance with company accounting policies and financial regulations. Assist during internal and external audits. Perform other accounting and administrative duties as assigned. Requirements: Bachelor''s Degree or Diploma in Accounting, Finance, or a related field. Part qualification in AAT, CA, ACCA, CIMA, or CMA will be an added advantage. Previous experience in accounting or finance will be an added advantage. Good knowledge of accounting principles and bookkeeping. Proficiency in Microsoft Excel and other Microsoft Office applications. Familiarity with accounting software will be an added advantage. Strong analytical and numerical skills. Excellent attention to detail and organizational skills. Ability to work independently and as part of a team. Benefits: Attractive remuneration package. Career growth and professional development opportunities. Supportive and collaborative working environment.', 'Colombo, Sri Lanka', '2026-08-06 09:50:18.413731+00', '2026-08-06 09:50:18.413731+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (636, 372, 4, 'UK Payroll Specialist', false, 'Process end-to-end UK payroll accurately and within statutory deadlines. Calculate salaries, overtime, bonuses, commissions, SSP, SMP, SPP, and other statutory payments. Manage PAYE, National Insurance, pensions, and payroll deductions. Prepare and submit payroll reports and RTI (Real Time Information) filings. Ensure compliance with UK payroll legislation and HMRC requirements. Resolve payroll queries promptly and professionally. Maintain accurate employee payroll records and confidentiality. Work closely with UK clients and internal teams to deliver exceptional service. Minimum 2 years of current hands-on experience processing UK payroll. Strong knowledge of HMRC regulations, PAYE, National Insurance, pensions, and statutory payments. Experience with UK payroll software such as BrightPay, Moneysoft, Sage Payroll, IRIS, or similar. Excellent Microsoft Excel skills. Strong attention to detail and ability to meet strict payroll deadlines. Excellent written and spoken English communication skills. Payroll qualifications or accounting qualifications (AAT, ACCA, CIMA, or equivalent) will be an added advantage. Benefits include Performance Bonuses, Medical Insurance, Career Development, Professional Training, and Back home Transport for Female Employees.', 'Dehiwala-Mount Lavinia, Sri Lanka', '2026-08-06 09:50:18.42066+00', '2026-08-06 09:50:18.42066+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (637, 379, 4, 'Data Labeler - Night Shift', false, 'Accurately label video data using Label Studio, adhering to specific guidelines and protocols. Maintain high levels of precision and quality in data labelling tasks. Collaborate with the AI development team to understand labelling requirements and standards. Participate in training sessions to improve labelling skills and understand the nuances of the task. Perform quality checks on labelled data to ensure consistency and accuracy. Assist with additional tasks and projects as required, contributing to the diverse needs of the team. Diploma or equivalent qualification in Computer Science or IT-related field; further education or certification is a plus. Strong attention to detail and commitment to accuracy. Basic understanding of AI and machine learning concepts is beneficial. Ability to learn new software and tools quickly. Good communication skills and the ability to work collaboratively in a team environment. Ability to manage time effectively and meet deadlines. Benefits include the experience of creating and implementing highly-valuable and innovative technology, high-impact working environment with flat hierarchies and short decision-making processes, state-of-the-art hardware to work with and a modern software infrastructure, and a beautiful office in the heart of Colombo.', 'Colombo, Sri Lanka', '2026-08-06 09:50:18.424764+00', '2026-08-06 09:50:18.424764+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (638, 379, 7, 'Data Labeler - Weekends and Holidays', false, 'Embark on a journey into the world of data and machine learning as a Data Labelling Trainee at Atlas Labs. If you have a keen eye for detail, a passion for working with data, and a desire to learn, join us on the cutting edge of technology. About Atlas Labs: Atlas Labs is a progressive technology company focused on creating exceptional technology products and services that propel progress and have a positive impact on the world. At the heart of everything we do is to liaise our culture of passion, commitment and excellence. We''re all about cultivating an environment where creativity thrives and excellence is the norm. With a burning passion to achieve greatness, we''re committed to going above and beyond to deliver the best possible outcomes for our clients and ourselves. We are not an ordinary company and we are not looking for people who want just another job. Our team consists of truly driven individuals, working together to achieve the unimaginable. Your Role: This role requires availability to work on weekends and holidays. Accurately label video data using Label Studio, adhering to specific guidelines and protocols. Maintain high levels of precision and quality in data labelling tasks. Collaborate with the AI development team to understand labelling requirements and standards. Participate in training sessions to improve labelling skills and understand the nuances of the task. Perform quality checks on labelled data to ensure consistency and accuracy. Assist with additional tasks and projects as required, contributing to the diverse needs of the team. Your Profile: Diploma or equivalent qualification in Computer Science or IT-related field; further education or certification is a plus. Strong attention to detail and commitment to accuracy. Basic understanding of AI and machine learning concepts is beneficial. Ability to learn new software and tools quickly. Good communication skills and the ability to work collaboratively in a team environment. Ability to manage time effectively and meet deadlines. Benefits: In addition to our wonderful team, our great culture, and our magnificent vision, there are a wide range of additional benefits that makes Atlas Labs an amazing place to work! You can receive: The experience of creating and implementing highly-valuable and innovative technology, while contributing to the long-term growth of a successful tech company. High-impact working environment with flat hierarchies and short decision-making processes. State-of-the-art hardware to work with and a modern software infrastructure. A beautiful office in the heart of Colombo!! Apply Today: Don''t meet every single requirement? If you''re excited about this role but your past experience doesn''t align perfectly with every qualification in the job description, we encourage you to apply anyway. You may be just the right candidate for this or other roles.', 'Colombo, Sri Lanka', '2026-08-06 09:50:18.425905+00', '2026-08-06 09:50:18.425905+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (789, 343, 4, 'Mechanic (Heavy Machinery), Welder, High-Bed Trailer Driver, Machine Helper (M/F), Heavy Vehicle Driver', false, 'ISO 9001:2015 / EMS 14001:2015 / OHSAS 18001:2007 certified, CIDA(ICTAD)-registered GP-B1 grade piling/construction contractor, hiring across 5 categories. Attractive salary based on age and experience.', 'Sri Lanka', '2026-08-07 03:42:11.815834+00', '2026-08-07 03:42:11.815834+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (790, 344, 4, 'Air Conditioning Technician (vehicle & home AC)', false, 'ISO 9001:2015 certified. Requires O/L pass with maths & science; NVQ Level IV preferred; practical training/certification an advantage; age under 45; 5 years'' experience preferred; English skills a plus.', 'Sri Lanka', '2026-08-07 03:42:11.819101+00', '2026-08-07 03:42:11.819101+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (639, 244, 4, 'Customer Support Representatives', false, 'Respond to customer inquiries via phone, email, live chat, and other communication channels. Provide accurate information regarding products and services while delivering exceptional customer service. Resolve customer complaints efficiently and professionally. Maintain accurate records of customer interactions and follow-up activities. Escalate complex customer issues to the relevant departments when necessary. Ensure customer satisfaction by providing timely and effective solutions. Meet individual and team performance targets and service level agreements (SLAs). Stay updated on company products, services, and policies to provide accurate information. Work collaboratively with internal teams to improve customer experience. Previous experience in customer service, call centre operations, or a similar role will be an added advantage. Excellent verbal and written communication skills in English. Strong interpersonal and customer relationship management skills. Good problem-solving and conflict-resolution abilities. Proficiency in Microsoft Office applications. Ability to multitask and work in a fast-paced environment. Positive attitude with a customer-focused approach. Ability to work independently and as part of a team. Attractive monthly salary of LKR 120,000 – 150,000. Career growth and development opportunities. Professional and supportive working environment. Performance-based rewards and incentives.', 'Colombo, Sri Lanka', '2026-08-06 09:50:18.42855+00', '2026-08-06 09:50:18.42855+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (640, 380, 4, 'Library Assistant', false, 'Preference will be given to candidates possessing a Diploma / Certificate in library and Information Science from a recognized university or Library & Information Management or equivalent qualification. Working Knowledge of the Dewey Decimal Classification (DDC) System. Working knowledge of library management software and digital library systems. Previous experience in a similar capacity will be an added advantage. Ability to handle correspondence independently. Good communication skills in both English and Sinhala. Applicants should reside within close proximity to Colombo City.', 'Colombo 7, Sri Lanka', '2026-08-06 09:51:00.114844+00', '2026-08-06 09:51:00.114844+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (641, 381, 4, 'Digital Marketing Executive', false, 'Manage and grow social media platforms (Facebook, Instagram, Linkedin, TikTok, etc.). Plan and execute digital marketing campaigns. Create engaging content, including graphics, videos, and captions. Manage website content and digital advertisements. Monitor campaign performance and prepare marketing reports. Coordinate with internal teams and external agencies to ensure brand consistency. Qualifications: Diploma or Degree in Marketing, Digital Marketing, or a related field. Minimum 1-2 years of experience in digital marketing. Knowledge of Meta Ads, Google Ads, SEO, and social media management. Experience with Canva, Adobe Creative Suite, or similar design tools is an advantage. Strong communication, creativity, and analytical skills. Ability to work independently and meet deadlines.', 'Ja-Ela, Sri Lanka', '2026-08-06 09:51:00.12104+00', '2026-08-06 09:51:00.12104+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (642, 382, 4, 'Manager - ICT (IFRS 17)', false, 'Lead the implementation of ICT solutions required for compliance with IFRS 17. Design, build, and maintain scalable and efficient data pipelines to support data extraction, transformation, and loading (ETL) processes for IFRS17 implementation. Integrate data from various sources, including relational databases, APIs, and flat files. Implement and oversee data security measures to protect sensitive financial and actuarial data. Qualifications: Masters Degree/Post Graduate Diploma/Degree/Special Degree in Computer Science, Engineering, Physical Science, Mathematics or Statistics / Professional Qualification or Equivalent related to the functional area from a University/Institute approved by the UGC. Minimum of 03 years experience in Assistant Manager Grade. Minimum 8-10 years of experience in Software Development, Management, Data Analytics, managing data warehouse and ETL process. Experience in Power BI / Cognos / Tableau & SAP or any ERP. Experience in BFSI industry. Age should be below 50 years.', 'Colombo 2', '2026-08-06 09:51:00.124996+00', '2026-08-06 09:51:00.124996+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (643, 383, 4, 'Digital Marketing Executive', false, 'We are looking for a creative, passionate, and results-driven Digital Marketing Executive to join our growing team.', 'Kadawata', '2026-08-06 09:51:00.127136+00', '2026-08-06 09:51:00.127136+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (644, 384, 4, 'Stores Executive', false, 'A well-established company based in Borella is looking for a Stores Executive to join our team. Requirements: G.C.E Advanced Level (A/L) qualification, previous experience in stores/inventory management will be an added advantage, good knowledge of Microsoft Excel, good mathematical skills, ability to communicate in English is an advantage, valid motorcycle riding licence, preferably residing close to Borella, age between 35-45 years. Attractive salary offered.', 'Colombo 8, Sri Lanka', '2026-08-06 09:51:00.129194+00', '2026-08-06 09:51:00.129194+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (645, 385, 4, 'IE Executive | Work Study Engineer', false, 'Bachelor''s degree/diploma or similar professional qualifications in Industrial Engineering/Operation Mgt / work-study. Minimum 01-year experience in the Industrial Engineering / Work-study division. Exposure in a factory environment (manufacturing) would be an added advantage. Able to set up Layout. Capability of preparing efficiency reports. Able to calculate lost time, study methods & introduce new methods. Good communication skills in English & Proficiency in Microsoft Office suite (Word, Excel, PowerPoint). The successful candidate will be offered a competitive remuneration package based on qualification & work experience. Additionally, he/she will be provided with free food and accommodation within factory premises.', 'Yatiyanthota, Sri Lanka', '2026-08-06 09:51:00.132024+00', '2026-08-06 09:51:00.132024+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (646, 385, 4, 'Packing Executive', false, 'Passed GCE A/L. Minimum two years of proven working experience in relevant field. Exposure in a factory environment (manufacturing) would be an added advantage. Computer Literacy. Knowledge of ERP system. Organization skills - High attention to detail, strong numerical aptitude, time management, and ability to monitor safety. Communication skills in English. The successful candidate will be offered a competitive remuneration package based on qualifications and work experience. He/she will also be provided with free Meals and free accommodation within the factory premises.', 'Yatiyanthota, Sri Lanka', '2026-08-06 09:51:00.135574+00', '2026-08-06 09:51:00.135574+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (647, 386, 8, 'Front Office Trainee (Intern)', false, 'Front Office Trainee (Intern) position at Water Garden Sigiriya, a luxurious resort located in Sri Lanka''s cultural triangle. Attractive salary with service charge and welfare benefits offered.', 'Sigiriya', '2026-08-06 09:51:00.136836+00', '2026-08-06 09:51:00.136836+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (648, 385, 4, 'HR Executive', false, '', 'Yatiyanthota', '2026-08-06 09:51:00.138442+00', '2026-08-06 09:51:00.138442+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (660, 299, 4, 'Management Service Officer (Limited)', false, 'Limited competitive examination for recruitment to the Grade III of the Provincial Management Service of the Eastern Province Public Service. There are 53 vacancies. Applicants must be officers currently serving in the Eastern Province Public Service. The position is subject to transfer within the province. Salary scale: Rs. 48,470-10x540-11x630-10x1,010-10x1,190-67,82,800/-. The examination consists of a written test and an interview. Written test includes two papers: Language Proficiency (40%) and Management Service Officer Service Challenges (40%). The examination will be held in Trincomalee, Batticaloa, Ampara, and Kalmunai. Application fee is Rs. 1,000/-. Online applications must be submitted between 2026.07.16 and 2026.08.14.', 'Eastern Province, Sri Lanka', '2026-08-06 09:52:07.612478+00', '2026-08-06 09:52:07.612478+00', 53);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (649, 387, 4, 'Administration Coordinator', false, 'To coordinate the administrative and academic activities of Rhino Academy, serve as the primary contact point for trainees, support their daily needs, and facilitate English language development programs. Key Responsibilities: Coordinate internal and external training programs. Manage course schedules, registrations, attendance, and learner records. Liaise with trainers, participants, and departments for smooth program delivery. Prepare training materials, reports, certificates, and evaluations. Conduct English language lessons and support communication skills development. Maintain training databases and administrative documentation. Promote learning initiatives and support continuous improvement. Job Requirements: Degree/Diploma in HR, Education, Business Management, or a related field. 2-3 years'' experience in training coordination, academic administration, or student affairs. Candidates with teaching experience and a strong command of the English language will be given preference. Proficiency in MS Office (Word, Excel, PowerPoint). Experience in maintaining training records and documentation. Professional qualification in Training & Development will be an added advantage. An attractive remuneration package with excellent fringe benefits will be offered to the right candidate.', 'Ekala, Sri Lanka', '2026-08-06 09:51:00.140576+00', '2026-08-06 09:51:00.140576+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (650, 388, 4, 'Digital Marketing Expert', false, 'Plan, create, and manage Google Ads campaigns (Search, Display, YouTube, and Performance Max); Manage Facebook, Instagram, TikTok, LinkedIn, and other social media platforms; Develop and execute digital marketing strategies to generate leads and sales; Monitor campaign performance and optimize ads for better ROI; Create engaging ad copies, captions, and marketing content; Analyze audience behavior, trends, and competitor activities; Manage social media calendars and posting schedules; Track analytics and prepare campaign performance reports; Work closely with the design, content, and development teams; Stay updated with the latest digital marketing trends and platform updates. Requirements: Proven experience in Google Ads and social media marketing; Good understanding of Facebook Ads Manager and Google Ads Manager; Knowledge of SEO, audience targeting, and lead generation strategies; Ability to analyze campaign data and improve performance; Creative thinking and strong communication skills; Basic graphic/content understanding for social media campaigns; Ability to work under deadlines and manage multiple campaigns; Good Sinhala and English communication skills. Benefits: Attractive salary based on experience and skills; Overtime payments available; Opportunity to work with a professional software and digital marketing company; Creative and growth-focused working environment.', 'Pannipitiya, Colombo, Sri Lanka', '2026-08-06 09:51:42.352587+00', '2026-08-06 09:51:42.352587+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (651, 389, 4, 'House Maid', false, 'Responsibilities: Cleaning the house, cooking for the family, other household chores. Qualifications: Must be willing to live in and work full-time. Benefits: Monthly salary of LKR 50,000.', 'Colombo 4, Sri Lanka', '2026-08-06 09:51:42.358594+00', '2026-08-06 09:51:42.358594+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (652, 390, 4, 'Data Entry Operator - Female', false, 'We are a premium Cosmetic & Accessories retail store located in Negombo, seeking for candidates with dynamic, self-driven and committed team players to employ at our showroom. Position: Data Entry / Female. Time: 9.30 AM TO 8.30 PM. Requirements: Aged below 30 years; English is preferred; Education Qualification minimum G.C.E A/L; Basic computer literacy; Experience preferred in similar work would be an added advantage; Be flexible with working hours; Must be able to assist with a sales Team in order to achieve team goals; Based in Negombo is preferred. Send your CV to Email: cosmoline225@gmail.com or WHATSAPP: 076-600 4500.', 'Negombo, Gampaha, Sri Lanka', '2026-08-06 09:51:42.362095+00', '2026-08-06 09:51:42.362095+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (653, 391, 4, 'Room Assistant', false, 'Join our team at Wilpattu Safari Resort, a boutique safari hotel near Wilpattu National Park. We are looking for enthusiastic, hardworking, and experienced individuals. Responsibilities include serving foreign tourists and gaining international hospitality experience. Qualifications: age below 35 years, minimum 1 year experience in a similar position, hotel school qualification or diploma preferred, good English communication skills an advantage, applicants from Anuradhapura, Nochchiyagama, Puttalam, Kurunegala and surrounding areas encouraged. Benefits: attractive salary, monthly service charge, tips, peak season bonus, free accommodation, free meals, uniforms, career development opportunities, friendly working environment.', 'Nochchiyagama, Anuradhapura, Sri Lanka', '2026-08-06 09:51:42.36634+00', '2026-08-06 09:51:42.36634+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (654, 357, 4, 'Heavy Vehicle Driver', false, 'Operate heavy vehicles safely and efficiently. Transport goods, equipment, and materials to designated locations. Perform daily vehicle inspections and report any mechanical issues. Ensure the vehicle is kept clean and well-maintained. Follow assigned delivery schedules and routes. Comply with traffic laws and company safety policies. Assist with loading and unloading materials when required. Maintain accurate delivery and vehicle log records. Requirements: Valid Sri Lankan Heavy Vehicle Driving License. Minimum of 2 years of experience driving heavy vehicles. Good knowledge of Sri Lankan road regulations and routes. Ability to perform basic vehicle maintenance and inspections. Physically fit and willing to work flexible hours when required. Responsible, punctual, and safety-conscious. Good communication and teamwork skills. What We Offer: Attractive salary and benefits. Overtime opportunities. Stable and supportive work environment. Career growth opportunities.', 'Rajagiriya, Colombo, Sri Lanka', '2026-08-06 09:51:42.368835+00', '2026-08-06 09:51:42.368835+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (655, 392, 4, 'Hair Dresser', false, 'Hair Dresser position at Salon Apsara. Qualifications: Minimum 1 year experience in Hair Coloring, good customer service skills, positive attitude and team spirit, interest in beauty and hair styling. Trainees welcome - no experience required, full training provided, school leavers can apply. Benefits: attractive salary and incentives, friendly and professional work environment, opportunities for professional growth, learn latest beauty methods and technologies, immediate recruitment, accommodation provided for female workers only. Female applicants given priority. Location: Kotte.', 'Kotte, Colombo, Sri Lanka', '2026-08-06 09:51:42.370911+00', '2026-08-06 09:51:42.370911+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (656, 393, 4, 'Food Delivery Driver', false, 'Deliver cake to shops, jaela, colombo area. Need to have driving experience of colombo roads.', 'Minuwangoda, Gampaha, Sri Lanka', '2026-08-06 09:51:42.372957+00', '2026-08-06 09:51:42.372957+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (657, 326, 7, 'Press Helper (Male)', false, 'Assist the Press Coordinator in the operation of the assigned Digital/Sheet-fed Press. Primary responsible for setting up the feeder end of the press and preparing/hanging paper digital press and if necessary, plates for sheet-fed machine. Continually pre-load the feeder so when one person is cleaning the output trays at the delivery. Work directly with the press coordinator in planning the next job. Adhere to and follow all safety policies and procedures and good housekeeping practices. Assist press coordinator in routine maintenance. Assist other press operators whenever possible by locating paper and/or loading paper. Minimum Qualifications: Should have passed the O/L examination in six subjects with at least two credit passes in not more than two sittings. At least two years'' experience in a relevant field (i.e. - Operating Binding Machine and Guillotine machine). Age between 21 and 45 years on the closing date of application. Remuneration: Basic Salary Rs. 42,775/- + Cost of Living Allowance (Rs.17,800/-) + EPF (12%) + ETF (3%). Period of Contract: One year.', 'Colombo 03, Sri Lanka', '2026-08-06 09:52:07.604883+00', '2026-08-06 09:52:07.604883+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (658, 297, 4, 'Management Assistant, Assistant Registrar, Sub Warden, Audit Assistant, Driver, Electrician, Works Aide, Chair Professor, Lecturer, Senior Lecturer', false, 'The Buddhist & Pali University of Sri Lanka invites applications from qualified candidates for the following vacancies: Academic positions including Chair Professor, Senior Lecturer, Lecturer (Probationary/Unconfirmed/Temporary) in Buddhist Studies, Pali, Sanskrit, English, Japanese, French, Hindi, and Chinese; Non-academic positions including Assistant Registrar, Sub Warden, Audit Assistant, Management Assistant, Driver, Electrician, and Works Aide. Applications must be submitted by 2026.08.10. Priority will be given to Bhikkhus for academic positions. Salary scales vary by position. Candidates must be able to teach in both Sinhala and English mediums.', 'Sri Lanka', '2026-08-06 09:52:07.610517+00', '2026-08-06 09:52:07.610517+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (791, 345, 4, 'General Production Worker (M/F)', false, 'Male & female production line workers, age 18-45. ~Rs. 25,000/month probation salary, +Rs. 5,000 allowance after 3 months, rising toward Rs. 35,000+ with allowances.', 'Sri Lanka', '2026-08-07 03:42:11.821412+00', '2026-08-07 03:42:11.821412+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (792, 447, 4, 'Accountant', false, 'Accountant position for the Negombo branch; age limit not exceeding 30.', 'Negombo, Sri Lanka', '2026-08-07 03:42:11.823881+00', '2026-08-07 03:42:11.823881+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (661, 315, 4, 'Social Services Officer', false, 'The North Central Provincial Department of Social Services is recruiting for the position of Social Services Officer (Limited) in the field/office service category 2. Applicants must possess a degree in Social Sciences from a recognized university by the University Grants Commission. Professional qualifications include at least 5 years of satisfactory service in the North Central Provincial Public Service. Physical and mental fitness is required to serve in any area within the North Central Province. Age must not be less than 21 years as of the closing date for applications. The examination consists of two papers covering Social Services and Social Welfare, and language skills, mathematical ability, and reasoning. A minimum of 40% marks is required in each subject. The position is permanent with pension benefits. Salary scale: Rs.58,660-10X1,190-11X1,360-15X1,670-110,570 per State Administration Circular No. 10/2025. The examination will be held in Anuradhapura. Applications must be submitted on the prescribed form by 2026.08.07. Examination fee is Rs.720/-.', 'North Central Province, Sri Lanka', '2026-08-06 09:52:07.613355+00', '2026-08-06 09:52:07.613355+00', 3);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (662, 325, 4, 'Senior Investigations Supervisor', false, 'The incumbent will be responsible for conducting detailed investigations on Company related incidents/ acts of misconduct and prosecutions in the relevant Corporate Offices cases at the domestic tribunals. As well as to collect information on matters detrimental to the Company and liaise with law enforcement agencies on Company related matters. Key responsibilities will include: Carrying out investigations into Company related incidents/ acts of misconduct by staff with a view to establish facts and submit reports to Human Resources department. Assisting the Human Resources department, with disciplinary matters and conduct prosecutions at the Domestic Tribunals with a view to establish company''s position. Maintaining and updating all records to have readily available and updated accurate information. Collecting information on matters detrimental to the smooth running of the Company. Conducting surveillance on staff/ passengers/ visitors in vulnerable areas with a view to present/ detect unauthorized acts. Assisting Law enforcement agencies operating within the company or on matters involving SriLankan Airlines. Carrying out WIP security duties, Supporting & contributing towards achieving department/ divisional initiatives & priorities. Requirements: 6 passes at GCE Ordinary Level (O/L s) with 4 credits in one sitting with a credit for English and 2 passes at GCE Advance Level (A/Ls) with 5 years experience in Police in the rank of Inspectorate. OR 6 passes at Ordinary Level (O/L s) with 4 credits in one sitting with a credit for English and 02 passes at GCE Advance Level (A/Ls) with 3 years experience in corporate sector in a relevant discipline with experience in Police in the rank of Inspectorate. The upper age limit is 45 years as at the date of submission of the application. Be a Sri Lankan Citizen. Employment will be offered on fixed term contract.', 'Katunayake, Sri Lanka', '2026-08-06 09:52:07.616379+00', '2026-08-06 09:52:07.616379+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (663, 325, 4, 'Licensed Aircraft Engineer (Line/Base/Cabin/MCC)', false, 'Licensed Aircraft Engineer (LAE) is responsible to perform Base Maintenance checks /Line Maintenance checks on company and customer aircraft in an efficient, timely and cost-effective manner. Ensure that all aspects related to the technical dispatch of Sri Lankan A320 CEO, A320 / A321 NEO, and A330 aircraft comply with the Civil Aviation Authority of Sri Lanka (CAASL) rules and regulations, and per Sri Lankan policies, procedures, and approved quality standards, in keeping with the Company''s Business needs. Key responsibilities include: Carry out aircraft maintenance and servicing activities on Company and other carriers as instructed by the Engineering Management, using approved methods, procedures, tools and spare parts whilst ensuring proper supervision and maintenance activities are performed in accordance with the regulatory requirements, quality and safety standards and active participation in audit preparation activities to ensure minimum audit findings in the section. Determine the work priorities and manage time and manpower efficiently in order to achieve work targets within the specified ground time, to accurately report on potential AOG defects during transits, short turnarounds arising from inspections and the progress on maintenance work thereby enable the Duty Engineer /Check Controller to make informed decisions regarding delays in order to take alternate arrangements. Ensure scheduled turnaround times (TAT) of maintenance inputs are achieved and perform training requirements/assignments to maintain sustainability within the organization. Ensure that the selected tasks on the discretion of the Engineer are assigned amongst Qualifying Mechanics/Inspectors and Technicians/Mechanics in a productive manner, guide them and monitor progress in order to meet the stipulated turnaround times. Requirements: A minimum of 5 years'' experience in aircraft maintenance & 01 year experience as a Licensed Aircraft Engineer. Hold an AML B1.1 or B2 License with active full type approval on one or more aircraft type [A330 (Trent 700) / A320 (V2500; CFM56-5B) / A320 NEO(Leap-1A)]. Should be a Sri Lankan Citizen. NOTE: Grade will be decided based on the number of years of experience as a Licensed Aircraft Engineer and number of approvals. The maximum age limit should be 55 years as of the application submission date. Employment will be offered on fixed term contract.', 'Katunayake, Sri Lanka', '2026-08-06 09:52:07.622533+00', '2026-08-06 09:52:07.622533+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (664, 325, 4, 'Aircraft Technician/Senior Aircraft Technician', false, 'Aircraft Technician is responsible to perform assigned maintenance tasks on aircraft, engines and components as directed by supervising authorization Holder or the monitoring Aircraft Maintenance Executive by adhering to safety and quality standards and Airworthiness authority requirements thereby contributing to company''s operational work requirements and customer airlines requirements as a responsible, productive efficient team member. Job accountabilities: Perform scheduled Aircraft Maintenance tasks, defect rectification, repairs and replacement of parts under the supervision of the Engineer / Approval Holder in charge of the Aircraft, using approved data, correct materials and tooling efficiently in order to maintain airline schedules. Communicate with supervising staff to obtain feedback of the progress of the tasks assigned any findings, observations or anomalies for effective completion of work. Provide necessary guidance to junior staff in order to develop their practical knowledge. Carry out marshaling of aircraft/arrival & departure procedures, towing, aircraft docking according to approved procedures, and thereby ensure safe movement/repositioning of aircraft. Maintain personal toolbox inventory according to regulatory requirements and due care is taken in handling common tools, equipment to prevent damages and ensure that tools are returned in serviceable condition, or any damages/discrepancies are informed prior to return to the Stores. Ensure that all removed components are stored adhering to correct procedures and aircraft spares/consumables are returned as per the laid down procedures in order to prevent audit findings. Maintain good housekeeping standards in the work area and within the aircraft confines thereby aircraft safety is enhanced, and a pleasant work environment is realized. Ensure compliance with Company Safety Manual, Maintenance Organization Expositions (CAASL/EASA) and the Engineering Procedures when performing duties for effective work operations. Responsible to ensure that recurrent training requirements for Maintenance Organization Procedures (MOP), Human Factors, Air Legislation, Fuel Tank Safety (FTS), Electrical Wiring Interconnection System (EWIS) are informed at least three months in advance to the relevant Aircraft Maintenance Executive using the approved Training Request Form. Requirements: 6 passes in G.C.E. O/L (Local or London) including 4 Credit passes (or equivalent), with credits for Mathematics, Science and English in one sitting except the Credit Pass for English which may be obtained in any sitting. AND 02 years or more experience as an Aircraft Technician in pressurized turbine aircraft used in commercial operations and also, should have a minimum of six months active aircraft maintenance experience during the last 24 months. AND Successful completion of an approved course specified below: a) A CAASL IS 147 or EASA Part 147 approved full-time basic aircraft maintenance course in category B1.1 or B2, conducted by a CAASL IS 147 or EASA Part 147 approved Aircraft Maintenance Training Organization (AMTO). OR b) A full-time basic aircraft maintenance course approved by the competent authority of an ICAO member state and conducted by an organization approved by such authority, in categories B1.1 or B2. If the categories defined by the member state are different, such courses may be accepted only after review of the course outline by SriLankan Engineering Quality OR c) A full-time basic and advance aircraft maintenance course (related to the specific trade applied for) conducted by an Aeronautical Military school. Such course is accepted only after review of the course outline by SriLankan Engineering Quality. NOTE: Grade will be decided based on the number of years of experience as an Aircraft Technician and candidates'' performance at the interview. The upper age limit should be 50 years as at the date of submission of the application. Should be a Sri Lankan Citizen. Employment will be offered on fixed term contract.', 'Katunayake, Sri Lanka', '2026-08-06 09:52:07.627949+00', '2026-08-06 09:52:07.627949+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (665, 394, 4, 'Lecturer - Information Technology', false, 'Should possess a Degree, Higher National Diploma or equivalent qualification in IT from a recognized university. Should have excellent time management and presentation/communication skills. Prior teaching experience would be preferable. Ability to manage all activities related to the program and maintain records. Should be able to work during weekends. Competitive salary and benefits for the right candidate.', 'Piliyandala', '2026-08-06 09:52:55.789185+00', '2026-08-06 09:52:55.789185+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (666, 284, 4, 'IT Executive', false, 'We are seeking a proactive IT Executive to join our team. This role is essential for maintaining our technological infrastructure, ensuring secure and seamless operations, and providing high-quality support to our team. Key responsibilities include providing 1st and 2nd level technical support for hardware, software, and network issues while managing IT support tickets; administering user accounts, Active Directory, Google Admin, and local network infrastructure; procuring, deploying, maintaining, and tracking hardware, software licenses, and other technology assets; implementing cybersecurity measures, monitoring system vulnerabilities, and managing data; coordinating with vendors, supporting software upgrades, and assisting with ERP systems and AI initiatives. Qualifications include a Bachelor''s Degree or diploma in Information Technology, Computer Science, Software Engineering or a related field; minimum 2-3 years'' experience in IT support, systems administration, or a similar role; hands-on experience with Windows Server, Active Directory, Microsoft 365, Google Workspace, networking, and IT security; experience with ERP systems will be an added advantage; knowledge of Artificial Intelligence, programming implementation tools and emerging technologies will be an added advantage; excellent troubleshooting, communication, and interpersonal skills; strong analytical and problem-solving skills; excellent communication and customer service skills; ability to work independently and manage multiple priorities; strong attention to detail and commitment to information security; ability to work under pressure and meet deadlines; team player with a proactive attitude. An attractive remuneration package will be offered. Salary is negotiable and commensurate with experience.', 'Wellampitiya, Sri Lanka', '2026-08-06 09:52:55.796769+00', '2026-08-06 09:52:55.796769+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (793, 448, 4, 'Site/Works Supervisor', false, '', 'Sri Lanka', '2026-08-07 03:42:11.825309+00', '2026-08-07 03:42:11.825309+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (794, 348, 4, 'Officer (title illegible) - Grade PS1', false, '1 vacancy, salary Rs. 200,000-220,000/month, age limit 65.', 'Colombo', '2026-08-07 03:42:11.826228+00', '2026-08-07 03:42:11.826228+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (667, 395, 4, 'Junior International Sales Executive', false, 'VS Fresh Pvt Ltd is a Sri Lankan seafood processing and export company, supplying premium fresh and frozen seafood to international markets. The role involves communicating with overseas customers, approaching new customers by Email, LinkedIn, WhatsApp, and Phone, building a career in international sales, marketing, and exports, and gaining exposure to sales, production, quality, logistics, documentation, and shipments. The company offers hands-on training in international seafood sales, marketing, and export business, work with overseas customers, importers, and global buyers, and opportunities to develop communication, negotiation, and relationship-building skills with excellent career growth.', 'Wennappuwa, Sri Lanka', '2026-08-06 09:52:55.800336+00', '2026-08-06 09:52:55.800336+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (668, 284, 4, 'SAP Administrator', false, 'We are seeking a proactive SAP Administrator to join our team. This role is essential for maintaining our high-level SAP ecosystem and ensuring its integrity. While providing technical support remains a core duty, this new role emphasizes system-wide optimization, comprehensive security, and integrating emerging technology like AI to future-proof our operations. Key responsibilities include: System Health Monitoring - conduct daily checks on system logs, optimize background jobs, work processes, and services to maintain peak system health and infrastructure performance. User & Security Lifecycle Management - oversee entire user provisioning, assign granular authorization roles, and lead internal security audits to ensure a bulletproof system. Full-Cycle Change & Transport Management - manage changes across development, quality, and production landscapes. Proactive Infrastructure Coordination - monitor all database and system backups, maintain disk space, and execute critical system patches and kernel updates with zero-downtime planning. Knowledge Maintenance & Technical Support - act as the primary contact for system-related issues, maintain an extensive knowledge base, and escalate complex bugs to SAP support. Qualifications: Bachelor''s degree or Diploma in IT/CS or a related technical field, with emphasis on infrastructure performance optimization. Minimum 3 years'' experience with SAP system administration. 3 years of general IT infrastructure or system administration experience (Helpdesk, Server Admin, or Database Admin). SAP-Specific Experience: Minimum 3 years of hands-on exposure to SAP or other ERP system administration tasks. Experience in programming and AI that can be utilized for programming tasks. An attractive remuneration package will be offered. Salary is negotiable and will commensurate with experience and qualifications.', 'Wellampitiya', '2026-08-06 09:52:55.805818+00', '2026-08-06 09:52:55.805818+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (669, 396, 4, 'Trade Officer - Branches', false, 'Ensure the smooth operation of trade services by delivering quality service and maintaining accurate transactions in compliance with bank policies, procedure manuals, statutory requirements, and KYC regulations. Onboard and acquire new trade finance clients. Scrutinize LC applications and follow up with customers on required corrections. Obtain necessary credit approvals and follow up on pending approvals. Endorse documents and release them to customers. Ensure timely delivery of advices and endorsed import documents to customers. Maintain high customer satisfaction through quality and timely service. Minimize customer complaints and respond promptly to queries. Minimum 4 years of relevant experience. Graduate from a recognized university, or full/part qualification in Banking. Qualification in Trade Finance and Bank Operations from a recognized professional body. Sound knowledge of Local and International Trade Regulations. Strong written and verbal Communication Skills. Excellent Negotiation and Cross-Selling Abilities. Sound understanding of the bank''s operational policies and procedures. The successful candidate will be offered an attractive remuneration package which will commensurate with qualifications and experience.', 'Colombo 1, Sri Lanka', '2026-08-06 09:52:55.808339+00', '2026-08-06 09:52:55.808339+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (670, 397, 4, 'Chartered Accountant', false, 'We are seeking a qualified and experienced Chartered Accountant to manage financial reporting, ensure statutory compliance, and provide strategic financial guidance. Responsibilities: Prepare and review financial statements in accordance with applicable accounting standards; Ensure compliance with statutory, tax, and regulatory requirements; Manage audits and coordinate with internal and external auditors; Prepare and submit tax returns and other statutory filings; Provide financial analysis, budgeting, and forecasting; Maintain accurate accounting records and internal controls; Advise management on financial planning and risk management; Sign Articles and other statutory documents in accordance with professional and legal requirements; Perform any other finance and accounting duties assigned by management. Requirements: Qualified Chartered Accountant (CA) with membership in the relevant professional accounting body; Valid practicing certificate (if required by law); Authorized and eligible to sign Articles; Minimum 3-5 years of post-qualification experience (preferred); Strong knowledge of accounting standards, taxation, and financial reporting; Excellent analytical, communication, and problem-solving skills; Proficiency in accounting software and Microsoft Office applications.', 'Colombo 2, Sri Lanka', '2026-08-06 09:52:55.810695+00', '2026-08-06 09:52:55.810695+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (671, 284, 4, 'Documentation Assistant (Male)', false, 'A well-established Shipping Company, with over 35 years of excellence in the shipping and logistics industry, is looking for a motivated, energetic and dedicated individual to join our team as a Documentation Assistant at our Container Depot in Sapugaskanda. Requirements: Male applicant, below 35 years of age; G.C.E. A/L or G.C.E. O/L qualification; Basic proficiency in English and computer applications (Microsoft Office); Good interpersonal and communication skills with the ability to work as part of a team; Willingness to work beyond normal office hours when required. Preference will be given to candidates who have prior experience in documentation or related office work, possess basic knowledge of accounting and invoicing, reside in or around the Sapugaskanda area. School leavers are also encouraged to apply. Salary: An attractive and negotiable remuneration package will be offered, commensurate with qualifications and experience.', 'Sapugaskanda', '2026-08-06 09:52:55.812372+00', '2026-08-06 09:52:55.812372+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (672, 398, 4, 'Executive - Warehouse Operations', false, 'Efficient inventory management, managing operations for receipts, storage, dispatch, record-keeping, ensuring proper procedures for items and sea-products, stock checks, form processing, and compliance with rules and regulations. Key Responsibilities: Monitor all consumables for identified needs and/or consumables. Collaborate with procurement and storage. Using AX system of inventory. Verifies incoming items and system alert incoming items. Reporting damages, FIFO and 5S adherence to damages of items stock and stores. Generate GRNs. Regular audits for inventory, including auditing for documents products. Inventory replenishment and Generate GRNs (manual and Excel). Process authorized MRNs. Document handover to finance and associated paperwork documents. Qualifications: Diploma/Certificate in SCM, Stores Management or Logistics. Minimum 2 years of experience. Inventory control knowledge. Computer literacy (Excel, ERP). Good communication and multicultural keywords. Ability to work under pressure.', 'Mirigama', '2026-08-06 09:52:55.814954+00', '2026-08-06 09:52:55.814954+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (795, 348, 4, 'Deputy Director (Engineering/Operations) - Grade PS2', false, 'Requires professional engineering qualification + 13 years'' post-qualification experience. Salary Rs. 185,000-205,000/month, age limit 65.', 'Colombo', '2026-08-07 03:42:11.82954+00', '2026-08-07 03:42:11.82954+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (673, 397, 4, 'Chartered Accountant', false, 'We are seeking a qualified and experienced Chartered Accountant to manage financial reporting, ensure statutory compliance, and provide strategic financial guidance. Responsibilities: Prepare and review financial statements in accordance with applicable accounting standards; Ensure compliance with statutory, tax, and regulatory requirements; Manage audits and coordinate with internal and external auditors; Prepare and submit tax returns and other statutory filings; Provide financial analysis, budgeting, and forecasting; Maintain accurate accounting records and internal controls; Advise management on financial planning and risk management; Sign Articles and other statutory documents in accordance with professional and legal requirements; Perform any other finance and accounting duties assigned by management. Requirements: Qualified Chartered Accountant (CA) with membership in the relevant professional accounting body; Valid practicing certificate (if required by law); Authorized and eligible to sign Articles; Minimum 3-5 years of post-qualification experience (preferred); Strong knowledge of accounting standards, taxation, and financial reporting; Excellent analytical, communication, and problem-solving skills; Proficiency in accounting software and Microsoft Office applications.', 'Colombo 2, Sri Lanka', '2026-08-06 09:52:55.817029+00', '2026-08-06 09:52:55.817029+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (674, 370, 4, 'Senior Student Counsellor / Student Counsellor - International Placements', false, 'Counsel students on study abroad options, program selection, application procedures, and visa requirements. Conduct one-on-one and group sessions to assess academic goals and placement suitability. Liaise with overseas universities, embassies, and relevant stakeholders to facilitate admissions. Track applications, maintain accurate records, and provide timely updates to students and parents. Support promotional activities such as university fairs, information sessions, and marketing initiatives. Bachelor’s degree or an equivalent qualification from a recognized Institute/University. Minimum 2–3 years’ experience in student counselling or international education. In-depth knowledge of global admissions processes, visa regulations, and scholarships. Excellent communication, interpersonal, and presentation skills. Organized, detail-oriented, and able to manage multiple student applications effectively.', 'Kurunegala, Sri Lanka', '2026-08-07 02:41:34.057546+00', '2026-08-07 02:41:34.057546+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (675, 255, 4, 'Aesthetician / Beauty Therapist', false, 'Perform a range of professional beauty treatments including facials, waxing, threading, and other aesthetic services. Conduct skin consultations and analyses to recommend suitable treatments and products. Provide aftercare advice to help clients maintain healthy skin. Maintain the highest standards of hygiene and sanitation by sterilizing equipment and preparing treatment rooms. Stay informed about the latest skincare technologies and beauty products. Build long-term relationships with clients and understand their needs. Efficiently manage appointments and contribute to a luxurious salon environment. Collaborate with hairstylists, nail technicians, and other team members to enhance customer experience. Relevant beauty therapy qualifications and practical experience preferred. Previous experience in a salon, spa, or aesthetic clinic is an advantage. Excellent customer service and communication skills. Ability to work collaboratively in a team environment. Attractive monthly salary with performance-based incentives. Continuous professional training and career development opportunities. Luxury working environment in a premium salon.', 'Colombo 07, Sri Lanka', '2026-08-07 02:41:34.06135+00', '2026-08-07 02:41:34.06135+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (676, 370, 4, 'Assistant Lecturer Cum Assistant Programme Coordinator - Nursing', false, 'Deliver lectures, tutorials, and practical sessions for Nursing programmes. Supervise students during clinical placements and assess their clinical competencies. Prepare lesson plans, assessments, examination papers, and maintain academic records. Coordinate the academic programme, including timetables, examinations, and student progress. Provide academic guidance and mentorship to students throughout their learning journey. Support curriculum development, quality assurance initiatives, and programme administration. Liaise with academic and administrative teams to ensure smooth programme delivery. The Person: Bachelor of Science (Hons) in Nursing Studies or HND in Nursing. Minimum one (1) year of academic/lecturing experience in Nursing at a recognized higher education institution. Experience in clinical supervision and student assessments. A Master''s Degree in Nursing or a related field will be an added advantage. Excellent communication, presentation, and interpersonal skills. Strong organizational, planning, and coordination abilities. Passionate about teaching, mentoring, and developing future nursing professionals. Proficient in Microsoft Office applications and capable of working collaboratively in a team environment.', 'Kandy, Sri Lanka', '2026-08-07 02:41:34.065869+00', '2026-08-07 02:41:34.065869+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (677, 399, 4, 'අභ්‍යයන්තර ආරක්ෂක නියාමක', false, 'තනතුර: අභ්‍යයන්තර ආරක්ෂක නිලධාරී (Security Guard). සුදුසුකම්: වයස 57ට අඩු, ආරක්ෂක ක්ෂේත්‍රයේ අවම වසර 02ක පලපුරුද්ද, රාජ්‍යය ආරක්ෂක අංශයක සේවය කර පලපුරුද්ද තිබීම අමතර සුදුසුකමක් වේ. රැකියා ස්ථානය - සිලෝන් ෂිපිං ලයින්ස්, අවිස්සාවේල්ල පාර, ඔරුගොඩවත්ත. ආකර්ෂණීය වැටුප් සහ දීමනා, EPF/ETF, වෛද්‍යාධාර/රක්ෂණ පහසුකම්, ප්‍රසාද දීමනා, වාර්ෂික නිවාඩු හිමිවේ.', 'Colombo 9, Sri Lanka', '2026-08-07 03:13:09.697892+00', '2026-08-07 03:13:09.697892+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (678, 400, 4, 'Accounts Assistant Female', false, 'Accounts Assistant Female role. Salary Rs 75,000 - 80,000 per month. Required education: Advanced Level. No prior work experience required. Opportunity to work abroad (Japan, New Zealand, South Korea, Australia, Canada, Italy, Germany, America, England) after one year of work in Sri Lanka. Interviews held daily until 30 vacancies are filled. Branches available in Nawaala, Nugegoda, Maharagama, Kottawa, Homagama, Boralesgamuwa. Contact via WhatsApp at 0776962219 for details.', 'Maharagama, Colombo', '2026-08-07 03:13:09.705566+00', '2026-08-07 03:13:09.705566+00', 30);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (679, 401, 7, 'Clinical Nurse', false, 'Position: Clinical Nurse - To be worked in OT | ICU | Emergency | Medical & Surgical. Entry Requirements: Age Limit Below 45, BSN + 3 Years Experience in Similar Capacity. Salary: OMR 620/-. Contact via Call/WhatsApp 076 922 2323 / 077 732 5421 or email alcomlk@gmail.com.', 'Nugegoda, Colombo', '2026-08-07 03:13:09.707536+00', '2026-08-07 03:13:09.707536+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (695, 413, 4, 'Office Assistant', false, 'We are seeking a motivated and detail-oriented Office Assistant to support day-to-day administrative operations and maintain efficient document management systems. Qualifications: Sat for the G.C.E. Ordinary Level Examination; Age below 25 years; Previous experience in a similar capacity will be an added advantage; Ability to work effectively in a team environment; Honest, responsible, and well organised. What we offer: Attractive remuneration package; Learning and career development opportunities; Exposure to Sri Lanka''s leading financial services sector.', 'Colombo 3, Sri Lanka', '2026-08-07 03:14:12.552255+00', '2026-08-07 03:14:12.552255+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (680, 402, 7, 'Junior Firefighter', false, 'Become a part of the Airport Rescue & Firefighting (ARFF) team and play a vital role in protecting lives, aircraft, and airport operations. Salary: USD 700 - 1,000 per month. Preference: Sri Lankan Nationals. Location: Madivaru Airport. Minimum Qualifications: Completed GCE Ordinary Level (O/L) with at least 3 passes. ARFF Firefighter Basic Training or equivalent firefighting qualification is an added advantage. Additional Requirements: Age between 18-30 years, medically fit and pass Aeromedical Examination, ability to complete ARFF Physical Fitness Tests (IPPT & PAT), valid driving license is an added advantage, willing to work shift duties including night shifts, weekends, and public holidays, good communication skills and teamwork. Key Responsibilities: Respond to aircraft accidents, fires, incidents, and other airport emergencies; provide specialized ARFF services including fuel spill washdowns, fire escorts, hot work standby, refuelling standby, hazardous cargo standby; participate in emergency drills and physical fitness training; maintain cleanliness and serviceability of fire station and equipment; inspect and report fire safety equipment; check ARFF vehicle equipment; perform watch room duties; comply with ARFF SOPs and airport regulations; perform other duties assigned by Fire In Charge or Airport Management.', 'Homagama, Colombo', '2026-08-07 03:13:09.710049+00', '2026-08-07 03:13:09.710049+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (681, 203, 4, 'ඇසුරුම් සේවක / සේවිකා ( ස්ථීර රැකියා ) - මාතර', false, 'ඇසුරුම් සේවක / සේවිකා ( ස්ථීර රැකියා ) - රත්මලාන, මොරටුව. රත්මලාන, මොරටුව පිහිටි ප්‍රධාන පෙළේ නිෂ්පාදන සමාගම් සදහා ඇති පුරප්පාඩු සදහා නවක සේවක මහත්ම මහත්මීන් බදවා ගනු ලැබේ. වයස අවු 18 - 40, උප්පැන්න සහතිකය, ග්‍රාමසේවක සහතිකය (මාස 6ට අඩු), චරිත සහතිකය, O/L හෝ A/L result sheet එක හෝ පාසල් අස්විමේ සහතිකය, ID Card එක ( copy 2ක් සමග), මුද්දර ප්‍රමාණයේ photos 2ක්, ලංකා බැංකුවේ තමාගේ බැංකු ගිණුමේ copy එකක්, කාඩ්බෝඩ් ෆයිල් කවරයක්, නිල් පෑනක්. අතිකාල සේවා මුර වල යෙදීමේදී ආහාර නොමිලේ සැපයේ. වැටුප අතිකාල දීමනා සමග 75,000.00 සිට ඉහලට. නවාතැන් පහසුකම්, සොඛ්‍ය පහසුකම්, ආරක්ෂාව, ප්‍රවාහන පහසුකම් සැපයේ.', 'Matara City, Matara, Sri Lanka', '2026-08-07 03:13:09.712159+00', '2026-08-07 03:13:09.712159+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (682, 403, 4, 'Branch Manager', false, 'Handle all legal and regulatory matters related to the branch. Maintain and update all operational books and statutory records accurately. High level of honesty, integrity and confidentiality. Excellent customer service skills.', 'Colombo 3, Sri Lanka', '2026-08-07 03:13:09.71348+00', '2026-08-07 03:13:09.71348+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (683, 404, 4, 'Cashier', false, 'Age between 20 to 40. Free Food. Free Accommodation. Salary 45000-50000.', 'Boralesgamuwa, Colombo, Sri Lanka', '2026-08-07 03:13:09.714741+00', '2026-08-07 03:13:09.714741+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (684, 203, 4, 'ඇසුරුම් සේවක / සේවිකා ( ස්ථීර රැකියා ) - මහියංගනය', false, 'ඇසුරුම් සේවක / සේවිකා ( ස්ථීර රැකියා ) - රත්මලාන, මොරටුව. ඔබත් රැකියා විරහිත තරුණයෙක්, තරුණියක් නම් එන්න අප හා එක්වන්න. රත්මලාන, මොරටුව පිහිටි ප්‍රධාන පේළේ නිෂ්පාදන සමාගම් සදහා ඇති පුරප්පාඩු සදහා නවක සේවක මහත්ම මහත්මීන් බදවා ගනු ලැබේ. වයස අවු 18 - 40, උප්පැන්න සහතිකය, ග්‍රාමසේවක සහතිකය (මාස 6ට අඩු), චරිත සහතිකය, O/L හෝ A/L result sheet එක හෝ පාසල් අස්විමේ සහතිකය, ID Card එක ( copy 2ක් සමග), මුද්දර ප්‍රමාණයේ photos 2ක්, ලංකා බැංකුවේ තමාගේ බැංකු ගිණුමේ copy එකක්, කාඩ්බෝඩ් ෆයිල් කවරයක්, නිල් පෑනක්. ඉහත සියළු සහතික වල පිටපත් 1 බැගින් සූදානම් කරගන්න. අතිකාල සේවා මුර වල යෙදීමේදී ආහාර නොමිලේ සැපයේ. වැටුප අතිකාල දීමනා සමග 75,000.00 සිට ඉහලට. නවාතැන් පහසුකම්, සොඛ්‍ය පහසුකම්, ආරක්ෂාව, ප්‍රවාහන පහසුකම් සැපයේ.', 'Mahiyanganaya, Badulla, Sri Lanka', '2026-08-07 03:13:09.715336+00', '2026-08-07 03:13:09.715336+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (685, 405, 4, 'Branch Manager', false, 'Permanent non permanent position available. WE ARE HIRING. PERMANENT POSITIONS: Attractive Income, Career Growth Opportunities, Training & Support, Long-Term Career Development. NON-PERMANENT POSITIONS: Flexible Working Hours, Additional Income Opportunity, Training & Support, Suitable for Male & Female Candidates. Income: Rs. 75,000 – 125,000+. Working Hours: 05 – 06 Hours Per Day. Location: Jaffna Town. Male & Female Can Apply. REQUIREMENTS: Marketing Experience preferred, Good Communication Skills, Hardworking & Self-Motivated, Willing To Achieve Targets.', 'Jaffna City, Jaffna, Sri Lanka', '2026-08-07 03:13:09.716214+00', '2026-08-07 03:13:09.716214+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (686, 406, 4, 'Warehouse Assistant', false, 'Responsibilities: Storing and receiving goods, assisting with order picking/packing, loading/unloading, supporting warehouse operations. Qualifications: Male applicants, GCE O/L, responsible, able to work well in a team, willing to learn and grow professionally. Benefits: Attractive salary (basic + incentives + attendance allowance + OT), EPF/ETF membership, insurance, advance money, free meals, stable and professional work environment, opportunity to gain experience in logistics, build knowledge/skills/field experience for foreign employment.', 'Katunayake, Gampaha, Sri Lanka', '2026-08-07 03:13:09.71801+00', '2026-08-07 03:13:09.71801+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (687, 407, 4, '', false, 'Sarasa Hotel, located in the Colombo - Kandy Main Road, Kelaniya, has been running for over 30 years of successful operation. We are looking for people who can successfully drive sales. Vacancies include Bar Supervisor, Barman, Bar Waiter, Housekeeping Supervisor, Room Boy, and General Helper. Attractive benefits and friendly environment. Be part of our success story.', 'Kelaniya', '2026-08-07 03:14:12.523332+00', '2026-08-07 03:14:12.523332+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (717, 422, 7, 'Security Guard - Dubai', false, 'Urgent Vacancies in Dubai. Position: Security Guard. Age Limit: 25 - 40. Contact us for more details. Email below documents to alhidayah77@gmail.com: 1. Updated CV 2. Passport Copy 3. Photographs. If interested, Apply Soon. For More information, Visit us. Al Hidaya Travels No.316 A, 2nd Floor, Super Market Complex Mount Lavinia.', 'Colombo 5, Sri Lanka', '2026-08-07 03:15:03.736904+00', '2026-08-07 03:15:03.736904+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (796, 348, 4, 'Program Coordinator - Grade PS3', false, 'Requires relevant qualifications + 10 years'' experience in program coordination. Salary Rs. 180,000-195,000/month, age limit 65.', 'Colombo', '2026-08-07 03:42:22.472974+00', '2026-08-07 03:42:22.472974+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (688, 408, 4, 'Factory Manager -Matale (FMCG, Food & Beverages)', false, 'Operational Management: Oversee the daily operations of the manufacturing plant, ensuring all processes run smoothly and efficiently. Machinery Oversight: Manage and maintain equipment including water treatment plants, wood boilers, tower dryers, and other spice processing machinery. Quality Assurance: Ensure that all products meet the highest quality standards and comply with industry regulations. Team Leadership: Lead and mentor a team of production staff, fostering a culture of continuous improvement and excellence. Process Optimization: Identify areas for process improvement and implement strategies to enhance productivity and reduce costs. Warehousing: Ensure that proper record-keeping, reporting and checks are implemented for RM, WIP and FG, while ensuring safe and secure transfer of goods within company premises. Health & Safety Compliance: Ensure all operations adhere to health and safety regulations, maintaining a safe working environment. Qualifications: Bachelor’s degree in Chemical Engineering, Process Engineering, or a related field. Two years of experience in a similar capacity and five years of experience in a manufacturing company. Strong leadership and team management skills. Excellent problem-solving abilities and attention to detail. Knowledge of industry regulations and quality standards. Living within traveling distance of Palapathwala, Matale or willing to relocate. Preferred Experience: Experience in the food processing, pharmaceutical, or similar industries is highly desirable. Familiarity with essential oils and oleoresin production is a plus but not mandatory. Experience in a production environment adhering to ISO 22000 or FSSC 22000 standards.', 'Matale, Sri Lanka', '2026-08-07 03:14:12.529091+00', '2026-08-07 03:14:12.529091+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (689, 409, 4, 'HR & Admin Executive', false, 'Oversee the full recruitment process and employee life cycle (onboarding to exit). Maintain employee records, including personal files, EPF, and ETF. Prepare monthly payroll and statutory contributions (EPF/ETF). Provide staff counseling and intervene when needed for smooth operations. Supervise and manage all staff-related matters, including attendance and leave. Issue appointment letters, contracts, and other HR documents. Support routine HR functions and coordinate with the operations team. Manage labour-related matters and ensure compliance with labour laws. Requirements: Fully or partially qualified in HR or equivalent from a recognized institute/university (retired personnel with employee management experience may also apply). A minimum of 3 years’ experience in similar capacity. Good communication skills in both English and Sinhala. Possess good IT literacy. Excellent PR, negotiation, and interpersonal skills; ability to work independently.', 'Colombo 5, Sri Lanka', '2026-08-07 03:14:12.53377+00', '2026-08-07 03:14:12.53377+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (690, 410, 4, 'Finance Executive', false, '', 'Nugegoda', '2026-08-07 03:14:12.535642+00', '2026-08-07 03:14:12.535642+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (691, 411, 4, 'Receptionist', false, 'Tax-free salary (shift basis) paid in USD. Comprehensive medical benefits. Excellent communication skills in English. Pleasant appearance with strong communication and interpersonal skills. Freshers are encouraged to apply. Prior experience would be an added advantage. Fast career growth opportunities. Team-building for strong workplace relationships.', 'Colombo 2', '2026-08-07 03:14:12.536888+00', '2026-08-07 03:14:12.536888+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (692, 411, 4, 'Executive - Human Resources', false, 'Support day-to-day HR Operations including employee relations and HR documentation. Prepare presentations and HR-related reports as required. Assist in maintaining HR records, reports and databases. Proficiency in MS Office packages. Excellent presentation and communication skills. Ability to multitask, prioritize workloads and work efficiently under pressure. Attention to detail and strong organizational skills. Benefits include comprehensive medical benefits, year-end bonus, tax-free salary paid in USD, fast career growth opportunities, work with a multicultural team, social events & outings.', 'Colombo 2', '2026-08-07 03:14:12.540495+00', '2026-08-07 03:14:12.540495+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (693, 412, 4, 'Junior Mechanical Engineer', false, 'We are seeking 3 motivated and detail-oriented Junior Mechanical Engineer to join our engineering team. The ideal candidate will support the design, development, testing, and maintenance of mechanical systems, enclosures and components. This role is well-suited for recent graduates or early-career professionals looking to build hands-on engineering experience in a collaborative environment. Key Responsibilities: Assist in designing mechanical enclosures, components, assemblies, and systems using CAD software. Prepare technical drawings, specifications, and engineering documentation. Support product development, prototyping, and testing activities. Conduct engineering calculations and performance analysis. Collaborate with senior engineers, production teams, and quality departments. Participate in troubleshooting mechanical issues and proposing solutions. Ensure designs comply with safety, quality, and industry standards. Assist with project planning, reporting, and progress tracking. Support continuous improvement initiatives in manufacturing and engineering processes. Required Qualifications: Degree in Mechanical Engineering or a related field. 0-2 years of experience in mechanical engineering projects, internships, or product development environments. Basic understanding of mechanical systems, materials, manufacturing processes, and product assembly techniques. Familiarity with CAD software such as AutoCAD, Autodesk Inventor, SolidWorks for mechanical component and assembly design. Understanding of engineering drawings, tolerancing, and GD&T principles. Exposure to mechanical integration of electronic assemblies and structural components is an advantage. Basic knowledge of heat dissipation methods, airflow concepts, and thermal considerations in product design is preferred. Strong analytical, troubleshooting, and problem-solving skills. Good communication, documentation, and teamwork abilities. Preferred Qualifications: Internship or project experience. Knowledge of simulation or analysis tools (ANSYS, MATLAB, etc.). Exposure to quality standards and maintenance practices. Ability to work in a fast-paced environment and manage multiple tasks.', 'Colombo 2', '2026-08-07 03:14:12.546275+00', '2026-08-07 03:14:12.546275+00', 3);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (694, 412, 4, 'Junior Embedded Software Engineer (Security-Focused)', false, 'Develop and maintain embedded software for microcontroller-based systems. Assist with firmware debugging, testing, and validation. Support implementation of secure boot, authentication, encryption, or secure communications features. Participate in code reviews and software quality improvement activities. Collaborate with hardware and systems engineering teams. Prepare technical documentation and test reports. Contribute to cybersecurity and secure development best practices. Requirements: Bachelor''s degree (or final-year student) in Computer Engineering, Electronics Engineering, Software Engineering, or a related field. Basic knowledge of embedded programming in C/C++. Familiar with communication protocols such as UART, SPI, I2C, Ethernet. Familiarity with microcontrollers and embedded systems concepts. Understanding of debugging tools and development environments. Interest in cybersecurity, secure systems, or embedded security. Familiarity with Linux based environments is an advantage. Strong analytical and problem-solving skills. Good communication and teamwork abilities. Nice to Have: Experience with RTOS. Exposure to cryptography or secure communication protocols. Knowledge of ARM-based architectures. Experience with Git or other version control systems. Personal or academic embedded systems projects. What We Offer: Mentorship from experienced embedded and security engineers. Exposure to real-world security-focused engineering projects. Opportunities for technical growth and certifications. Collaborative engineering environment. Competitive salary and benefits package.', 'Colombo 02, Sri Lanka', '2026-08-07 03:14:12.550348+00', '2026-08-07 03:14:12.550348+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (718, 14, 4, 'Commi - Hot Kitchen', false, 'Urgently Hiring kitchen staffs for a Restaurant in Sigiriya. Please send us your CV for following numbers. +94 77 335 7478 +94 77 429 7478. Accommodation / Meals Free.', 'Sigiriya, Matale, Sri Lanka', '2026-08-07 03:15:03.751014+00', '2026-08-07 03:15:03.751014+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (696, 284, 4, 'Manager | Assistant Manager - Sales, Marketing & Shipping', false, 'Drive international sales growth by identifying, acquiring, and managing foreign seafood buyers and distributors. Analyze global seafood market trends, competitor activities, and pricing strategies to maximize revenue. Manage client relationships and handle negotiations, contracts, and export orders from placement to fulfillment. Represent the company at international trade fairs, exhibitions, and industry networking events. Oversee end-to-end export documentation, including Bills of Lading (B/L), Health Certificates, Certificates of Origin (COO), and customs clearance files. Coordinate with cold storage operations, freight forwarders, shipping lines, and transport providers to ensure seamless cold-chain logistics. Ensure strict compliance with international import/export regulations, food safety standards, and local export/BOI guidelines. Optimize freight costs and streamline shipping procedures to improve dispatch efficiency and reduce lead times. Candidate Profile: Minimum 5 years of hands-on experience in export sales, international marketing, and shipping operations (experience in the seafood, perishable, or food manufacturing sector is highly preferred). A Bachelor''s degree in Business Administration, Marketing, Supply Chain/Logistics, or a professional qualification (CIM, SLIM, CILT). Deep understanding of international trade terms (Incoterms), seafood shipping protocols, cold chain logistics, and export documentation requirements. Strong negotiation, analytical, and problem-solving skills with fluent written and verbal English communication. Ability to manage cross-functional workflows between processing teams, logistics, and international clients efficiently. What We Offer: An attractive and competitive remuneration package commensurate with qualifications and experience. Performance-driven incentives. Opportunities to travel and engage with global international markets. A supportive and growth-oriented corporate environment.', 'Dankotuwa', '2026-08-07 03:14:12.554166+00', '2026-08-07 03:14:12.554166+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (697, 414, 4, 'Driver', false, 'Driver (Grade III) - Requires GCE O/L with 2 credits and 6 subjects in two sittings, heavy vehicle driving license with 3 years experience, age 18-45, Sri Lankan citizen, physically and mentally fit, good character. Salary: Rs. 48,005 - 16x490 - 55,845 (monthly). Tractor Operator (Grade III) - Requires GCE O/L with 2 credits and 6 subjects in two sittings, NVQ level 2 or 3 in relevant field, 1 year experience, age 18-45, Sri Lankan citizen, physically and mentally fit, good character. Salary: Rs. 44,575 - 16x490 - 52,415 (monthly). Applications to be sent by registered post to the Registrar, University of Moratuwa by 2026.08.21.', 'Moratuwa, Sri Lanka', '2026-08-07 03:14:34.646031+00', '2026-08-07 03:14:34.646031+00', 2);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (698, 415, 4, 'Assistant Registrar', false, 'Applications are invited from suitably qualified citizens of Sri Lanka to serve at the University of Vocational Technology for the post of Assistant Registrar (Establishment Division). Qualifications: External: (i) A Degree with First or Second Class of a recognized University / Higher Educational Institute. OR (ii) A degree of a recognized University with a Postgraduate Degree /Postgraduate Diploma in Administration or Management of a recognized University/Higher Educational Institute. Internal: (i) A graduate of a recognized University / Higher Educational Institution who is a confirmed employee of the University. OR Employee who has completed a minimum of five (5) years of satisfactory service in the relevant field in a Grade 11 of the Management Assistant non technological (U-MN-I) or technological (U- MT-I) category. Nature of Appointment: Permanent with entitlement to Employees’ Provident Fund and Employees’ Trust Fund. Age Limit: Age should be not less than 22 years and not more than 45 years. The upper age limit will not apply to internal candidates. Salary Scales: Salaries will be paid as per the Provisions of Management Services Circular No. 06/2025 dated 25/03/2025. Salary Code: U-EX 1. Selection Procedure: By a Written Competitive Examination and/ or Structured Interview. Every applicant should be a citizen of Sri Lanka, physically and mentally fit, and of excellent moral character.', 'Ratmalana, Sri Lanka', '2026-08-07 03:14:34.648263+00', '2026-08-07 03:14:34.648263+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (699, 416, 4, 'Nursing Assistant', false, 'Qualifications: 1. Passed GCE Ordinary Level examination with six (06) subjects in not more than two sittings. 2. Completed Nursing Assistant course (NVQ 03 or 04) conducted by NAITA, or completed CAD Nursing Assistant course conducted by a TVEC registered institute, or completed Nursing Assistant course from a nursing training institute registered under the Sri Lanka Medical Council with 5 years of experience. 3. At least six (06) months of experience in health services. Additional qualifications: Passed Mathematics, Science, and English in GCE O/L. Experience in patient care and pharmacy services is considered a special qualification. IT and computer literacy skills. Age limit: 18 to 40 years. Salary: Rs. 250.00 per hour. May work up to 300 hours per month depending on service requirements.', 'Sri Lanka', '2026-08-07 03:14:34.653496+00', '2026-08-07 03:14:34.653496+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (700, 417, 4, 'Management Assistant', false, 'Management Assistant (Grade III) and Technical Officer (Grade II ''B'' Division) positions available at the University of Sri Jayewardenepura. Applications are invited for these vacancies. Please visit https://allergy.sjp.ac.lk/vacancies/ for more details. Applications should be submitted to the Deputy Registrar, Department of Immunology and Molecular Medicine, University of Sri Jayewardenepura, Gangodawila, Nugegoda by 2026.07.17.', 'Sri Lanka', '2026-08-07 03:14:34.654655+00', '2026-08-07 03:14:34.654655+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (701, 296, 4, 'Management Assistant', false, 'The Management Assistant position is under the Integrated Rural Development and Climate Resilience Project (IRDCRP), funded by the Government of Sri Lanka and the World Bank, implemented under the Ministry of Agriculture, Livestock, Lands & Irrigation. Responsibilities include providing administrative and management support to the Project Management Unit. Qualifications: GCE O/L with credit passes in four subjects including language and mathematics, and GCE A/L with passes in three subjects; age between 18-45; computer literacy; experience in similar positions; ability to type in Sinhala, Tamil, and English; experience working with foreign-funded projects; knowledge of English and government rules and regulations. Salary: Rs. 46,010.00 + 50% = Rs. 69,015.00 per month.', 'Sri Lanka', '2026-08-07 03:14:34.655829+00', '2026-08-07 03:14:34.655829+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (702, 418, 4, 'Security Officer', false, 'Applications are invited from Sri Lankan citizens with good health and excellent character for the post of Security Officer (Vacancies - 03) in the Office of the Secretary General of Parliament. Salary: Rs. 47,240-9x540/10x590/3x680- Rs. 60,040/- (with all allowances, the minimum monthly salary is approximately Rs. 87,000.00). Qualifications: Passed G.C.E. (O/L) examination with six subjects in two sittings including Sinhala or Tamil language, Mathematics and English; OR a member of the Sri Lanka Army (regular) holding the rank of Sergeant or above with not less than 10 years of commendable service; OR a member of the Sri Lanka Police holding the rank of Sergeant or above with not less than 10 years of commendable service. Age: Not less than 30 and not more than 50 years as of the closing date. Selection: Written examination and interview. The position is permanent and pensionable. Selected candidates will be on probation for 3 years. Applications must be submitted according to the prescribed application form and sent by registered post to ''The Secretary General of Parliament, Parliament of Sri Lanka, Sri Jayawardenepura Kotte'' on or before 2026.08.17.', 'Sri Jayawardenepura Kotte, Sri Lanka', '2026-08-07 03:14:34.65681+00', '2026-08-07 03:14:34.65681+00', 3);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (719, 423, 4, 'Photographer', false, 'Join our professional team at Timothy Studio as a Photographer / Editor! We are looking for someone who has knowledge and experience in photography, has a good understanding of camera equipment and lighting, is creative and eager to try new things. Also requires knowledge and experience in photography and photo editing (Photoshop).', 'Kadawatha, Gampaha, Sri Lanka', '2026-08-07 03:15:03.762534+00', '2026-08-07 03:15:03.762534+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (703, 419, 4, 'Statistician', false, 'Open competitive examination for recruitment to the Executive Service Grade III (Statistician post) in the Department of Census & Statistics. The examination will be held in October 2026 in Colombo. Applications must be submitted online via www.doenets.lk under ''Our Service'' - ''Online Applications — Recruitment Exams/E.B. Exams''. Application window opens 2026.07.13 at 9:00 AM and closes 2026.08.10 at 9:00 AM. Salary scale: SL 1-2025, Rs.82,150-1022,400-85,2,940-17X3,900- Rs.195,970/- (monthly). Qualifications: A degree with at least one of the following as a main subject: Statistics, Mathematics, Economics, Sociology, Demography, Computer Science, Information Technology, Geography, Social Science, or Criminology. Age limit: 18-35 years (born between 1991.08.10 and 2005.08.10). Must be a citizen of Sri Lanka. Examination fee: Rs.1200/-. The selection process includes a written examination and an interview.', 'Colombo, Sri Lanka', '2026-08-07 03:14:34.659533+00', '2026-08-07 03:14:34.659533+00', 28);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (704, 325, 4, 'Station Assistant (Based in Delhi)', false, 'The incumbent will be responsible for managing the operational teams in Division Name Departure Terminal, Arrival, Ramp service and all other services relevant to flight Airport Service Delivery -Overseas movement to achieve on-time performance and to achieve prescribed customer service standards while controlling expenditure and ensuring that the handling agent provides agreed services and sufficient facilities. Key responsibilities will include: Achieve assigned operational performance targets to contribute towards succeeding corporate objectives. Ensure that the GHA provides services and supplies according to company standards and requirements to maintain the expected service levels and to maintain customer satisfaction by resolving problems. Manage planned and unplanned disruptions efficiently to minimize passenger inconvenience and provide passengers with up to date delay information. Control station expenditure, maintain station logs, performance records and ensure proper administration of the station in consultation with Station Head/Line stations manager/ Country Manager. Establish and maintain healthy relationships with local organizations including regulators of the country to sustain service standards and to manage any legal implications arising from handling issues in consultation with head office and maintain an uninterrupted channel of communication with Station Head/ Manager Line Stations/ Country management to enhance productivity and service levels. Investigate and respond promptly to passenger complaints in consultation with Station Head/Manager Customer affairs and/or Manager Line Stations and resolve the complaint and ensure utmost satisfaction of the customer. Ensure that the GHA provides services according to the agreed SLA, in line with company standards, Obtain maximum services from the handling agent in a friendly yet persuasive manner, to provide customer satisfaction/delight to achieve/maintain company service standards and identify / resolve problems arising from weak areas of the handling agent to maintain expected 85% of service level standards. Requirements: Pass Senior Secondary School level Examination. A credit or equivalent pass for English in Secondary School Level Examination. 02 years of work experience in Airport Service. Proficiency in written & spoken English is essential. Be an Indian Citizen. The upper age limit should be 30 years as at the closing date 10th August 2026. Please upload your CV along with the educational certificates and the documentary proof for work experience. Employment will be offered on fixed term contract.', 'Delhi, India', '2026-08-07 03:14:34.662348+00', '2026-08-07 03:14:34.662348+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (705, 297, 4, 'Management Assistant, Assistant Registrar, Sub Warden, Audit Assistant, Driver, Electrician, Works Aide, Chair Professor, Lecturer, Senior Lecturer', false, 'The Buddhist & Pali University of Sri Lanka invites applications from qualified candidates for the following vacancies: Academic positions including Chair Professor, Senior Lecturer, Lecturer (Probationary/Unconfirmed/Senior Lecturer Grade II/I), and Temporary Lecturer in Buddhist Studies, Pali, Sanskrit, English, Japanese, French, Hindi, and Chinese languages. Non-academic positions include Assistant Registrar, Sub Warden, Audit Assistant, Management Assistant, Driver, Electrician, and Works Aide. Qualifications and salary scales are specified per UGC circulars. Applications must be submitted by 2026.08.10. Benefits include EPF/ETF contributions and medical scheme participation.', 'Homagama, Sri Lanka', '2026-08-07 03:14:34.663713+00', '2026-08-07 03:14:34.663713+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (706, 299, 4, 'Management Service Officer (Limited)', false, '', 'Sri Lanka', '2026-08-07 03:14:34.664369+00', '2026-08-07 03:14:34.664369+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (707, 420, 4, 'Senior Key Account Manager (GM)', false, 'Brand Strategy Development: Develop and implement comprehensive brand strategies aligned with business objectives. Define and maintain brand guidelines to ensure consistency across all touchpoints. Market Analysis: Conduct market research to understand customer preferences, competitor activities, and industry trends. Analyze data to identify opportunities for brand growth and differentiation. Campaign Management: Plan and execute innovative marketing campaigns across digital and traditional platforms. Collaborate with creative teams to deliver high-quality content that resonates with target audiences. Cross-Functional Collaboration: Work closely with product, sales, and marketing teams to align brand initiatives with business goals. Partner with external agencies for design, advertising, and media planning. Performance Tracking: Monitor and report on campaign performance metrics, using insights to optimize future initiatives. Manage the brand budget effectively, ensuring all activities deliver maximum ROI. Customer Engagement: Foster a strong connection between the brand and its target audience through storytelling and innovative strategies. Champion customer feedback to refine brand messaging and offerings. Candidate Requirements: Ability to build and maintain strong relationships with key clients. Excellent interpersonal and communication skills to foster trust and collaboration. Strong persuasion and negotiation skills to close deals effectively. Ability to upsell and cross-sell products or services. Understanding of industry trends, competitor activity, and market dynamics. Ability to align business strategies with customer needs. Ability to work in a fast-paced, ever-changing business environment. Resilience in handling client challenges and meeting revenue targets.', 'Colombo, Western Province', '2026-08-07 03:14:42.154358+00', '2026-08-07 03:14:42.154358+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (708, 280, 4, 'Walk In Interview | Service Desk Analyst (Trainee)', false, 'Provide first-level support by troubleshooting hardware, software, and network issues. Log, track, and resolve incidents and service requests within agreed timeframes. Communicate with users to understand issues and provide timely updates on resolutions. Escalate complex issues to the appropriate teams when necessary. Bachelor’s degree in related fields (recent graduates). Strong analytical and problem-solving skills. Good communication and interpersonal abilities. Willingness to work on a roster basis, including night shifts. Up to 2 years of relevant experience in a similar role or domain.', 'Colombo, Western Province', '2026-08-07 03:14:42.158057+00', '2026-08-07 03:14:42.158057+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (709, 280, 4, 'Walk In Interviews | Networking (Fresh Graduates)', false, 'Start Your Career in Infrastructure Services. Are you a fresh IT graduate looking to start your career in IT Infrastructure Services? Join HCLTech and be part of a global organization where you can learn, grow, and build a strong technical foundation. Who Can Apply: Fresh graduates. Completed a 3-year or 4-year IT-related Bachelor''s degree. Ability to submit official academic transcripts. Passionate about technology, learning, and career growth. Strong communication skills with a positive attitude. Basic knowledge of computer systems, networking concepts, and MS Office tools. Added Advantage: Understanding of ITIL/ITSM processes. Knowledge of any programming or scripting language.', 'Colombo, Western Province', '2026-08-07 03:14:42.161508+00', '2026-08-07 03:14:42.161508+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (710, 280, 4, 'Service Desk Analyst', false, 'Provide first-level support by troubleshooting hardware, software, and network issues. Log, track, and resolve incidents and service requests within agreed timeframes. Communicate with users to understand issues and provide timely updates on resolutions. Escalate complex issues to the appropriate teams when necessary. Bachelor’s degree in related fields (recent graduates). Strong analytical and problem-solving skills. Good communication and interpersonal abilities. Willingness to work on a roster basis, including night shifts. Up to 2 years of relevant experience in a similar role or domain.', 'Colombo, Western Province', '2026-08-07 03:14:42.165432+00', '2026-08-07 03:14:42.165432+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (711, 280, 4, 'Walk In Interviews | Graduate Engineer Analyst - Infrastructure Services (Data Centre) (Fresh Graduates)', false, 'Start Your Career in Infrastructure Services. Are you a fresh IT graduate looking to start your career in IT Infrastructure Services? Join HCLTech and be part of a global organization where you can learn, grow, and build a strong technical foundation. Who Can Apply: Fresh graduates. Completed a 3-year or 4-year IT-related Bachelor''s degree. Ability to submit official academic transcripts. Passionate about technology, learning, and career growth. Strong communication skills with a positive attitude. Basic knowledge of computer systems, networking concepts, and MS Office tools. Added Advantage: Understanding of ITIL/ITSM processes. Knowledge of any programming or scripting language.', 'Colombo, Western Province', '2026-08-07 03:14:42.168227+00', '2026-08-07 03:14:42.168227+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (712, 280, 4, 'Walk In Interview | Service Desk - Infrastructure Services', false, 'The Service Desk Role serves as the first point of contact for customers, helping them resolve IT-related issues and ensuring a positive support experience. In this role, you will: Diagnose, analyze, troubleshoot, and resolve IT incidents and service requests. Provide first-level support through voice and ticketing systems. Work closely with global teams to ensure timely issue resolution. Be part of a dynamic Help Desk team supporting enterprise environments. Comprehensive technical training will be provided to all candidates joining this role. Ideal Candidate Profile: Both IT and Non-IT graduates are welcome. Applicants must possess a completed degree qualification. Please note that undergraduate candidates will not be considered for this position. 2-5 Years of Experience. Strong communication skills. Passion for technology, troubleshooting, and helping customers. Experience in Service Desk, Help Desk, or IT Support roles is an added advantage.', 'Colombo, Western Province', '2026-08-07 03:14:42.170391+00', '2026-08-07 03:14:42.170391+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (713, 280, 4, 'Walk In Interview | Graduate Engineering (Fresh Graduates)', false, 'We are looking for passionate and energetic fresh graduates to join our Infrastructure Services team specializing in IT Support and ServiceNow. This role is ideal for individuals beginning their IT career and eager to gain hands-on exposure in ServiceNow, ITIL concepts, and customer support operations. Job Overview: Developing basic form customizations, business rules, and client scripts in ServiceNow; Applying a foundational understanding of ITIL and ITSM concepts in daily tasks; Handling customer technical support queries with professionalism, clarity, and accuracy; Ensuring timely resolution of issues while providing high-quality, customer-focused support; Communicating effectively with users of varying technical backgrounds; Educating customers on available support options and explaining the steps taken to resolve issues; Collaborating with team members, escalating issues as required, and following documented processes to resolve service-related concerns. Required Skills & Competencies: Strong communication, presentation, and writing skills; Excellent troubleshooting abilities with a consultative approach; Basic understanding of ITSM / ITIL / CMDB concepts; Fundamental JavaScript knowledge; Familiarity with ServiceNow (added advantage). Educational Qualifications: Fresh graduates who have completed a 3-year or 4-year IT-related degree; Official transcripts must be provided as proof of completion.', 'Colombo, Western Province', '2026-08-07 03:14:42.17244+00', '2026-08-07 03:14:42.17244+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (714, 280, 4, 'Walk In Interview | Help Desk (Non - IT Degree Welcome)', false, 'The Service Desk Analyst serves as the first point of contact for customers, helping them resolve IT-related issues and ensuring a positive support experience. In this role, you will: Diagnose, analyze, troubleshoot, and resolve IT incidents and service requests. Provide first-level support through voice and ticketing systems. Work closely with global teams to ensure timely issue resolution. Be part of a dynamic Help Desk team supporting enterprise environments. Comprehensive technical training will be provided to all candidates joining this role. Ideal Candidate Profile: Both IT and Non-IT graduates are welcome. Applicants must possess a completed degree qualification. Please note that undergraduate candidates will not be considered for this position. Non-IT graduates with qualifications in Management, Business Administration, Arts, International Business Management, General Degrees, Marketing, Physical Sciences, Hospitality Management, English/Communication, Airline & Ticketing, or related fields will be considered. Less than 12 months of work experience. Strong communication skills with a customer-focused mindset. Willingness to work flexible shift schedules, including night shifts, based on client requirements. Added Advantage: ITIL & ITSM process understanding, Knowledge in any programming language.', 'Colombo, Western Province', '2026-08-07 03:14:42.174398+00', '2026-08-07 03:14:42.174398+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (715, 280, 4, 'Walk In Interview | Service Desk Infrastructure Services (Fresh Graduates - Non IT Students)', false, 'The Service Desk Role serves as the first point of contact for customers, helping them resolve IT-related issues and ensuring a positive support experience. In this role, you will: Diagnose, analyze, troubleshoot, and resolve IT incidents and service requests. Provide first-level support through voice and ticketing systems. Work closely with global teams to ensure timely issue resolution. Be part of a dynamic Help Desk team supporting enterprise environments. Comprehensive technical training will be provided to all candidates joining this role. Ideal Candidate Profile: Both IT and Non-IT graduates are welcome. Applicants must possess a completed degree qualification. Please note that undergraduate candidates will not be considered for this position. 0-1 Years of Experience. Completed IT/Non-IT Degree with Transcript. Strong communication skills. Passion for technology, troubleshooting, and helping customers.', 'Colombo, Western Province', '2026-08-07 03:14:42.176143+00', '2026-08-07 03:14:42.176143+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (716, 421, 4, 'Senior Lecturer - Fashion Design', false, 'Deliver high-quality teaching at undergraduate and postgraduate levels. Supervise student research, dissertations, projects, and theses. Conduct quality research and contribute to scholarly publications or professional practice. Participate in academic planning, quality assurance, and departmental development. Mentor students and support their academic and professional growth. Contribute to university committees, research initiatives, and community engagement activities. Qualifications: Bcs, Msc, Mphil or a Phd in the relevant discipline from a recognized university. Candidates with degrees from the UK, Australia or North America will be given preference. Relevant years of teaching and research (or creative practice) in higher education. A robust and continuous portfolio of high-impact research publications in recognized international journals or a distinguished record of professional industry projects. Benefits: Competitive and negotiable salary based on qualifications and experience. Two-year renewable employment contract. One annual round-trip airfare between your home country and Dhaka. Free furnished accommodation in Dhaka. Pick and drop facilities between residence and campus. International health and medical insurance coverage. Opportunities for research collaboration, professional development, and international academic networking.', 'Dhaka, Bangladesh', '2026-08-07 03:14:42.178463+00', '2026-08-07 03:14:42.178463+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (731, 317, 4, 'Laboratory Attendant, Electrician, Driver', false, '', 'Sri Lanka', '2026-08-07 03:15:37.839043+00', '2026-08-07 03:15:37.839043+00', 1);
