INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (730, 317, 4, 'Programmer/Systems Analyst', false, '', 'Sri Lanka', '2026-08-07 03:15:37.838384+00', '2026-08-07 03:15:37.838384+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (734, 427, 4, 'Logistics Assistant', false, 'Create Purchase Orders (POs) for local and international vendors. Coordinate payment arrangements for local and overseas suppliers. Arrange marine insurance documentation for shipments. Prepare and maintain logistics reports and related records. Organize and maintain payment documents and supporting records. Perform other logistics and administrative duties as assigned. Candidate must have a Diploma in Supply Chain Management or Logistics, minimum 1-2 years of experience in logistics or supply chain operations, proficiency in Microsoft Office applications, good communication and coordination skills, and ability to work independently and meet deadlines. An attractive remuneration package in line with market rates, along with other benefits, awaits the selected candidate.', 'Katunayaka', '2026-08-07 03:15:53.758562+00', '2026-08-07 03:15:53.758562+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (735, 249, 4, 'Office Assistant - Male', false, 'Assist with daily office and administrative tasks. Handle filing, photocopying, and document management. Deliver and collect documents when required. Drive company vehicles for official duties. Support other office operations as assigned by management. Male candidate. Valid Sri Lankan driving licence for moter bike (mandatory). Responsible, punctual, and trustworthy. Good communication skills. Previous experience in a similar role is an added advantage. Applicants residing in or around Colombo are preferred.', 'Colombo 06, Sri Lanka', '2026-08-07 03:15:53.764081+00', '2026-08-07 03:15:53.764081+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (736, 249, 4, 'Inventory Specialist', false, '3+ years of proven experience in inventory handling and stock control. Previous work experience in stores, warehouse operations, or inventory management. Ability to maintain accurate stock records and conduct regular stock counts. Good knowledge of inventory receiving, issuing, and storage procedures. Ability to identify and resolve inventory discrepancies. Willingness and ability to work at any company location as required. Good organizational and time management skills. Basic computer literacy, including Microsoft Excel and inventory software. Ability to work independently and as part of a team. Strong attention to detail and accuracy. Experience in handling inventory across multiple locations will be an added advantage. Flexibility to travel between company branches and sites when required.', 'Colombo 6', '2026-08-07 03:15:53.767679+00', '2026-08-07 03:15:53.767679+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (737, 249, 8, 'Intern Lawyer', false, 'Assist with day-to-day legal activities and independently manage assigned legal documentation tasks. Conduct legal research and prepare summaries on relevant laws and regulations. Assist in drafting and reviewing legal documents, agreements, and letters. Maintain and organize legal files and records. Support in preparing documents for legal proceedings and meetings. Coordinate with external legal when needed. Attend meetings and take notes as needed. Assist with compliance-related documentation and administrative legal tasks. Currently pursuing or recently completed an LLB or legal studies. Good knowledge of legal concepts and documentation. Strong research, analytical, and communication skills. Good attention to detail and ability to maintain confidentiality. Proficiency in MS Office applications. Willingness to learn and gain practical legal experience.', 'Colombo 06, Sri Lanka', '2026-08-07 03:15:53.770293+00', '2026-08-07 03:15:53.770293+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (738, 428, 4, 'Junior Executive | Executive - Data Analyst (Recoveries)', false, 'Generate and maintain daily, weekly, and monthly MIS reports on recovery performance, overdue portfolios, and collection efficiency for the Recoveries Department. Analyze NPL (Non-Performing Loan) trends, ageing buckets, and support strategic recovery decisions by analysed data. Maintain and update recovery databases/dashboards, ensuring accuracy of collection data, write-offs, and recovery case statuses. Coordinate with branch/regional recovery officers to consolidate field-level recovery data and reconcile discrepancies. Support management by providing analyzed recovery data and preparing reports and presentations for recovery review meetings. Minimum 1-2 years’ experience in MIS, data analytics, dashboard management. Previous experience in recoveries/collections within a bank or NBFI will be an advantage. Bachelor''s degree in Finance, Statistics, IT, Business Management, or a related field. Strong proficiency in Excel (pivot tables, macros, dashboards) and working knowledge of SQL/Power BI or similar reporting tools. Strong analytical, numerical, and communication skills with high attention to detail and ability to meet reporting deadlines.', 'Colombo 8', '2026-08-07 03:15:53.778795+00', '2026-08-07 03:15:53.778795+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (739, 249, 4, 'Personal Driver - Managing Director', false, 'Rush Lanka Group is looking for an experienced, reliable, and trustworthy Personal Driver for our Managing Director. The ideal candidate must be professional, discreet, and committed to ensuring safe and comfortable travel at all times. Requirements: Age between 40-50 years, healthy and physically fit, responsible, punctual, and trustworthy, good driving experience with a valid driving license, well-groomed with a professional attitude, knowledge of routes in Colombo and around the island is an advantage, ability to maintain confidentiality and handle responsibilities with discretion, candidate should be willing to stay and work as required. Benefits: Accommodation provided, immediate joining required.', 'Colombo 6, Sri Lanka', '2026-08-07 03:15:53.781769+00', '2026-08-07 03:15:53.781769+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (740, 249, 4, 'Junior Architect', false, 'Prepare architectural drawings, layouts, and design modifications independently. Prepare and modify drawings using AutoCAD, Revit, or other design software. Support the preparation of 3D models, presentations, and design concepts. Coordinate with engineers, consultants, and project teams. Assist with site visits and monitor drawings and construction details. Review drawings and ensure accuracy and compliance with project requirements. Maintain project documentation and update drawings when required. Requirements: Degree/Diploma in Architecture or related field. Good understanding of architectural drawings and construction details. Knowledge of AutoCAD, Revit, and architectural design software. Creative thinking with good attention to detail. Good communication and interpersonal skills. Ability to work under deadlines and manage multiple tasks.', 'Colombo 06, Sri Lanka', '2026-08-07 03:15:53.784089+00', '2026-08-07 03:15:53.784089+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (741, 249, 4, 'Store Keeper', false, 'Receive, inspect, and record incoming stock. Organize and maintain construction site store for easy access. Keep accurate inventory records and perform regular stock counts. Ensure proper storage conditions and safety procedures. Prepare stock reports and assist in stock replenishment. Coordinate with site teams and suppliers to meet material needs. Maintain cleanliness and orderliness of the store area. Issue materials and tools to site teams as per request and proper documentation. Proven experience as a Store Keeper or in a similar role, preferably in a construction site. Good organizational and record-keeping skills. Ability to operate inventory management software. Strong attention to detail and accuracy. Physical stamina to handle manual work. Excellent communication skills. Knowledge of construction materials, tools, and operations.', 'Colombo 06, Sri Lanka', '2026-08-07 03:15:53.785896+00', '2026-08-07 03:15:53.785896+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (742, 429, 4, 'Branch Officer - Jaffna Branch', false, 'Pass G.C.E. A/L Examination. Competency in MS Office. Age between 22-32. Marketing oriented personality. Should be able to communicate in both Tamil & English languages. The selected candidate will take part in marketing promotional campaigns on the request by marketing division. Should be able to travel on promotional work. Day to day branch operations.', 'Jaffna, Sri Lanka', '2026-08-07 03:15:53.787397+00', '2026-08-07 03:15:53.787397+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (744, 212, 5, 'Data Entry Operator - (Part Time) Works at Home (Online)', true, 'Sri Lankan Projects, Data Entry Works, Online Data Submission, Copy Typing, Simple Typing. Start Your Work Within 30 Minutes. Income: Daily - Rs. 500 – 2,000, Monthly - Rs. 65,000+ (Depends on your work performance). Facilities: Full Sinhala / English Guidelines (Call or Email), Daily Job Options (Typing, Data Entry & Data Submission), Work From Home – Flexible Working Hours, Payments via Bank Deposit / eZ Cash, 24×7 Support. Qualifications: Basic IT and Email knowledge, open to any male/female, can work from anywhere in the island. Suitable for: Full-Time/Part-Time Employees, Job Seekers, Housewives, School Leavers, University Students, anyone looking for extra income. Requirements: Computer, Laptop or Smartphone/iPhone, Internet Connection, at least 1 hour per day.', 'Kaduwela, Colombo, Sri Lanka', '2026-08-07 03:16:12.035794+00', '2026-08-07 03:16:12.035794+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (745, 431, 4, 'Female Aerobic Trainer', false, 'We''re hiring a certified female fitness trainer to conduct group aerobic fitness classes in a fun, safe, and inspiring environment. Responsibilities include conducting engaging and energetic group aerobic classes, ensuring proper exercise techniques and participant safety, motivating members to achieve their fitness goals, creating a welcoming and positive class atmosphere, and delivering an outstanding fitness experience every session. Requirements include NVQ Level 4 in Fitness (or equivalent), experience in conducting group fitness or aerobic classes, an Advanced Certificate in Aerobics/Group Exercise is a valuable addition, excellent communication and motivational skills, and a positive attitude with a passion for empowering others. Benefits include an attractive salary package, performance incentives, a friendly and supportive work environment, a modern fitness facility, and career growth and continuous learning opportunities.', 'Dehiwala, Colombo', '2026-08-07 03:16:12.039608+00', '2026-08-07 03:16:12.039608+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (746, 160, 4, 'මුදල් අයකැමි - බම්බලපිටිය', false, 'සුමති හෝල්ඩින්ස් ආයතනයේ ප්‍රධාන ශාඛාවට මුදල් අයකැමිවරයෙකු ඉක්මනින් බඳවා ගැනේ. සුදුසුකම්: වයස අවුරුදු 30 ට අඩු පිරිමි පුද්ගලයෙකු වීම, බම්බලපිටිය අවට හෝ බම්බලපිටියට මිනිත්තු 30 ක දුරකින් ස්ථීර පදිංචිකරුවෙකු වීම, අ.පො.ස. උසස් පෙළ සමත්, ගිණුම් සම්බන්ධ පාඨමාලාවක් හදාරා තිබීම (Finance or related field), යතුරු පැදියක් තිබීම, සේවා මුර (Shifts) අනුව සේවය කිරීමේ හැකියාව (දහවල් කාලයේ පමණයි).', 'Colombo 3, Sri Lanka', '2026-08-07 03:16:12.041468+00', '2026-08-07 03:16:12.041468+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (747, 426, 4, 'Nursing Assistant and Caregivers', false, 'We are looking for dedicated and compassionate Nursing Assistants and Caregivers to join our team, providing essential care and support to patients at Siva Home Care and Medicals. Responsibilities: Assisting patients with daily activities (bathing, dressing, and feeding). Monitoring vital signs and reporting changes to nurses. Helping with patient mobility and transfers. Maintaining a clean and safe patient environment. Documenting patient care activities. Requirements: Good communication skills (English & Sinhala/Tamil preferred). Ability to work independently and as part of a team. Physical ability to lift and move patients. Compassionate and patient-focused attitude. Experience in a healthcare setting is a plus. NVQ Level 4 or 3 qualification in Nursing or a related field (or willingness to obtain). Benefits: Competitive salary. Annual performance increment. Opportunity for a long-term career.', 'Colombo 6, Sri Lanka', '2026-08-07 03:16:12.045491+00', '2026-08-07 03:16:12.045491+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (748, 432, 4, 'Kitchen Helper', false, 'Kitchen Helper – Immediate Vacancy (Galle). Required qualifications: Ability to work responsibly and enthusiastically. Ability to work with a team. Kitchen service experience is an advantage (not mandatory). Priority for those who can join immediately. Food & Accommodation facilities are provided. Work location: Galle.', 'Ahangama, Galle, Sri Lanka', '2026-08-07 03:16:12.047141+00', '2026-08-07 03:16:12.047141+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (749, 9, 4, 'Graphic Designer', false, 'Please go through the attached advertisement. Sending your CV via WhatsApp is mandatory.', 'Wellampitiya, Colombo', '2026-08-07 03:16:12.048153+00', '2026-08-07 03:16:12.048153+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (750, 421, 4, 'Lecturer / Assistant Lecturer - Business Management', false, 'Deliver high-quality teaching at undergraduate and postgraduate levels. Supervise student research, dissertations, projects, and theses. Conduct quality research and contribute to scholarly publications or professional practice. Participate in academic planning, quality assurance, and departmental development. Mentor students and support their academic and professional growth. Contribute to university committees, research initiatives, and community engagement activities. Qualifications: Bcs, Msc, Mphil or a Phd in the relevant discipline from a recognized university. Candidates with degrees from the UK, Australia or North America will be given preference. Relevant years of teaching and research (or creative practice) in higher education. A robust and continuous portfolio of high-impact research publications in recognized international journals or a distinguished record of professional industry projects. Benefits: Competitive and negotiable salary based on qualifications and experience. Two-year renewable employment contract. One annual round-trip airfare between your home country and Dhaka. Free furnished accommodation in Dhaka. Pick and drop facilities between residence and campus. International health and medical insurance coverage. Opportunities for research collaboration, professional development, and international academic networking.', 'Dhaka, Bangladesh', '2026-08-07 03:16:26.95932+00', '2026-08-07 03:16:26.95932+00', 1);
