INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (946, 408, 4, 'Executive - Production (FMCG, Food & Beverages) - Pannala', false, 'Supervise production staff and oversee the daily operations of the organic factory. Assist in factory planning and manage overall production activities to ensure smooth workflow. Monitor and improve production efficiency and effectiveness through continuous process enhancements. Communicate and coordinate with other departments to maintain seamless operational flow. Support audits, inspections, and reporting requirements related to certifications. Maintain accurate records of production, inspection, and traceability documentation. Requirements: Degree in Agriculture or Science. 3 years of experience in operations or production is mandatory. Strong organizational and communication skills. Ability to work independently and collaboratively within a team. Knowledge about coconut-related products is an added advantage. The selected candidate will receive an attractive remuneration package, in keeping with the market standards.', 'Pannala, Sri Lanka', '2026-08-26 01:05:41.782754+00', '2026-08-26 01:05:41.782754+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (947, 520, 4, 'Manager - Regulatory', false, 'This role is responsible for leading and managing Regulatory Affairs activities to ensure full compliance with pharmaceutical regulatory requirements and support business growth through timely product registrations and approvals. The position involves preparing and coordinating regulatory submissions, maintaining regulatory documentation, liaising with regulatory authorities, monitoring regulatory changes, and ensuring compliance with NMRA, GMP, and other applicable pharmaceutical regulatory standards. The role also supports audits and inspections, provides regulatory guidance on product-related documentation, manages regulatory renewals and variations, and drives continuous improvement of regulatory processes while leading and developing the Regulatory team. Qualifications include a Bachelor''s Degree in Science, Pharmacy, or a related discipline (Master''s Degree will be an added advantage), minimum 5 years of experience in Regulatory Affairs within the pharmaceutical industry, strong knowledge of NMRA, GMP, and other applicable pharmaceutical regulatory requirements, proven experience in regulatory submissions, product registrations, renewals, variations, and compliance management, experience in liaising with regulatory authorities and managing regulatory documentation, strong analytical, problem-solving, and decision-making skills, excellent communication, stakeholder management, and organizational abilities, ability to manage multiple priorities and work effectively in a highly regulated environment, and proficiency in Microsoft Office and regulatory management systems/software.', 'Colombo 03, Sri Lanka', '2026-08-26 01:05:41.78709+00', '2026-08-26 01:05:41.78709+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (948, 521, 4, 'Factory Accountant', false, '', 'Walapane', '2026-08-26 01:05:41.789105+00', '2026-08-26 01:05:41.789105+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (949, 521, 4, 'Assistant Manager - Human Resources (Corporate Office)', false, 'Manage day-to-day HR operations and administration. Manage employee relations, grievances, and disciplinary matters. Maintain employee records and HR documentation. Support performance management and employee engagement initiatives. Handle EPF, ETF, gratuity, and other statutory HR matters. Prepare HR reports and manpower-related information. Requirements: Bachelor''s Degree in HRM, Business Administration, or a related field. Professional qualification in HR (CIPM/PQHRM or equivalent) will be an added advantage. 3-5 years of relevant HR experience, preferably in the apparel/manufacturing industry. Good knowledge of Sri Lankan labour laws and HR practices. High level of confidentiality, professionalism, and integrity.', 'Dehiwala', '2026-08-26 01:05:41.791443+00', '2026-08-26 01:05:41.791443+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (950, 522, 4, 'Front of House', false, 'Biling is looking for a warm, confident and professional Front of House team member to join us in Colombo. We''re looking for someone who is fluent in spoken English, naturally warm, friendly and guest focused, has strong communication and listening skills, is attentive and able to anticipate guest needs, confident explaining dishes, drinks and their stories, stays calm and organised during busy service, is reliable, punctual and responsible, works well as part of a team, and is willing to learn and take feedback. Previous restaurant experience is an advantage, but attitude, personality and willingness to learn matter just as much to us.', 'Colombo 2', '2026-08-26 01:25:34.728772+00', '2026-08-26 01:25:34.728772+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (951, 7, 8, 'Intern - Human Resources', false, 'Join MAS Linea Intimo, Biyagama as an Intern - Human Resources. Activewear vertical training and framing is ideal for management or a related field. Critical thinking will help grow your HR expertise in a dynamic environment. Apply now! Apply within 7 calendar days of this advert being published.', 'Biyagama, Sri Lanka', '2026-08-26 01:25:34.739707+00', '2026-08-26 01:25:34.739707+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (952, 523, 4, 'Accounts Assistant', false, '', 'Heiyanthuduwa', '2026-08-26 01:25:34.742059+00', '2026-08-26 01:25:34.742059+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (953, 524, 4, 'Customer Service Representative', false, 'Manage customer orders from order entry to final delivery. Coordinate with customers, logistics partners, warehouses and internal teams. Monitor shipments, stock availability, lead times and delivery schedules. Proactively communicate delays, changes and order status. Maintain accurate ERP records and shipping documentation. Support OTIF, order accuracy and stock reliability targets. Bachelor''s degree or equivalent qualification. Background in Supply Chain / Logistics preferred. 2-5 years'' experience in customer service, order management, logistics or supply chain. Experience working with ERP systems. Fluent written and spoken English is essential. Strong coordination, communication and problem-solving skills.', 'Panadura', '2026-08-26 01:25:34.745519+00', '2026-08-26 01:25:34.745519+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (954, 525, 4, 'Restaurant Vacancies', false, 'We are up-grading & growing. Wanted - Cafe & Lounge Team. Restaurant/Cafe Lounge Supervisors with professional qualifications, good knowledge and previous experience in a similar capacity, good supervisory & sales skills with ability to manage for profitability, knowledge of coffees, teas, other beverages, food dishes etc, excellent PR skills, active with innovative ideas, age group 35-55 years. Restaurant Captains with ala carte restaurant experience in star class hotels. Stewards with ala carte restaurant experience in star class hotels. Stewardesses with ala carte restaurant experience in star class hotels. Sales Girls - Cafe Lounge or Sales Experience. Barista / Ice Cream Dishes / Juice & Smoothie Makers. Cashiers - preferably ladies 20-30 years with/without experience. Preference given to young and active team players committed to the job and looking forward towards career growth. Food and accommodation provided. Trainees considered. Attractive salaries and incentives offered.', 'Negombo', '2026-08-26 01:25:34.751645+00', '2026-08-26 01:25:34.751645+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (955, 526, 8, 'Digital Media Officer | Intern', false, 'We are looking for a dynamic and enthusiastic Digital Media Officer / Intern to join our organization. Requirements: Following a Degree in Marketing, Business Management, or a related field, or a Minimum of one year’s experience in digital media marketing. Excellent communication and interpersonal skills. Fluency in Sinhala and English languages (Fluency in Tamil language will be an added advantage). Basic knowledge of MS Office applications. A strong willingness to learn, adapt, and collaborate within a team environment.', 'Borella', '2026-08-26 01:25:34.754937+00', '2026-08-26 01:25:34.754937+00', 1);
