INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (968, 532, 5, 'Delivery Rider (Part Time)', false, 'Responsibilities: Deliver food orders to customers on time; receive orders and transport them correctly; regularly inspect and maintain the motorcycle; maintain good communication with customers; follow safe driving practices. Qualifications: Age between 18 and 45; must own a motorcycle; must have a valid driving license; knowledge of road signs and traffic rules. Benefits: Monthly salary between Rs. 65,000 and 70,000; 8 days off per month; special salary scale for experience; opportunities for internal promotions; permanent job; free food and beverages during work; accommodation facilities; medical insurance; Rs. 2 million life insurance and special benefits for birthdays, marriages, childbirth, education, parent illness, and natural disasters; attractive salary and many other privileges (conditions apply).', 'Gampaha City, Gampaha, Sri Lanka', '2026-08-28 08:57:35.869746+00', '2026-08-28 08:57:35.869746+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (960, 530, 4, 'Project Manager', false, 'Key Responsibilities: 1. Ensures the efficient and effective coordination/management of the urban NbCS project and all related activities. 2. Designs and manages the monitoring and evaluation of all the work under the urban NbCS project at the macro-level. 3. Researches and makes recommendations for NbCS policies and regulations. 4. Manages all grants under the NbCS project. 5. Assists in coordinating all Public Relations activities of the NBS project. Special Skills Needed: Knowledge of urban nature based solutions; Strong project and time management skills; Strong attention to detail and a passion for research; Adept at managing tasks, planning events, and balancing priorities; Excellent report writing skills. Preferred Qualifications: At least a Bachelor''s degree in Environmental Sciences or a related field; Minimum of 5 years'' experience in environmental field and managing funding in excess of Cdn $5 million; Experience in areas such as environmental analyses, gender equality and human rights highly advantageous; Competence in Microsoft Office suite and any donor management systems; Experience in public speaking and working with government and private sector would be a distinct advantage. Remuneration Package: Includes, inter alia, basic salary, group life and health insurance coverage.', 'St. Andrew, Jamaica', '2026-08-28 04:11:22.925919+00', '2026-08-28 04:11:22.925919+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (961, 530, 4, 'Gender Specialist', false, 'The Gender Specialist will provide technical leadership in ensuring the integration of gender-responsive approaches within the organisation. This includes integrating gender-sensitive NbCS strategies in governance, disaster risk management, community engagement, funding mechanisms, and policy development. Activities Include: Governance and Capacity Building; Gender Gap Assessments and Strategy Development; Assist with Digital Platform Development and Knowledge Sharing; Policy brief Development and Stakeholder Engagement; Stakeholder Training and Consultation; Networking and Partnership Development; Community Engagement. Preferred Qualifications: At least a Master''s degree in Gender studies, Policy, Development Studies, Social Sciences, International development, or a related field; Minimum of 5 years of professional experience in gender analysis, gender mainstreaming, and women''s empowerment, preferably in the context of urban development, policy or environmental sustainability; Proven ability to engage with government agencies, NGOs, community organizations, and marginalized groups on gender-related issues; Familiarity with international frameworks and conventions on gender equality, such as the Beijing Platform for Action, CEDAW and the Sustainable Development Goals; Proficiency in using digital tools for content dissemination and monitoring. Remuneration Package: Includes, inter alia, basic salary, group life and health insurance coverage.', 'St. Andrew, Jamaica', '2026-08-28 04:11:22.932052+00', '2026-08-28 04:11:22.932052+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (962, 530, 7, 'Communications Consultant', false, 'Key Responsibilities: To craft a communications strategy to increase the awareness of gender responsive NbCS policies and regulations amongst key Jamaican stakeholders. Key Objectives: 1. Increase public awareness about the existence of the NbCS project, its objectives and its importance. 2. Foster a deeper understanding among key stakeholders and the public about the use of NbCS and its role in increasing resilience to climate change and disaster impacts in urban areas of Jamaica through gender responsive solutions. 3. Encourage participation and involvement in the implementation and support of the gender responsive NBS solutions. Specific Objectives: Prepare clear, consistent, accessible, engaging and effective communication geared towards the public, targeted persons and key stakeholders; Highlight the tangible impact and positive outcomes of the NbCS solutions through compelling success stories, jingles, case studies, and data-driven evidence; Facilitate dialogue, collaboration and partnerships between stakeholders to maximize collective efforts and resources in addressing NbCS solutions; Empower communities to take ownership of their climate change resilience and disaster management projects by providing them with the information, tools and resources to participate gender responsive NBS solutions; Create a logo and effective branding, marketing and social media strategy for the project. Preferred Qualifications: At least a Bachelor''s degree in Media and Communications, Marketing or related field; Minimum of 5 years of professional experience preferably in crafting media and marketing strategies in the context of urban development, policy or environmental sustainability; Proven ability to engage with government agencies, NGOs, community organizations and marginalized groups on gender-related issues. Remuneration Package: A flat rate will be paid per consultant hours/days and agreed reimbursable expenses will be covered.', 'St. Andrew, Jamaica', '2026-08-28 04:11:22.934752+00', '2026-08-28 04:11:22.934752+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (963, 531, 4, 'Accounts Assistant', false, 'A dedicated Accounts Assistant (Male/Female) is urgently required for the accounts department of a leading supermarket located in Nittambuwa. Qualifications & Requirements: Passed G.C.E. Advanced Level (A/L), Preferred in Commerce or Mathematics streams (Biological Science stream applicants may also apply), Basic knowledge of accounting and a commitment to learning new skills, Ability to work with responsibility and enthusiasm. Salary & Benefits: Monthly Salary: Rs. 50,000 – Rs. 60,000, Food and accommodation facilities provided, Entitled to 4 days off per month. Working Hours: 8:30 AM to 10:30 PM.', 'Nittambuwa, Gampaha', '2026-08-28 08:57:35.84972+00', '2026-08-28 08:57:35.84972+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (964, 33, 5, 'Data Entry Operators - (Online Part Time) Works at Home', true, 'Data entry operator role working from home. Requires basic IT knowledge and email only. Can work from home from anywhere in the island. Choose job categories and work at convenient times. Can use a computer, laptop, or smartphone. Minimum one hour per day is sufficient. Open to employed individuals, unemployed, homemakers, school leavers, university students, and anyone seeking extra income. Apply via the employer website link; they will contact you within 15 minutes.', 'Nugegoda, Colombo', '2026-08-28 08:57:35.861589+00', '2026-08-28 08:57:35.861589+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (965, 532, 5, 'Delivery Rider (Part Time)', false, 'Responsibilities: Deliver food orders to customers on time, receive orders and transport them correctly, regularly inspect and maintain the motorcycle, maintain good communication with customers, follow safe driving practices. Qualifications: Age between 18 and 45, must own a motorcycle, must have a valid driving license, knowledge of road signs and traffic rules. Benefits: Monthly salary between Rs. 65,000 and 70,000, 8 days off per month, special salary scale for experience, opportunities for internal promotions, permanent job, free food and drinks during work, accommodation facilities, medical insurance, life insurance of Rs. 2 million, special benefits for birthdays, weddings, childbirth, education, parent illness, and natural disasters.', 'Kotikawatta, Colombo', '2026-08-28 08:57:35.864651+00', '2026-08-28 08:57:35.864651+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (966, 533, 4, 'Cleaning Staff', false, 'Responsibilities: Keep the restaurant premises clean and hygienic, clean toilets/washrooms, wash plates, glasses, cups, cutlery and other utensils used by customers, keep utensils and equipment clean and tidy, properly use cleaning equipment and materials, carry out daily cleaning tasks on time, support maintaining cleanliness and hygiene standards of the restaurant. Qualifications: Previous experience in cleaning/restaurant field is a special qualification, good attention to cleanliness and hygiene, ability to work responsibly and efficiently, ability to work collaboratively with a team, report to work on time and perform assigned duties properly. Benefits: Attractive salary, accommodation facilities, duty meals, EPF/ETF, opportunities for professional development, friendly work environment.', 'Kurunegala City, Sri Lanka', '2026-08-28 08:57:35.866952+00', '2026-08-28 08:57:35.866952+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (967, 534, 4, 'Logistics Assistant', false, 'Join our team and play a key role in ensuring accurate, compliant, and timely product deliveries while maintaining the highest standards of customer service and operational excellence. Send your CV to careers@rockland.lk with the subject line: "Logistics Assistant - Hanwella"', 'Hanwella, Colombo, Sri Lanka', '2026-08-28 08:57:35.868386+00', '2026-08-28 08:57:35.868386+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (969, 533, 4, 'Chinese cook', false, 'Athugalpura Gemigedara (Pvt) Ltd is hiring experienced chefs for the position of Chinese Cook (Commis I / Commis II). Applicants should have knowledge of Chinese cuisine and the ability to work efficiently in a fast-paced kitchen environment. Qualifications: Minimum 1 year of service experience in a Chinese Cook (Commis I / Commis II) position; good knowledge of Chinese cuisine; experience in wok cooking, food preparation, and plating; ability to work harmoniously and responsibly with a team; adherence to cleanliness and food hygiene standards; ability to work efficiently in a fast-paced service environment. Benefits: attractive salary, accommodation facilities, duty meals, EPF/ETF, opportunities for professional development, and a friendly working environment.', 'Kurunegala City, Sri Lanka', '2026-08-28 08:57:35.872056+00', '2026-08-28 08:57:35.872056+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (970, 532, 5, 'Delivery Rider (Part Time) - Kirillawala', false, 'Responsibilities: Deliver food orders to customers on time, receive orders and transport them correctly, regularly check and maintain the motorcycle, maintain good communication with customers, follow safe driving practices. Qualifications: Age between 18 and 45, must own a motorcycle, must have a valid driving license, knowledge of road signs and traffic laws. Benefits: Monthly salary between Rs. 65,000 and 70,000, 8 days off per month, special salary scale for experience, opportunities for internal promotions, permanent job, free food and drinks during work, accommodation facilities, medical insurance, life insurance of Rs. 2 million and special benefits for birthdays, marriages, childbirth, education, parent illness and natural disasters, attractive salary and many other privileges (conditions apply).', 'Kiribathgoda, Gampaha', '2026-08-28 08:57:35.873667+00', '2026-08-28 08:57:35.873667+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (971, 130, 4, 'Client Relations Executive', false, 'Join Christ International Education Consultants, an established education consultancy with 12+ years of experience. Responsibilities include identifying new clients and building relationships, contacting students and parents directly and by phone, providing information on foreign education opportunities and courses, identifying new leads and converting them into successful clients, conducting regular follow-ups with clients, achieving monthly and annual sales/student recruitment targets, participating in marketing events, seminars and promotional activities, and providing initial support for students'' admission process. Qualifications: Minimum GCE Advanced Level (A/L) qualification, excellent verbal and written communication skills, confident, friendly and professional personality, strong interpersonal and relationship-building skills, sales-oriented mindset with ability to achieve targets, good follow-up and negotiation skills, basic computer literacy and knowledge of Microsoft Office, ability to work independently and as part of a team, willingness to learn and develop knowledge of international education. 1+ year of experience in sales/marketing/customer service/education consultancy is an advantage. Benefits include attractive salary package and performance-based commissions and incentives.', 'Colombo 03, Sri Lanka', '2026-08-28 08:57:35.875514+00', '2026-08-28 08:57:35.875514+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (972, 212, 5, 'Data Entry Operator', true, 'Data Entry Works, Online Data Submission, Copy Typing, Simple Typing. Start Your Work Within 30 Minutes. Income: Daily - Rs. 500 – 2,000, Monthly - Rs. 65,000+ (Depends on your work performance). Benefits: Full Sinhala / English Guidelines (Call or Email), Daily Job Options (Typing, Data Entry & Data Submission), Work From Home – Flexible Working Hours, Payments via Bank Deposit / eZ Cash, 24×7 Support. Qualifications: Basic IT and Email knowledge, open to any male/female, can work from anywhere in the island. Suitable for Full-Time/Part-Time Employees, Job Seekers, Housewives, School Leavers, University Students, anyone looking for extra income. Requirements: Computer, Laptop or Smartphone/iPhone, Internet Connection, at least 1 hour per day.', 'Kalmunai, Ampara, Sri Lanka', '2026-08-28 08:57:35.877369+00', '2026-08-28 08:57:35.877369+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (973, 479, 4, 'කොමිනිකේෂන් සේවිකාවන්', false, 'හෝමාගම පමුක පෙලේ කොමිනිකේෂන් ආයතනයක් සඳහා සේවිකාවන් අවශ්‍යයි. ෆොටෝකොපි යන්ත්‍ර ක්‍රියාකරවීමේ දැනුම ඇති අය විශේෂයි. (පුහුණු / නුපුහුණු).', 'Homagama, Colombo, Sri Lanka', '2026-08-28 08:59:39.52705+00', '2026-08-28 08:59:39.52705+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (974, 535, 4, 'Office Clerk', false, 'Perform general office clerical duties, maintain and organize files and records, assist with administrative tasks as required, handle correspondence and communication efficiently. Requirements: Minimum 06 months of experience in a similar role, age between 21–35 years, excellent computer literacy with proficiency in MS Office applications, good communication skills in English and Sinhala, willingness to work on a shift basis (7:00 AM – 7:00 PM), male & female candidates can apply. Benefits: attractive remuneration package & incentives that are above market standards.', 'Colombo 03, Sri Lanka', '2026-08-28 08:59:39.534059+00', '2026-08-28 08:59:39.534059+00', 1);
