INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (976, 467, 4, 'General Manager', false, 'Manage daily club operations, lead and motivate the team, ensure excellent customer service, coordinate reception, housekeeping and maintenance, oversee memberships and daily sales, organize club activities and events, maintain operational standards and SOPs, coordinate with accounting and management, solve operational issues quickly and efficiently. Requirements: Previous management experience in hospitality, fitness clubs, sports clubs or hotels, strong leadership and communication skills, good spoken and written English, computer literacy (Microsoft Office / Google Workspace), highly organized and responsible, ability to work independently and make decisions, positive attitude and strong customer service mindset. We Offer: Competitive salary, performance-based bonuses, opportunity to grow within the GOOD STORY Group, friendly international working environment, long-term career development, work in one of the fastest-growing lifestyle projects in Southern Sri Lanka.', 'Ahangama, Galle, Sri Lanka', '2026-08-28 08:59:39.53861+00', '2026-08-28 08:59:39.53861+00', 1);
INSERT INTO public.job_post (id, employer_id, job_type_id, job_role, is_remote, job_description, location, created_at, updated_at, no_of_vacancies) VALUES (977, 535, 4, 'Office Clerk', false, 'Perform general office clerical duties. Maintain and organize files and records. Assist with administrative tasks as required. Handle correspondence and communication efficiently. Requirements: Minimum 06 months of experience in a similar role, age between 21–35 years, excellent computer literacy with proficiency in MS Office applications, good communication skills in English and Sinhala, willingness to work on a shift basis (7:00 AM – 7:00 PM). Male & Female candidates can apply. Benefits: attractive remuneration package & incentives that are above market standards.', 'Colombo 03, Sri Lanka', '2026-08-28 08:59:39.540863+00', '2026-08-28 08:59:39.540863+00', 1);
